WordHunterWoW_QuestEN = WordHunterWoW_QuestEN or {}
WordHunterWoW_QuestEN[30477] = { title = "A Gift For Haohan", description = "Haohan Mudclaw is the big boss of the Tillers union and the richest guy in the Valley! He's been nice to let me stay here, so I want to do something nice for him.\n\nHe likes expensive stuff, like ruby shards, but I don't have a lot of money, so I need to get him something else.\n\nI know! I've seen a great big fish in Cattail Lake! We should get one of its teeth as a gift!", objectives = "" }
WordHunterWoW_QuestEN[30478] = { title = "A Gift For Jogu", description = "Sometimes I feel sad for Jogu. He's the only jinyu around, and I don't think he has any friends. Other than his smelly bottle, of course.\n\nYou know what? I've got an idea. Farmer Yoon has a basket of craneberries inside his house, and a few apples as well. I'm sure you could bring them to the stillmaster in the Halfhill Market and get him to brew something special for Jogu.", objectives = "" }
WordHunterWoW_QuestEN[30479] = { title = "A Gift For Gina", description = "Have you seen Gina Mudclaw, the market girl? She has it all - looks, brains, and nice big tummy. Could you deliver a gift for me?\n\nI wanted to pick some orchids that grow on top of the big hills to the west, but I can't climb that high. Could you pick a few and bring them to Gina?\n\nOh, and when you see her... tell her I said \"hi\".", objectives = "" }
WordHunterWoW_QuestEN[30480] = { title = "The Ritual", description = "From the moment I first rose from the river, I knew I was destined to be Waterspeaker.\n\nI was taught many rituals, and have performed all of them, save one.\n\nThere was one, an extremely ancient one, that we were told to call upon if our people ever turned against us. \n\nThis must have happened in our people's distant past, because we haven't needed to use it in our village's memory.\n\nI suppose now is the time to do so.", objectives = "" }
WordHunterWoW_QuestEN[30481] = { title = "Carved in Stone", description = "You see the shiny stones in the walls? Rook wants some. The mogu been collecting them, so they have some to take too maybe.\n\nIf you find stones, you please bring them to Rook? Rook will be your friend.", objectives = "" }
WordHunterWoW_QuestEN[30482] = { title = "The Soul-Gatherer", description = "A single large mogu performing a ritual on the lake caught your attention while you were killing the other mogu in the area. It seems unwise to let his ritual complete.", objectives = "" }
WordHunterWoW_QuestEN[30484] = { title = "Gauging Our Progress", description = "The time for war is at hand, {name}!\n\nWe've been training these natives non-stop since you left, and I believe they're as good as they're going to get.\n\nSee for yourself. Check in with the others and return with your findings.\n\nWe must rely on our enemy being somehow... even less prepared.", objectives = "" }
WordHunterWoW_QuestEN[30485] = { title = "Last Piece of the Puzzle", description = "These hozen are behaving most unnaturally, {name}. Marching in formation? In armor?\n\nThis troubles me. We must discuss it at another time, however. I have come to ask for your assistance.\n\nThe ancient fresco, where last we spoke, is nearly unveiled. I am certain that it holds ancient wisdom - knowledge that the emperor wanted us to remember.\n\nMy meditations alone may not be enough to discern its meaning. Please, take this heirloom to the shrine of my ancestors. I shall require their assistance.\n", objectives = "" }
WordHunterWoW_QuestEN[30487] = { title = "Comin' Round the Mountain", description = "The mountain pass is very dangerous. You need much luck to survive. Nephew Bentnail will show you the way.\n\nPerhaps today is a lucky day to travel though. Wind blows from the east; this is good sign. Grummles always travel best when east wind blows.\n\nClimb in the cart when you are ready to leave.", objectives = "" }
WordHunterWoW_QuestEN[30488] = { title = "The Missing Muskpaw", description = "What the heck are you supposed to be? a {class}? Never heard of one of them. You here to help or to steal my yaks?\n\nLook, if yer' insistin' on helpin' out, go find my boy. He got himself grabbed by a bunch of sprites and probably doesn't even know we lost the ranch.\n\nThey dragged him off to Pranksters' Hollow south east of here. Go rescue him an' I'll see about giving you a reward of some sort.", objectives = "" }
WordHunterWoW_QuestEN[30489] = { title = "Fresh Needle Scent", description = "Say, if you really are here to help, I could use me some needles off them sprites in Pranksters' Hollow.\n\nThe grummles don't believe in luck they can't smell. They'll pay better for yaks that have that fresh needle scent.", objectives = "" }
WordHunterWoW_QuestEN[30490] = { title = "Yakity Yak", description = "Yaungols! They come through here taking what they want and destroying whatever's left.\n\nI can't have these thugs destroy the last pieces of the Yak Wash here. It's all my boy and I have left.\n\nHead over to our old ranch and dish out some pain on them yaungols. I bet if you kill enough of them they'll think twice before attacking anything in this area.", objectives = "" }
WordHunterWoW_QuestEN[30491] = { title = "At the Yak Wash", description = "Look, my father is crazy. I love him, but he's crazy.\n\nThese yaungol managed to completely obliterate our ranch and scattered our yaks every which way.\n\nIf I know my father though, he's going to try to go head to head with the yaungol to get the yaks back.\n\nCan you help us round up some of the yaks so my father doesn't do anything stupid?\n\nJust ride them over to the Yak Wash so we can clean them up and sell them to the grummles.", objectives = "" }
WordHunterWoW_QuestEN[30492] = { title = "Back in Yak", description = "I wasn't lying about your reward. Here, take these washed yaks to the grummle caravan master Eightcoins.\n\nYou can find him at the Grummle Bazaar west of here. He'll credit us and give you a delivery fee.\n\nHe may be short, but he is our biggest customer.\n\nReturn to me if you lose the yaks. More often than not they just come right back here anyway. Once they've been cleaned that is.", objectives = "" }
WordHunterWoW_QuestEN[30495] = { title = "Love's Labor", description = "Can I trouble you for another favor?\n\nWe're way behind schedule, and this jade shipment is the last we need to finish the great statue.\n\nI've got my hands full, so could you run this ore over to the other foremen?\n\nHistorian Dinh, Surveyor Sawa, and Kitemaster Shoku can all be found around the base of the statue. Taskmaster Emi is directing production at the top of the statue.\n\nWe're on a deadline, so make sure you do it fast! Time's a wasting!", objectives = "" }
WordHunterWoW_QuestEN[30496] = { title = "The Waterspeaker's Staff", description = "There is great dissent in Inkgill, {race}. Elder Shai Hu drank the sha-corrupted waters of the mere, and forced the others to do the same. When I protested, Orachi of the town guard confiscated my ritual staff and banished me.\n\nNow, I am not only an exile, I am unable to speak with the waters that once gave me guidance!\n\nI am not a fighter. But if you are, perhaps you can recover my staff from Orachi? He is in town to our north.", objectives = "" }
WordHunterWoW_QuestEN[30498] = { title = "Get Back Here!", description = "Oh, before I forget, I have something I was asked to deliver to you. A letter from one of your companions, I assume.\n\nI was made to understand that your presence was urgently required, so I took the liberty of arranging your passage.\n\nSpeak to Ginsa Arroweye just south of here when you're ready. She has a kite waiting.", objectives = "" }
WordHunterWoW_QuestEN[30499] = { title = "Get Back Here!", description = "Oh, before I forget, I have something I was asked to deliver to you. A letter from one of your companions, I assume.\n\nI was made to understand that your presence was urgently required, so I took the liberty of arranging your passage.\n\nSpeak to Ginsa Arroweye just south of here when you're ready. She has a kite waiting.", objectives = "" }
WordHunterWoW_QuestEN[30500] = { title = "Residual Fallout", description = "Pandaria is a mystical land, traveler.\n\nIt bears repeating that some of its secrets remain hidden, even to Lorewalkers.\n\nSealing those fissures did not mend what has been broken. If the legends are true, it will take much more to release this land from the grasp of the Sha.\n\nThe aggression of that battle awakened a host of living negative emotions. What you see here is likely the first of many such manifestations.\n\nFor now, we can only try to diminish their presence here.", objectives = "" }
WordHunterWoW_QuestEN[30502] = { title = "Jaded Heart", description = "The more powerful remnants of that horrible manifestation may be too much for you to handle on your own, {name}.\n\nI fear I'd be of little help in terms of actual combat, but I can suggest a solution.\n\nThe great jade statue was soon to become a living serpent - one of our revered celestials. Its construction imbued it with special powers that may sufficiently weaken these adversaries.", objectives = "" }
WordHunterWoW_QuestEN[30504] = { title = "Emergency Response", description = "Your companions have made themselves at home in our land, and brought with them a dangerous conflict.\n\nThe full extent of their destruction here we cannot yet know. Already it is... unspeakable.\n\nNevertheless, to forsake your friends out of spite would be against our way. Any that yet live are doubtlessly wounded and in desperate need of care.\n\nThese fireworks were to celebrate the statue's completion. Use them near your companions to signal Mishi, and she will bear them off to safety.", objectives = "" }
WordHunterWoW_QuestEN[30506] = { title = "Admiral Taylor has Awakened", description = "It would seem that your Admiral Taylor has awakened from his injuries. He and his people are upstairs in the apothecary's house back in Binan Village.\n\nHe has requested your presence.", objectives = "" }
WordHunterWoW_QuestEN[30507] = { title = "Admiral Taylor has Awakened", description = "It would seem that your Admiral Taylor has awakened from his injuries. He and his people are upstairs in the apothecary's house across the way.\n\nHe has requested your presence.", objectives = "" }
WordHunterWoW_QuestEN[30508] = { title = "Admiral Taylor has Awakened", description = "It would seem that your Admiral Taylor has awakened from his injuries. He and his people are upstairs.\n\nHe has requested your presence.", objectives = "" }
WordHunterWoW_QuestEN[30509] = { title = "General Nazgrim has Awakened", description = "It would seem that your General Nazgrim has awakened from his injuries. He and his people are upstairs in the apothecary's house back in Binan Village.\n\nHe has requested your presence.", objectives = "" }
WordHunterWoW_QuestEN[30510] = { title = "General Nazgrim has Awakened", description = "It would seem that your General Nazgrim has awakened from his injuries. He and his people are upstairs in the apothecary's house across the way.\n\nHe has requested your presence.", objectives = "" }
WordHunterWoW_QuestEN[30511] = { title = "General Nazgrim has Awakened", description = "It would seem that your General Nazgrim has awakened from his injuries. He and his people are upstairs.\n\nHe has requested your presence.", objectives = "" }
WordHunterWoW_QuestEN[30512] = { title = "Westwind Rest", description = "<Admiral Taylor winces in pain.>\n\nJade Forest was a disaster. \n\nAnduin's gone. We lost some good people. We didn't stop the Horde from advancing into the continent. \n\nBut I think I've found a way to get the locals on our side. You just helped fight off some of these \"yaungol\", no?\n\nI hear yaungol sacked Westwind Rest, a local village. We've been told that two groups of survivors have camped out along the road west out of town.\n\nWe help them out, maybe they'll consider siding with the Allliance.", objectives = "" }
WordHunterWoW_QuestEN[30513] = { title = "Eastwind Rest", description = "I am injured, but we can't stop here.\n\nThe hozen were... unreliable. The pandaren would be much better allies.\n\nYou have seen the refugees in this village, and heard of the yaungol invasion, no?\n\nWell, we've heard from the locals that Eastwind Rest, a nearby village, was destroyed by the Yaungol.\n\nApparently some survivors have gathered along the road out of town.\n\nGo. Take the road west. Gather the survivors. \n\nWe'll help them rebuild. Then, they will see the advantage of joining the Horde!", objectives = "" }
WordHunterWoW_QuestEN[30514] = { title = "Challenge Accepted", description = "The yaungol have always been a difficult, proud people, but never this violent or aggressive. \n\nI do not know what has prompted this change in their behavior, but we don't have time to find out, now. We fear for our lives and livelihoods as long as Ur-Bataar, leader of the Bataari yaungol, lives.\n\nGo, set the banner in his camp ablaze to challenge him, and then defeat him in battle. Only then will we be secure.", objectives = "" }
WordHunterWoW_QuestEN[30515] = { title = "Challenge Accepted", description = "The yaungol have always been a difficult, proud people, but never this violent or aggressive. \n\nI do not know what has prompted this change in their behavior, but we don't have time to find out, now. We fear for our lives and livelihoods as long as Ur-Bataar, leader of the Bataari yaungol, lives.\n\nGo, set the banner in his camp ablaze to challenge him, and then defeat him in battle. Only then will we be secure.", objectives = "" }
WordHunterWoW_QuestEN[30516] = { title = "Growing the Farm I: A Little Problem", description = "So you need to whack some wily weeds?\n\nNo problem, neighbor! Only thing is, I'm running low on weed killer.\n\nI make my own concoction - very potent, totally organic and good for the earth. Plants love it! Well... except for those pesky weeds. They hate the stuff!\n\nIf you bring me some Spideroot from the terraces just west of us, I'll make a fresh batch and go down to Yoon's farm myself.\n\nI would gather some myself but... well... I hate spiders. You'll see what I mean.", objectives = "" }
WordHunterWoW_QuestEN[30517] = { title = "Farmer Fung's Vote I: Yak Attack", description = "The next voting member on the Tiller's council is Farmer Fung, and it's easy to see why.\n\nThat man's vegetables are the biggest in the valley! I only hope that someday I can grow pumpkins as big as his.\n\nIf we hope to join the Tillers, he would be the next person to convince.", objectives = "" }
WordHunterWoW_QuestEN[30518] = { title = "Farmer Fung's Vote II: On the Loose", description = "You want my vote for Farmer Yoon? Ha! You're joking, right?\n\nListen, I'm not going to vote for some citypaw with no lick a' knowledge about farming the earth.\n\nIt would be an embarrassment to farm alongside you or that Yoon shmuck.\n\nNow let me deal with my own problems. Some devil let my prize yaks loose, and now they're running wild northwest of Halfhill.\n\nIf I could just get my yaks back, then maybe I'd be able to sleep at night.", objectives = "" }
WordHunterWoW_QuestEN[30519] = { title = "Nana's Vote I: Nana's Secret Recipe", description = "The next vote we'll need is from Nana Mudclaw. She's Haohan's grandmother, and she's been a Tiller longer than you and I have been alive!\n\nShe's still working at the Tillers building in Halfhill. Why don't you pay her a visit?", objectives = "" }
WordHunterWoW_QuestEN[30521] = { title = "Haohan's Vote I: Bungalow Break-In", description = "This is going to be tough, {name}.\n\nThe last vote we need comes from Haohan Mudclaw, the head of the Tillers Union.\n\nI know he wasn't too keen on us to start, but we've learned so much about farming, I'm sure he'll have a change of heart!\n\nGo speak to him. You can be very convincing, right?", objectives = "" }
WordHunterWoW_QuestEN[30522] = { title = "Haohan's Vote II: The Real Culprits", description = "What are YOU doing here, citypaw?\n\nLook, I've got my hands full with a break-in at my shed to the west. Some rascals came in the middle of the night and ransacked the place.\n\nI've got missing seeds, broken tools, and eaten inventory to deal with.\n\nI'll just add it to my list of other troubles: a whole wagon of melons stolen, a broken water pump, animals ruining my harvest...\n\nI wish that I could just get to the bottom of all this already!", objectives = "" }
WordHunterWoW_QuestEN[30523] = { title = "Growing the Farm II: The Broken Wagon", description = "Hey {name}. I've been looking at that wagon every day, day in and day out, since the day I moved in. Quite an eyesore, don't you think?\n\nI heard in town that Fish Fellreed is quite handy with tools. She might be able to fix it up, and then we could turn that patch of land into a plot for farming.\n\nWhy don't you talk to her and see if she'd be willing to do the job?", objectives = "" }
WordHunterWoW_QuestEN[30524] = { title = "Growing the Farm II: Knock on Wood", description = "Sure! I know just the wagon that you're talkin' about!\n\nI can fix it right up, but I'll need wood.\n\nThere's a whole lot of it down at the bottom of the lake. If you fish it right out - haha, get it? Fish? Oh I just crack myself up sometimes.\n\nAnyway, you bring me here some 'o that wood and then I'll get right to work!", objectives = "" }
WordHunterWoW_QuestEN[30525] = { title = "Haohan's Vote III: Pure Poison", description = "All right, {name}. This is our big chance!\n\nMr. Mudclaw's farm is in big trouble. Those mountain hozen are coming down at night, wrecking his crops and eating his hard-earned harvest.\n\nWe've got to get rid of them for good, and I know just how to do it.\n\nBack in the day, my grandpa showed me how to mix a wounding poison to deal with the pests on the farm.\n\nThe virmen warrens to the north hold the key ingredients for my mixture.\n\nDon't look so worried, {name}! I'm pretty sure this is going to work.", objectives = "" }
WordHunterWoW_QuestEN[30526] = { title = "Lost and Lonely", description = "The starving, mangy dog whines piteously and attempts a brief wag of its tail.\n\nIt looks like it could use a good meal right about now.", objectives = "" }
WordHunterWoW_QuestEN[30527] = { title = "Haohan's Vote IV: Melons For Felons", description = "All right, now I happen to know that those mountain hozen love a delicious, sweet melon.\n\nMr. Haohan's last harvest of melons got stolen, so we're going to have to grow some of our own.\n\nOnce we have our harvest, we'll use them to lure the nasty hozen's leader out of its cave!", objectives = "" }
WordHunterWoW_QuestEN[30528] = { title = "Haohan's Vote V: Chief Yip-Yip", description = "You ready for the final step of the plan?\n\nThe leader of the Kunzen hozen is a brute by the name of Chief Yip-Yip. It's said that he is nearly impervious to pain.\n\nI've injected the melons with a toxic mixture, so don't try eating them!\n\nOnce you get his attention, throw these melons onto the ground. Yip-Yip won't be able to resist a sweet striped melon.\n\nWhen he takes a bite, he'll be temporarily weakened, and you should find yourself an opening to attack.", objectives = "" }
WordHunterWoW_QuestEN[30529] = { title = "Growing the Farm III: The Mossy Boulder", description = "Now that we're officially members of the Tillers Union, Mr. Mudclaw said he'd be happy to help us upturn this big ole' rock in the middle of our field.\n\nOnce we clear away that stone, I've got something special planned.\n\nRun down and give him a holler to let him know that we're ready.", objectives = "" }
WordHunterWoW_QuestEN[30534] = { title = "A Second Hand", description = "Despite your best efforts, the work is starting to pile up around here.\n\nPerhaps you could ask one of your best friends if they'd like to help out at Sunsong Ranch.", objectives = "" }
WordHunterWoW_QuestEN[30535] = { title = "Learn and Grow I: Seeds", description = "Well, first things first! I'm going to need lots of help 'round here.\n\nIf we're going to be partners, you've got to learn how to harvest crops, and if you wanna harvest crops you gotta plant seeds!\n\nNow it's my understanding that a mister, uh... Grainfell? No, that wasn't it... Greedfill? That doesn't sound right...\n\nGreenfield! That's his name! He's the man to see for seeds.\n\nGreenfield's got a stall over at Halfhill Market, directly southeast of here - go see him and pick up some vegetable seeds.", objectives = "" }
WordHunterWoW_QuestEN[30565] = { title = "An Unexpected Advantage", description = "Things seem to be goin' our way more and more lately, {name}. I was out doin some explorin' when I came upon this little beauty.\n\n<Sully gestures to the ballista to his right.>\n\nProblem is she's one of a set and the other one is still in pieces. I'd have gotten it together by now if those pesky Grimleers hadn't ambushed me and taken some of the gears and bolts.\n\nHey, ye seem to be pretty good at handlin' the natives. Ye wouldn't mind goin' and helpin' ol'Sully out would ye? ", objectives = "" }
WordHunterWoW_QuestEN[30567] = { title = "Blanche's Boomer Brew", description = "Can you smell it in the air? A storm is brewing! And so am I!\n\nMeet me at the hilltop when the storm hits and together we'll whip up a keg of my most famous brew. Can I count on your help?\n\n", objectives = "" }
WordHunterWoW_QuestEN[30568] = { title = "Helping the Cause", description = "Welcome back, {name}! It seems the Jinyu have taken to our training even better than I had hoped. We're in the final stages of our preparations now.\n\nI need someone to go check in with Amber, Bold Karasshi, and Mishka. See if they need any help to complete their training.\n\nYou'll find Karasshi and Mishka here in Pearlfin Village. Amber is training recruits in Slingtail Pits to the northwest.", objectives = "" }
WordHunterWoW_QuestEN[30569] = { title = "Trouble on the Farmstead", description = "I... I escaped from Farmer Chow's, to the southeast of here. It's been taken over by yaungol, but the old man and his wife just won't give it up!\n\nPlease, go there and help him out. Maybe if you do, he'll be willing to send some folks back here and help you guys farm up some food for the new town?", objectives = "" }
WordHunterWoW_QuestEN[30570] = { title = "Trouble on the Farmstead", description = "I... I escaped from Farmer Chow's, to the southeast of here. It's been taken over by yaungol, but the old man and his wife just won't give it up!\n\nPlease, go there and help him... Maybe if you do, he'll be willing to send some folks back here and help you guys farm up some food for the new town?", objectives = "" }
WordHunterWoW_QuestEN[30571] = { title = "Farmhand Freedom", description = "Those Ordo yaungol are working my farmhands to death! It just ain't right.\n\nPlease, {class}, save them before it's too late.", objectives = "" }
WordHunterWoW_QuestEN[30575] = { title = "Round 'Em Up", description = "Mobility is going to be key to maintaining our foothold in this new land. Problem is, there's no way to maintain mobility without mounts, and... well, we don't have many of those here, now do we?\n\nThe local yaks seem to make good mounts. At least, the local pandaren say they do. Why don't you go round some up for us?", objectives = "" }
WordHunterWoW_QuestEN[30581] = { title = "... and the Pot, Too!", description = "Sure, I'm willing to help you guys out. But we need to eat, too! I don't even have a pot to cook in! Let alone ingredients to put in it!\n\nHere's a list of the things that I need. Now get!", objectives = "" }
WordHunterWoW_QuestEN[30582] = { title = "The Late Mrs. Muskpaw", description = "This well worn trinket has several markings on it confessing love and adoration from the late Mrs. Muskpaw.\n\nPerhaps Lao would like his wife's trinket back.", objectives = "" }
WordHunterWoW_QuestEN[30583] = { title = "Blue Dwarf Needs Food Badly", description = "Oi!\n\nWe need ta' get us some food, if we're gonna survive here for long!\n\nYe' may not know it, but I'm somethin' of a cook me'self. Why don'tcha go out there and fetch us some meaty bits. I can cook 'em up and feed us for weeks! Or, days, at least.", objectives = "" }
WordHunterWoW_QuestEN[30584] = { title = "Shocking!", description = "Have you ever had a fresh dojani eel {name}?  No?\n\nWell you have not lived then!  Head north up to the dojani river and fish up a few for us.   Be careful, those eels can zap you if you're not careful!", objectives = "" }
WordHunterWoW_QuestEN[30585] = { title = "What Lurks Below", description = "Legend tells of a great beast in the forest to the north.  My son is missing and I fear he may have wandered too near its lair....\n\nHead northwest to Krasari Falls and look for a mysterious whirlpool - this is the key to revealing what is hidden there.  Kill the wretched beast and recover any clues to my son's whereabouts.", objectives = "" }
WordHunterWoW_QuestEN[30586] = { title = "Jagged Abalone", description = "Pandaren have been harvesting jagged abalone in this area for generations.  Now it's time for you to learn the ritual.\n\nThe abalone can be found just northeast of here in narsong trench.  Be careful, we have noticed increased shark activity in that area recently.", objectives = "" }
WordHunterWoW_QuestEN[30587] = { title = "Yakity Yak", description = "For now, the yaungol invaders seem content to steal yaks. Surveying the area, however, you notice they could easily move on the Yak Wash at any moment.\n\nThinning their numbers may help show the yaungol that this area is protected.", objectives = "" }
WordHunterWoW_QuestEN[30588] = { title = "Fishing for a Bruising", description = "The riverblade saurok clan is attacking one of our local fishing expeditions!  They need help right away!\n\nThin those saurok out and help that expedition return safely!", objectives = "" }
WordHunterWoW_QuestEN[30589] = { title = "Wrecking the Wreck", description = "To dislodge the alliance ship, we need to find our engineer. He parted ways with us when we were escaping the wreckage.\n\nYou should be able to find him somewhere in the western forest. Tell him Korga sent you and he'll get in line to help.", objectives = "" }
WordHunterWoW_QuestEN[30590] = { title = "Handle With Care", description = "We can help you get your ship free, but we'll need more of the explosives we were trying to take back from the Alliance to make it happen.\n\nI ordered the men to grab all the explosives they could before making our escape. If you sift through the wreckage and bodies to our south, there should be some explosive bundles among them, those that didn't already blow up anyway.\n\nGet me enough of them and I think I can put something together for ya.", objectives = "" }
WordHunterWoW_QuestEN[30591] = { title = "Preying on the Predators", description = "The forest has become far more dangerous ever since Shen-zin Su began shaking. The tigers are agitated and have begun attacking the refugees, and on occasion, me as well.\n\nIf these injured and weak survivors are to make it to safety here at the hut, we need to help clear the forest for them.", objectives = "" }
WordHunterWoW_QuestEN[30592] = { title = "The Burlap Trail: To Burlap Waystation", description = "Bad fortune for grummles today. Hozen have begun to ravage! They attack our supply line to the Serpent's Spine.\n\nCan you help? We are not fighters. We are grummles. Good fortune to those who help grummles.\n\nGo with a group of grummles to the Burlap Waystation. Keep them safe. Make sure at least one grummle survives.\n\nGrummles shall reward. Grummles always reward.", objectives = "" }
WordHunterWoW_QuestEN[30593] = { title = "Deanimate the Reanimated", description = "The admiral's asked me to take care of a major problem, but my specialty's in healing, not fighting!\n\nThe pandaren in the camp here have told me that something is animating the statues to the northeast at Mogujia.\n\nWill you help me out, {name}? We can't afford to have a fight with an army of statues right now.", objectives = "" }
WordHunterWoW_QuestEN[30594] = { title = "Deanimate the Reanimated", description = "I've got much to do here, {name}. I could use your help.\n\nThere's a place to the northwest. The pandaren here call it Mogujia. Something's causing the statues there to animate, and our pandaren friends here are pretty spooked about it.\n\nIf they're not dealt with soon, we might have a serious problem. We just moved in. It's not like we can afford to fight a war with an army of statues right now.", objectives = "" }
WordHunterWoW_QuestEN[30595] = { title = "Profiting off of the Past", description = "Let me guess, you're here to deal with the mogu statues that are being reanimated. What a coincidence, I'm here to, um... conduct research on the mogu.\n\nI tell you what, if you bring me as many of the mogu relics in there that you can carry, I'll give you a cut. Of the research... funding.", objectives = "" }
WordHunterWoW_QuestEN[30596] = { title = "A Zandalari Troll?", description = "While you've been destroying the reanimated mogu statues, the unmistakable accent of a Zandalari troll has been taunting you.\n\nIt's clear that the threat to Westerly Rest will not end until he's been dealt with.", objectives = "" }
WordHunterWoW_QuestEN[30598] = { title = "Who Knew Fish Liked Eggs?", description = "Great cranes have been nesting in this area for generations.  The Narsong Spires provide a sheltered area to rear their young.\n\nTheir pristine eggs are revered as bait for catching the silver goby.  Retrieve a crane egg and see if you can catch a goby!", objectives = "" }
WordHunterWoW_QuestEN[30599] = { title = "A Monkey Idol", description = "Before, grummles keep hozen from ravaging by bribing with food.\n\nBut now the Broketooth hozen south of here have their big magic idols. The Ook of Dook has trained them to use their idols to get power from sacrifices.\n\nThey are using them to kill grummles!\n\nYou must destroy these idols!\n\nFor every idol, there is a chief. Kill the chief and throw corpse on their altar.", objectives = "" }
WordHunterWoW_QuestEN[30600] = { title = "No Pack Left Behind", description = "The Broketooth hozen south of here killed all of my grummles. What is worse, their packages are undelivered.\n\nFortune frowns on a grummlepack undelivered.\n\nPlease, give my grummles peace on the great trail of beyond and bring their grummlepacks to me.\n\nI will see they are delivered.", objectives = "" }
WordHunterWoW_QuestEN[30601] = { title = "Instant Courage", description = "It is very bad fortune to travel mountain paths without a good guide. We grummles make the best guides, but many have run away. They fear the mountain pass now. Many good grummles disappear up there.\n\nGrummles are good at many things, but are not very brave. Maybe with fire lotus incense you can make them brave. Then they will show you the way. \n", objectives = "" }
WordHunterWoW_QuestEN[30602] = { title = "The Rabbitsfoot", description = "The Broketooth hozen stole our Rabbitsfoot! He was the grummle with the biggest luckydo.\n\nThis is very bad fortune indeed. Please, {race}, we need our Rabbitsfoot back. We need his good fortune back.\n\nCan you search the Broketooth Outpost for him?", objectives = "" }
WordHunterWoW_QuestEN[30603] = { title = "The Broketooth Ravage", description = "They took my luckydo! Their leader hozen here, Mo Mo, stole my rabbitsfoot.\n\nThis is most bad fortune for grummles. My rabbitsfoot is a big luckydo for grummles everywhere. If hozen learn how to get luck from my rabbitsfoot then all is lost.\n\nPlease can you get it back?", objectives = "" }
WordHunterWoW_QuestEN[30604] = { title = "Breaking Broketooth", description = "Hozen only ravage when they think their supplies are too few for their number of mouths.\n\nProblem is, hozen always have more mouths than food.\n\nWe have very few grummles these days.\n\nIt is a hard thing to ask, but can you be a friend to grummles, and destroy some of the Broketooth hozen south of here? It is the only way to prevent them from destroying the landscape.", objectives = "" }
WordHunterWoW_QuestEN[30605] = { title = "Lucky Yakshoe", description = "While you were gone, I saw a group of grummles coming down the Burlap Trail. It was led by my Brother Yakshoe.\n\nBut then the Knucklethumps attacked. They took my brother and his grummles north.\n\nPlease, {name}! Save my brother. He always has bad fortune and no luck, but he is my brother. Look for him at the alter in front of Fort Silverback.", objectives = "" }
WordHunterWoW_QuestEN[30606] = { title = "Thumping Knucklethump", description = "The Knucklethump hozen have new chief, the Ook of Dook.\n\nHe sees fear in the west, anger in the south, hatred in the north, and yaungols in the east.\n\nAnd so he sets his hozen to ravage, gathering food and supplies for coming famine.\n\nThey are many Knucklethumps and dangerous.\n\nPlease, Luckydo, can you defeat their fighters?", objectives = "" }
WordHunterWoW_QuestEN[30607] = { title = "Hozen Love Their Keys", description = "The hozen have a yeti! They call it Old Poot Poot and keep it at the back of their cave.\n\nHozen are normally scared of yeti, but now they feed it grummles.\n\nThey have a Hunter Chief, Cho Cho the Wicked. Can you see if he has a key on him to the yeti shackles?\n\nBad fortune for hozen if a yeti is loose in their fort.", objectives = "" }
WordHunterWoW_QuestEN[30608] = { title = "The Snackrifice", description = "They took my grummles! Hozen don't eat grummles, but yeti do. And the Knucklethumps have a yeti.\n\nPlease rescue my grummles. Cut them down or let them out of cages. Rescue them any way you can.\n\nMany fortunes and rewards if you do this.", objectives = "" }
WordHunterWoW_QuestEN[30610] = { title = "Grummle! Grummle! Grummle!", description = "Now that grummles are rescued, we need to rescue our supplies.\n\nThe Ook of Dook is only chief because he has supplies.\n\nGo to the Dooker Dome area north west of here. Take some grummles with you. Keep them safe and get them near supply crates.\n\nGrummles know what to do from there.\n\nRabbitsfoot and I will meet you there.", objectives = "" }
WordHunterWoW_QuestEN[30611] = { title = "Unleash The Yeti!", description = "Your yeti ride gave me an idea. The Ook of Dook has a pet yeti he named Chomp Chomp.\n\nHe uses this yeti to scare other hozen in to making him the leader hozen. We need to get rid of that yeti.\n\nGo to Dooker Dome northwest of here and defeat some of the Cagemasters so Chomp Chomp is not tied up as much.\n\nYakshoe and I will meet you there with lots of incense and a dirty yak.", objectives = "" }
WordHunterWoW_QuestEN[30612] = { title = "The Leader Hozen", description = "The time has come to face the Ook of Dook. We beat him, and the hozen won't have someone telling them to ravage.\n\nHere is the plan: Yakshoe will lead Tassle in to arena and scare away Chomp Chomp.\n\nThen, you sneak in and fight the Ook of Dook while his hozen are distracted by the yeti rampaging through their home.\n\nWe'll meet you back at Kota Basecamp with a big reward. Good fortune to you, friend of grummles.", objectives = "" }
WordHunterWoW_QuestEN[30613] = { title = "Armored Carp", description = "Armored Carp are a delicacy around these parts.\n\nUnfortunately we can't fish them up since they snap our hooks with their powerful jaws.  Take this fishing spear and see if you can catch a few for us.", objectives = "" }
WordHunterWoW_QuestEN[30614] = { title = "Oil Stop", description = "When the yaungols came, they began to dig up oil. What is this \"oil\", I wonder? Perhaps it is thing of much undiscovered luck. This I must know.\n\nHere, take this vial, and fill it with yaungol oil from one of their windmills. I will give you many fortunes if you bring me some.", objectives = "" }
WordHunterWoW_QuestEN[30615] = { title = "A Zandalari Troll?", description = "While you've been destroying the reanimated mogu statues, the unmistakable accent of a Zandalari troll has been taunting you.\n\nIt's clear that the threat to Westerly Rest will not end until he's been dealt with.", objectives = "" }
WordHunterWoW_QuestEN[30616] = { title = "Traffic Issues", description = "Yaungols are attacking our Burlap Trail. This is most bad fortune for grummles.\n\nWe use that trail to carry supplies to the Serpent's Spine. Without supplies, the defenders of the wall are in danger.\n\nGrummles are packers and explorers, not fighters. Could you be a luckydo for us and stop the yaungol blockade?", objectives = "" }
WordHunterWoW_QuestEN[30617] = { title = "Roadside Assistance", description = "A luckydo remembers to bring incense on a journey in to the mountains. The smellier the luck the better.\n\nCan you journey up the road to One Keg and light the incense you find along the way?\n\nThis will give good fortune to grummles that must travel the road.\n\nBrother Lintpocket can give you many rewards. Speak to him when you arrive.", objectives = "" }
WordHunterWoW_QuestEN[30618] = { title = "Resupplying One Keg", description = "If you're looking for the best supplies in Kun-Lai you've come to the right place! Oh sure, it looks a bit empty. Don't let appearances deceive you..\n\nOh, who am I kidding?! Between the hozen attacks, and the sprites pillaging what few supplies we do get, my stock has dwindled to a dangerous level.\n\nIf you could help me recover some of my supplies I should have enough to contribute to your journey.", objectives = "" }
WordHunterWoW_QuestEN[30619] = { title = "Mogu?! Oh No-gu!", description = "I know your friends are worried about the animating statues over at Mogujia, but I'll tell you what you should really be worried about.\n\nWhere there are animated statues, there are mogu. I don't know if you've seen one before, but if you haven't...\n\nWell, let's just say mogu are bad, bad, news.\n\nWhile you're dealing with whatever else you're doing, you need to get the mogu behind the trouble!", objectives = "" }
WordHunterWoW_QuestEN[30620] = { title = "Mogu?! Oh No-gu!", description = "I know your friends are worried about the animating statues over at Mogujia, but I'll tell you what you should really be worried about.\n\nWhere there are animated statues, there are Mogu. I don't know if you've seen one before, but if you haven't...\n\nWell, let's just say Mogu are bad, bad, news.\n\nWhile you're dealing with whatever else you're doing, you need to get the Mogu behind the trouble!", objectives = "" }
WordHunterWoW_QuestEN[30621] = { title = "They Stole My Luck!", description = "My journeys through Kun-Lai have taught me two things. First, never sneak up on a sleeping yak. Second, having luck on your side is both necessary and hard to come by.\n\nThe grummles believe in carrying a lucky trinket at all times. In my mind, if one trinket can sometimes bring luck, then many trinkets would guarantee it!\n\nAfter arriving in One Keg my lucky trinkets were stolen by those little menace sprites. I'd be truly grateful if you could retrieve them for me.", objectives = "" }
WordHunterWoW_QuestEN[30622] = { title = "The Swarm Begins", description = "Without the wall to protect us, we barely stand a chance. If you hadn't gathered so many people to help us, we wouldn't have a prayer.\n\nCheck in with Captain Oakenshield - he should be up near the break in the wall. Kill as many mantid as you can on the way there.\n\nIf we win, we win. If we lose, we go down fighting. For Pandaria!", objectives = "" }
WordHunterWoW_QuestEN[30623] = { title = "The Mantidote", description = "<Mei motions towards the battlefield.>\n\nYou see those huge mantid commanders out there? They have a strange aura about them. It reminds me of the sadness we saw at Zhu's Watch.\n\nPerhaps... they're under the influence of the sha, too?\n\nI kept Ken-Ken's mask - the one he used to remove the sha from Yi-Mo. I believe that, if we use it on the mantid, we can convince them to turn back.", objectives = "" }
WordHunterWoW_QuestEN[30624] = { title = "It Does You No Good In The Keg", description = "I been thinkin'.\n\nWe got all this beer that Chen brewed, and we got all these people that you've gathered. We should bring the two together.\n\nThere's a bunch o' folks out there in the fields, riskin' their lives for Pandaria. You an' I should at least bring 'em a keg or two.\n\nThey might raise their mugs in victory. They might enjoy one last drink before gettin' skivvered by a mantid. Either way, I wouldn't want 'em to fight without a good brew in their belly.", objectives = "" }
WordHunterWoW_QuestEN[30625] = { title = "Students No More", description = "Those five students - the ones who were looking for the Hidden Master - they went up to the front lines, alone. I'd send Shado-Pan to aid them, but I haven't got any left.\n\nThere's dangerous creatures up there near the wall. If you find those students, make sure that they haven't fallen to any of them.", objectives = "" }
WordHunterWoW_QuestEN[30626] = { title = "Retreat!", description = "I'm going to withdraw what few forces I have. We may have to fall back to the Stormstout Brewery, or even Halfhill. That call is Commander Loon Mai's to make.\n\nYou go ahead. Deliver word to the Commander. My Shado-Pan will be shortly behind.", objectives = "" }
WordHunterWoW_QuestEN[30627] = { title = "The Savior of Stoneplow", description = "That commander speaks hastily. He has the weapon he needs to win this battle. He has YOU.\n\n\"But it's too hard,\" you might say.\n\nYou would be wrong. It is not too hard. NOTHING IS TOO HARD.\n\nGo now, {name}. Go, and save Stoneplow!", objectives = "" }
WordHunterWoW_QuestEN[30628] = { title = "The Gratitude of Stoneplow", description = "One last thing, {name}. Don't worry, it's not another favor. You've killed enough mantid today.\n\nWe recently received a shipment of high-quality armor from Kun-Lai Summit. I was planning to keep them for my men... but I can't think of anybody more deserving than you. You'll find them on the second floor of the inn, here in town.", objectives = "" }
WordHunterWoW_QuestEN[30630] = { title = "Into the Vale", description = "Ah, I have been waiting for your arrival, traveler.\n\nI wish we could meet in better times, but alas, I fear the situation in the Vale is quite dire.\n\nBut let us not speak of that now. Go visit Matron Vi Vinh at the Shrine of Seven Stars.\n\nShe should be able to settle you in.", objectives = "" }
WordHunterWoW_QuestEN[30631] = { title = "The Shrine of Seven Stars", description = "Look at this creature, traveler. Only moments after we arrived, this mogu assassin attacked with no warning.\n\nHis blade was intended for the leader of the Golden Lotus. It is very lucky indeed that we were here to stop the attack.\n\nSeeing this attempt on Zhi's life, I fear for the safety of those who have already entered the valley.\n\nThe caretakers are settling your people into the city to the southeast. Go and speak to the leaders. Make sure they are safe.", objectives = "" }
WordHunterWoW_QuestEN[30632] = { title = "The Ruins of Guo-Lai", description = "According to Zhi the Harmonious, the mogu are moving into the Vale from the Ruins of Guo-Lai to the west.\n\nI sent Anji and Kun to investigate the situation, but they have not yet returned.\n\nI need a capable {class} like you to go check on them.", objectives = "" }
WordHunterWoW_QuestEN[30633] = { title = "Out with the Scouts", description = "We'd been briefed on mogu sightings in the Vale, but the situation is worse than we had anticipated.\n\nScouts are swarming all over the ruins to the northwest, gathering intel and stealing treasures.\n\nYour objective is clear - dispatch of any scouts you see. An army cannot move if we take out its eyes.", objectives = "" }
WordHunterWoW_QuestEN[30634] = { title = "Barring Entry", description = "Lao Softfoot and I scouted up the ruins to the north.\n\nIt looks like the mogu are infiltrating the valley through a cave just up the hill, and already they are sending formidable reinforcements through.\n\nThere are too many enemies to take them head on, so you'll have to meet Lao Softfoot at the entrance to the ruins.\n\nHe'll help you sneak in under the cover of stealth. Then, plant this keg of explosives at the mouth of the cave.\n\nThe rest should take care of itself.", objectives = "" }
WordHunterWoW_QuestEN[30635] = { title = "Killing the Quilen", description = "We've taken care of the scout problem for now, but there are still advance mogu forces inside the Guo-Lai Halls down the hill.\n\nUnfortunately, their vicious guard dogs are protecting their operations deeper in the ruins.\n\nGo and dispatch of their beasts. Be on your guard - they can be quite good at blending into their surroundings.", objectives = "" }
WordHunterWoW_QuestEN[30636] = { title = "Stones of Power", description = "Many thousands of years ago, the rulers of the Vale sought energy from a powerful crystal known as Revelite.\n\nWith this substance, they were able to power cities, factories, and engines of war.\n\nZhi the Harmonious has asked us to collect some crystals and bring them back to the city.\n\nKeep an eye out for them while you are in the ruins.", objectives = "" }
WordHunterWoW_QuestEN[30637] = { title = "The Guo-Lai Halls", description = "As you pass by the great door, you hear sounds from deep inside.\n\nAnji mentioned that advance mogu scouts had been sighted in this area. Perhaps they made their way down to the depths below.\n\nYour senses tingling, you decide to investigate.", objectives = "" }
WordHunterWoW_QuestEN[30638] = { title = "Leaving an Opening", description = "This is serious.\n\nKun and I will keep an eye on things here, but you should go to the Golden Pagoda.\n\nGo, swiftly!", objectives = "" }
WordHunterWoW_QuestEN[30639] = { title = "The Secrets of Guo-Lai", description = "I just received information from a guard stationed near the Ruins of Guo-Lai that the Shado-Tien leader entered the halls, killing two of my men in the process. They're intent on something inside. We need to stop them.\n\nHe Softfoot has already followed them in. He should be waiting for you at the entrance to the western chambers.\n\nMove quickly, {name}. I don't like the thought that the mogu may be a step ahead of us.", objectives = "" }
WordHunterWoW_QuestEN[30640] = { title = "Battle Spear of the Thunder King", description = "I have received some troubling news, {name}.\n\nThe mogu are plotting to steal three artifacts of power from the Vale.\n\nWe must retrieve the artifacts immediately and hide them for safekeeping.\n\nThe first artifact is the Battle Spear of the Thunder King.\n\nUpon emperor Lei Shen's death, the spear was placed in an ancient shrine to the northwest.\n\nBring the spear back to me.", objectives = "" }
WordHunterWoW_QuestEN[30641] = { title = "Battle Helm of the Thunder King", description = "The second artifact of power is the Battle Helm of the Thunder King.\n\nEmperor Lei Shen wore the helm into every battle. It became so well-known that his enemies would flee at the mere sight of it.\n\nWhen the Emperor died, they placed the helm in the very bottom of the Guo-Lai Halls to the west, surrounded by thousands of terracotta soldiers.\n\nThus, they could look upon their leader and follow him into death.", objectives = "" }
WordHunterWoW_QuestEN[30642] = { title = "Battle Axe of the Thunder King", description = "The final artifact is the Thunder King's axe.\n\nLei Shen charged into battle with his spear in one hand, and his axe in the other.\n\nIt is said that he could throw his axe with brutal accuracy, and when it hit its target, it made a sound like crashing thunder.\n\nAfter his death, the axe was placed in a ceremonial chamber to the southwest.\n\nNeedless to say, we must not let it fall into the mogu's hands.", objectives = "" }
WordHunterWoW_QuestEN[30643] = { title = "The Mogu's Message", description = "The battle against the mogu rages fiercely with neither side giving quarter.\n\nWe cannot hold our position forever. Something must be done to strike a blow at the mogu, a blow from which they cannot recover.\n\nGo check in with Zhi the Harmonious at The Silent Sanctuary. I wish to hear his thoughts on this matter.", objectives = "" }
WordHunterWoW_QuestEN[30644] = { title = "What Comes to Pass", description = "You had better report back to the Golden Pagoda immediately.", objectives = "" }
WordHunterWoW_QuestEN[30645] = { title = "The Might of Three", description = "This is it, {name}. This is the end.\n\nIf we don't drive the mogu from the valley, they will seize the remnants of their ancient power and use it to break Pandaria to their will.\n\nBut our forces are few, and tired, and small. We bleed, while their warriors are made of stone.\n\n{name}, although all odds are against us, still I must ask you to go and help our forces slay the mogu invaders.\n\nI have prayed to the Celestials, begging their aid. I can only hope that they answer our call.", objectives = "" }
WordHunterWoW_QuestEN[30646] = { title = "The Final Power", description = "I never thought it would come to this!\n\nLeven went to face Warlord Zhao-Jin the Bloodletter at the top of the palace steps, but our reinforcements cannot get through!\n\nWe are the only ones who stand between him and the Vale's greatest... and most deadly... powers.\n\nPlease, {name}, you must find a way to stop him!", objectives = "" }
WordHunterWoW_QuestEN[30648] = { title = "Moving On", description = "Your journey in this land has already proven most eventful, traveler. And mine, it appears, is destined to continue for a time.\n\nA chain of events began when your people arrived here, and while some of those happenings are traumatic to behold, I feel there must be a larger purpose behind your presence.\n\nFor now it is wisest that you leave this place and explore Pandaria's other regions.\n\nSpeak to me when you are ready to leave.", objectives = "" }
WordHunterWoW_QuestEN[30649] = { title = "The Shrine of Two Moons", description = "Look at this creature, traveler. Only moments after we arrived, this mogu assassin attacked with no warning.\n\nHis blade was intended for the leader of the Golden Lotus. It is very lucky indeed that we were here to stop the attack.\n\nSeeing this attempt on Zhi's life, I fear for the safety of those who have already entered the valley.\n\nThe caretakers are settling your people into the city to the northeast. Go and speak to the leaders. Make sure they are safe.", objectives = "" }
WordHunterWoW_QuestEN[30650] = { title = "Pandaren Prisoners", description = "Look, I know the Alliance needs recruits, and there's just not enough of us here right now to make a fighting presence of this town.\n\nBut I know that the yaungol over at Fire Camp Ordo, to the northwest, have taken many of my people as prisoners. And I also know that if you would be willing to rescue them from their captivity, they'd more than likely be willing to join the Alliance.\n\nWhat do you say, {name}?", objectives = "" }
WordHunterWoW_QuestEN[30651] = { title = "Barrels of Fun", description = "Oh, well now, let's have us some fun, boyo!\n\nThose Ordo yaungol to the northwest have saved us the trouble o' havin' to make some bombs. They already have them there.\n\nLet's put their explosive barrels to good use and destroy their oil-pumpin' machines, shall we?", objectives = "" }
WordHunterWoW_QuestEN[30652] = { title = "In Tents Channeling", description = "The yaungol of Fire Camp Ordo are a dire threat. I need you to head northwest and take out their leader.\n\nUnfortunately, his four subordinates are maintaining a fire barrier that prevents us from getting to him in the adjoining cave.\n\nTake them out and the shield will come down. You'll find them in their tents, channeling.", objectives = "" }
WordHunterWoW_QuestEN[30653] = { title = "It Does You No Good In The Keg", description = "I been thinkin'.\n\nWe got all this beer that Chen brewed, and we got all these people that you've gathered. We should bring the two together.\n\nThere's a bunch o' folks out there in the fields, riskin' their lives for Pandaria. You an' I should at least bring 'em a keg or two.\n\nThey might raise their mugs in victory. They might enjoy one last drink before gettin' skivvered by a mantid. Either way, I wouldn't want 'em to fight without a good brew in their belly.", objectives = "" }
WordHunterWoW_QuestEN[30654] = { title = "The Guo-Lai Halls", description = "The mogu are up to something, I can feel it.\n\nThey've been sending scouts down into the Guo-Lai Halls.\n\nAccording to the caretakers, the Halls are home to ancient treasures of emperors past. Not only riches, but artifacts of great power.\n\nWe must prevent the mogu from accessing these treasures! Go down the ramp to the northwest and stop them!", objectives = "" }
WordHunterWoW_QuestEN[30655] = { title = "Pandaren Prisoners", description = "Look, I know the Horde needs recruits, and there's just not enough of us here right now to make a fighting presence of this town.\n\nBut I know that the yaungol over at Fire Camp Ordo, to the west, have taken many of my people as prisoners. And I also know that if you would be willing to rescue them from their captivity, they'd more than likely be willing to join the Horde.\n\nWhat do you say, {name}?", objectives = "" }
WordHunterWoW_QuestEN[30656] = { title = "Barrels of Fun", description = "I love blowing stuff up. It's in my blood!\n\nThe yaungol to the west at Fire Camp Ordo have a ton of explosive barrels just lying around.\n\nI say we put them to good use and destroy their oil-pumpin' machines while having some fun!", objectives = "" }
WordHunterWoW_QuestEN[30657] = { title = "In Tents Channeling", description = "The yaungol of Fire Camp Ordo are the worst threat we're facing. I need you to head west and take out their leader.\n\nThe coward is hiding in a cave, which is protected by a fire shield cast by his four underlings.\n\nTake them out and the shield will come down. You'll find them in their tents, channeling.", objectives = "" }
WordHunterWoW_QuestEN[30658] = { title = "Huff & Puff", description = "Have you heard of the prickly puffer fish {name}?  Of course you haven't, you're new around these parts!\n\nThey can be found in the sarjun depths, due west of here.  Take this fishing spear and see if you can bring me back of few of their poison tipped spines.", objectives = "" }
WordHunterWoW_QuestEN[30660] = { title = "The Ordo Warbringer", description = "<The shield is down. Time to head into the cave and slay the Warbringer of the Ordo yaungol!>", objectives = "" }
WordHunterWoW_QuestEN[30661] = { title = "The Ordo Warbringer", description = "<The shield is down. Time to head into the cave and slay the Warbringer of the Ordo!>", objectives = "" }
WordHunterWoW_QuestEN[30662] = { title = "The Ordo Warbringer", description = "You've taken the shield down at Fire Camp Ordo. Go back there before the shield goes up again.\n\nTime to head into the cave and slay their chief!", objectives = "" }
WordHunterWoW_QuestEN[30663] = { title = "The Ordo Warbringer", description = "You've taken the shield down at Fire Camp Ordo. Get back over there before they get that shield up again.\n\nSlay the Warbringer of the Ordo!", objectives = "" }
WordHunterWoW_QuestEN[30665] = { title = "The Defense of Shado-Pan Fallback", description = "I sent for reinforcements from the Shado-Pan Monastery, but have heard nothing back. We have already lost the town.\n\nA few lucky villagers may have survived, but we are pinned down here.\n\nWe do not have time to entertain strangers. If you can fight, help my men defend this tower. If not, leave, for you will not survive long here.", objectives = "" }
WordHunterWoW_QuestEN[30666] = { title = "Sudden, Unexpected Crocolisk Aggression", description = "Normally, my day consists of catching fish, and then eating the fish I caught, followed by sleeping. Note that I did not include \"fight with a crocolisk\" in that list of activities.\n\nYou look like a handy {class}. Can you go get rid of some of these crocolisks, so I can get back to my regular routine? The crocolisks normally keep to themselves up at Kea Krak, to the northwest.", objectives = "" }
WordHunterWoW_QuestEN[30667] = { title = "Particular Plumage", description = "When the crocs started attacking, they scared a bunch of the lories out of their nests, up in that island to our northwest.\n\nI can use those lories' feathers to make some specialized lures, which will come in handy if and when I get to stop defending my brethren from these reptiles.\n\nYou up for some feather hunting?", objectives = "" }
WordHunterWoW_QuestEN[30668] = { title = "Build Your Own Raft", description = "<Jay looks off in the direction of Kea Krak.>\n\nHmm. They don't seem to be... calming down. We're going to have to try something different.\n\nYou'll need a raft. Go grab some wood planks and seaweed, and bring them over to me. I'll put something together for you.", objectives = "" }
WordHunterWoW_QuestEN[30669] = { title = "The Lorewalker on the Lake", description = "Your raft is down in the water below. Take it out to the middle of the lake, where you should find a woman. Her name is Ana  Wu.\n\nWhenever I have a question that I can't figure out on my own, I'll ask her. She should be able to tell us why these crocolisks won't stop attacking.", objectives = "" }
WordHunterWoW_QuestEN[30670] = { title = "Turnabout", description = "Our true enemies are the sha, not the yaungol.\n\nThe sha are emotion manifest. Destructive, yes. But undisciplined. Undisciplined force cannot last. The flood, in dispersion, loses its force. The wildfire burns its fuel.\n\nAnd, discipline and wisdom can turn their destructive energy against themselves.\n\nBring me the essences of the sha in the village, and I will explain further.", objectives = "" }
WordHunterWoW_QuestEN[30671] = { title = "Wisdom Has A Price", description = "<Ana listens to your story, and nods.>\n\nCrocolisks attacking? I know a story about that. And I will share it with you, but first... I grow hungry.\n\nShark meat should do the trick. You should find enough sharks in the water beneath us.", objectives = "" }
WordHunterWoW_QuestEN[30672] = { title = "Balance", description = "The story did not end happily. The Narsong crocolisk is no more.\n\nThis time, however, you may have a chance to change the ending.\n\nThe hozen to the south are overfishing these waters. With the fish gone, the crocolisks are hungry and desperate - and so they attack Marista.\n\nGo now, {race}! Stop those hozen from their reckless fishing!", objectives = "" }
WordHunterWoW_QuestEN[30673] = { title = "Holed Up", description = "Thank the heavenly spirits for you, {class}! I don't know how much longer I could've lasted.\n\nThere are other Firebough Nook survivors, I'm sure of it. Will you help rescue them and get us to the safety of Shado-Pan Fallback?", objectives = "" }
WordHunterWoW_QuestEN[30674] = { title = "Balance Without Violence", description = "Some of the fish that the Unga hozen have gathered don't seem do be dead yet. There may still be time to throw them back into the water.", objectives = "" }
WordHunterWoW_QuestEN[30675] = { title = "Buried Hozen Treasure", description = "The map you hold is crinkled, dirty, and poorly drawn, but you can see a big X on a beach.\n\nIs there buried treasure somewhere on this island?", objectives = "" }
WordHunterWoW_QuestEN[30677] = { title = "Shuttle Service", description = "", objectives = "" }
WordHunterWoW_QuestEN[30678] = { title = "Like Bombing Fish In A Barrel", description = "Turns out these rays are not as easy to catch as I thought! You seem like a pretty smart guy, think you can help me out?\n\nI made the bombs but have been having trouble using the raft with my hurt leg. The rays are common in the shallows just west of here. Take the bombs and use my raft to bring me back their stingers!\n\nOh yeah, watch out for the hammerheads!", objectives = "" }
WordHunterWoW_QuestEN[30680] = { title = "Holed Up", description = "Oh thank you, thank you, thank you. If you hadn't come along...\n\nWait! There must be other survivors in the Nook like me!\n\nPlease, {class}, I beg you. Rescue the rest of my citizens and deliver us safely to Shado-Pan Fallback.", objectives = "" }
WordHunterWoW_QuestEN[30681] = { title = "Holed Up", description = "Oh, thank you! There's no way I could have made it back on my own.\n\nCome to think of it, there must be others around Firebough Nook that need to be rescued. Shall we go collect them and then head to the safety of Shado-Pan Fallback?", objectives = "" }
WordHunterWoW_QuestEN[30682] = { title = "Holed Up", description = "I can't believe you made it here!\n\nI don't know how much longer I could have stayed hidden in here.\n\nI'm sure that there are others. {class}, we have to rescue them! Then we can go to Shado-Pan Fallback. The master there will know what to do!", objectives = "" }
WordHunterWoW_QuestEN[30683] = { title = "One Traveler's Misfortune", description = "Did you have to throw our supplies at them?! Why not use your weapon? Maybe fancy spells or kicks? Why the supplies?!\n\nNow we don't have enough to last us, especially with Nephew Bentnail here. His appetite is like a yeti's!\n\nYou threw it, you get us more. There is wreckage down the path. Maybe you will find supplies there.", objectives = "" }
WordHunterWoW_QuestEN[30684] = { title = "Seeker's Folly", description = "I'm sure your pandaren friend has some ideas about what the mogu are after.\n\nHe headed up the mountain a few days ago without a guide, and asked that only you be sent up after him. He was very specific:\n\n\"The {class} must endure the trek alone, with only his thoughts. He will honor each shrine before meeting me at the top.\"\n\nThe path is just northwest of the camp, marked by flags. Please be careful! Seeker's Folly is a dangerous trek even on a lucky day.", objectives = "" }
WordHunterWoW_QuestEN[30690] = { title = "Unmasking the Yaungol", description = "Simply killing Kobai will accomplish nothing, as he is possessed by a particularly powerful and destructive Sha - Malevolent Fury.\n\nYou will use the trap I have fashioned from the Blinding Rage Essences you brought. Lure him into the trap, and then steal his mask. Once you put it on, Malevolent Fury will appear and attempt to take control of you.\n\nDefeat him, and we will have made a victory of this tragic situation. You can find him to the north of the retreat, where he taunts us in insane rage.", objectives = "" }
WordHunterWoW_QuestEN[30691] = { title = "Misery", description = "While you are in the water below, you should slay Nahassa, the mortbreath patriarch. He suffers. I can feel his death cries ululating up to the surface of the lagoon.\n\nFind his cave, and put him out of his misery. Not because it will solve Marista's crocolisk problem. Simply out of mercy.", objectives = "" }
WordHunterWoW_QuestEN[30692] = { title = "The Burlap Trail: To Kota Basecamp", description = "This here's hozen lands. Very dangerous. But grummles must trek through. Supplies must reach the Serpent's Spine.\n\nGo, protect the next wave of grummles on their trek to Kota Basecamp.\n\nIf at least one survives, good fortune will find its way to you.", objectives = "" }
WordHunterWoW_QuestEN[30694] = { title = "Tread Lightly", description = "My students tell me the surrounding area is littered with deadly traps, no doubt set by the saurok. Stumbling into one gets you a face full of spikes.\n\nAs the saying goes: \"The Way is rife with danger - tread lightly, and with scrutiny.\"\n\n<Koro hands you a long tree branch.>\n\nHere, this is scrutiny.\n\nIt should be long enough to set the traps off at a safe distance.", objectives = "" }
WordHunterWoW_QuestEN[30695] = { title = "Ahead on the Way", description = "Huge maws of despair are spewing out sha from the pagodas on either side of the temple. Meanwhile, your impromptu training in the Way continues.\n\n\"She who mends torn umbrella will be more dry than she who strikes at rain.\"\n\nWhile I take issue with that particular lesson--sometimes punching the rain can be quite effective--the meaning holds true in this case.\n\nTake out those maws of despair and give my order a chance at reclaiming the temple grounds.", objectives = "" }
WordHunterWoW_QuestEN[30698] = { title = "Scavenger Hunt", description = "YOU!  You're just who I have been looking for!\n\nI need more parts for my goblin fishing bombs but I hurt my leg and can't collect them myself.\n\nYou see those shipwrecks nearby?  I bet they have just what I need if you can get to it and fish it out.  Take my fishing raft and see what you can find!  My buddy has been trying to help me out too so you might find some extra rafts near the wreckage, feel free to use em' too.", objectives = "" }
WordHunterWoW_QuestEN[30699] = { title = "To Winter's Blossom", description = "The battle against the Sha is eternal - we can not leave this place. \n\nBut I am troubled by the absence of reinforcements from the Monastery given that we sent for them days ago. \n\nYou have performed admirably, perhaps you could travel to Winter's Blossom, our base camp on the way to the Shado-Pan Monastery. Speak with Lin Silentstrike once you arrive - he should know what is happening. To get there, travel north of the village and follow the road through Shado-Li Basin to Winter's Blossom.", objectives = "" }
WordHunterWoW_QuestEN[30700] = { title = "Snapclaw", description = "A giant, poisonous crab is wrecking havoc on our local abalone stores.  I need you to go down into narsong trench and take it out!", objectives = "" }
WordHunterWoW_QuestEN[30701] = { title = "Viseclaw Soup", description = "Nothing tastes quite like viseclaw soup.  It's a krasarang specialty!\n\nI was just about to start up on a new batch when I realized I am missing a key ingredient, the eyes!\n\nI need you to kill the viseclaw fishers on the beach and return with their eyes for the soup!", objectives = "" }
WordHunterWoW_QuestEN[30704] = { title = "Hozen in the Mist", description = "", objectives = "" }
WordHunterWoW_QuestEN[30705] = { title = "Captain's Log", description = "", objectives = "" }
WordHunterWoW_QuestEN[30706] = { title = "Angry Scribblings", description = "", objectives = "" }
WordHunterWoW_QuestEN[30715] = { title = "A Line Unbroken", description = "When we regrouped after their initial attack, we numbered three less. You can fight, and we must plan our defense should these cursed yaungol attack again. \n\nIf you would help us, grant our fallen comrades their last rites, and recover their armor. You will find their bodies to the west, near the gate.\n\nAnd try to keep the birds off them.", objectives = "" }
WordHunterWoW_QuestEN[30716] = { title = "Chasing Hope", description = "Chi-Ji is always with us. Even when he is not here in the Cradle, pieces of his spirit run through the forests and beaches of the island, watching us and testing us.\n\nProve your dexterity in the eyes of Chi-Ji, {name}. Find and catch the spirits of the crane.", objectives = "" }
WordHunterWoW_QuestEN[30717] = { title = "Gifts of the Great Crane", description = "The cranes of Krasarang are a gift from Chi-Ji. Even the very feathers they leave behind are a gift for us to appreciate.\n\nWe use these feathers to adorn our garments and to fletch arrows. But first... they must be gathered.", objectives = "" }
WordHunterWoW_QuestEN[30718] = { title = "Students of Chi-Ji", description = "Our order prides itself on excellence in combat. We hone these combat skills by dueling one another, here on the Cradle of Chi-Ji.\n\nProve yourself in the eyes of the Red Crane. Venture south, into the center of the island, and duel with your fellow students.", objectives = "" }
WordHunterWoW_QuestEN[30723] = { title = "Honor, Even in Death", description = "Hmm... If Shado-Master Chong trusted you, perhaps you can help us.\n\nThe yaungol are our enemies.\n\nStill, we must prove we are better than they. We will show them honor in death.\n\nAs after most battles, the carrion birds have begun gathering. Thin their numbers, so the bodies of our foes will not be desecrated. They've gathered at the battlefield to the west.", objectives = "" }
WordHunterWoW_QuestEN[30724] = { title = "To the Wall!", description = "They are attacking again!\n\n<Lin looks to the Ox Gate.>\n\nArchers... on the wall!\n\nI need you to get up there. My wife Suna went to scout the wall with that fool Lao-Chen. Perhaps if he had spent more time preparing defenses and less building that ridiculous ale lift contraption...\n\nIt matters not. Get a kite from Len, to the west, and then get up there and find my wife. She'll know what to do next.", objectives = "" }
WordHunterWoW_QuestEN[30725] = { title = "Ellia Ravenmane", description = "We regularly organize one-on-one duels with trainees that we think are well-suited for one another. We have found one such trainee for you, {name}.\n\nHer name is Ellia Ravenmane. This will be her first duel, too. She will be waiting for you at the pavilion just to the south of here.", objectives = "" }
WordHunterWoW_QuestEN[30726] = { title = "Minh Do-Tan", description = "Your next challenger is another relatively new trainee. His name is Minh Do-Tan, and he has won his last two matches.\n\nHe will be waiting for you near the crane statue to the south.", objectives = "" }
WordHunterWoW_QuestEN[30727] = { title = "Ellia Ravenmane: Rematch", description = "Ellia Ravenmane requested a rematch with you. She seems to identify you as her \"rival\".\n\nWe discourage rivalries here within the Cradle of Chi-Ji, but we rarely decline a rematch request. You will find Ellia near the Pedestal of Hope, on the island's eastern side.", objectives = "" }
WordHunterWoW_QuestEN[30728] = { title = "Fat Long-Fat", description = "You have been matched with a... special trainee. His name is Fat Long-Fat.\n\n<Thelonius chooses his words carefully.>\n\nFat Long-Fat... operates outside of the normal rules of combat. He does not fight every day, and when he does, he chooses his competitor. Today, for some reason... he has selected you.\n\nYou will find him atop Angkhal Pavilion.", objectives = "" }
WordHunterWoW_QuestEN[30729] = { title = "Julia Bates", description = "We welcome all kinds here within the Cradle, as long as they recognize and subscribe to the ideologies of the Red Crane. One of our new, more exotic trainees comes from the human kingdoms to the northeast. She goes by the rather foreign-sounding name of Julia Bates.\n\nShe is your next challenger. You will find her on the island's western shore.", objectives = "" }
WordHunterWoW_QuestEN[30730] = { title = "Dextrous Izissha", description = "Jinyu normally avoid our order, but every few years, we find one that subscribes to the way of the Crane. One such jinyu is Dextrous Izissha.\n\nIzissha is your next challenger. He waits for you on the island's southwestern shore.", objectives = "" }
WordHunterWoW_QuestEN[30731] = { title = "Kuo-Na Quillpaw", description = "Most of the duels within the Cradle take place between two trainees. Rarely, when a trainee exhibits a rare amount of skill, they will have an opportunity to duel their trainer.\n\nToday, you duel against Kuo-Na. She will be waiting for you at the Pedestal of Hope.", objectives = "" }
WordHunterWoW_QuestEN[30732] = { title = "Ellia Ravenmane: Revenge", description = "Your \"rival\" has appeared again. Ellia Ravenmane has been avoiding her duties on the island, instead focusing on personal training, with the intent to defeat you in battle.\n\n\"I will destroy {name},\" she said.\n\nI have honored her request for a rematch, but I will be keeping a close eye on her. Her motives may be shifting in a dangerous direction.", objectives = "" }
WordHunterWoW_QuestEN[30733] = { title = "Tukka-Tuk", description = "You are making a name for yourself, {name}. I received a challenge from one of our more skilled competitors. He believes you are not as strong as you seem.\n\nHis name is Tukka-Tuk, the hozen. If you've ever fought against hozen before, you know that their apparent juvenility belies their battle acumen. Good luck.", objectives = "" }
WordHunterWoW_QuestEN[30734] = { title = "Huck Wheelbarrow", description = "Usually our trainees are adventurers like yourself, or monks from Tian Monastery, or occasionally retired Shado-Pan. Very rarely, though, we will greet trainees that have no fighting experience whatsoever.\n\nHuck Wheelbarrow is one such trainee. He has requested a duel with you. Look for him on the island's western shore.", objectives = "" }
WordHunterWoW_QuestEN[30735] = { title = "Mindel Sunspeaker", description = "Our highest-ranked trainee is an outsider like you. It is both strange and exciting to live in a time when so many foreigners have embraced the way of the Crane.\n\nYour challenger's name is Mindel Sunspeaker, and he awaits you within Angkhal Pavilion.", objectives = "" }
WordHunterWoW_QuestEN[30736] = { title = "Yan Quillpaw", description = "You have already defeated Kuo-Na Quillpaw. You have not yet fought her brother, Yan.\n\nHe will meet you at the Pedestal of Hope, and he will not hold back. His reputation as a trainer is at stake.", objectives = "" }
WordHunterWoW_QuestEN[30737] = { title = "Fat Long-Fat: Rematch", description = "Fat Long-Fat has requested another match with you. I find this strange. And concerning.\n\nHe will be waiting atop the Dome Belrissa.", objectives = "" }
WordHunterWoW_QuestEN[30738] = { title = "Thelonius", description = "When we last spoke, I promised to tell you the secret of Fat Long-Fat. I still plan to tell you that secret... after I determine your worth.\n\nI will meet you on the western shore, and we will duel.", objectives = "" }
WordHunterWoW_QuestEN[30739] = { title = "Ellia Ravenmane: Redemption", description = "Ellia Ravenmane, your rival, has returned. She demands that you meet her atop the Pedestal of Hope.\n\nYou need to understand, {name}... something horrible has happened to her. She has changed. You will see for yourself when you arrive at the pedestal.\n\nGood luck, {name}.", objectives = "" }
WordHunterWoW_QuestEN[30740] = { title = "Champion of Chi-Ji", description = "While you will always hold a place of honor among our order, you are still welcome to participate in our duels.\n\nOne of our current champions awaits you in the Dome Balrissa. I know that they would be honored to duel with you.", objectives = "" }
WordHunterWoW_QuestEN[30742] = { title = "Shut it Down", description = "I mussed up. Bad.\n\nIt's hard work cutting seeds out of kafa berries! But I noticed goots eat the berries up and give back the seeds... in a day or so.\n\nI fed everything I had to the goots on Kota Peak and now they're nuts! Chargin' everything that moves.\n\nKota used to be safe for Grummles to gather kafa. Not anymore. Not with them goots. Will you help?", objectives = "" }
WordHunterWoW_QuestEN[30743] = { title = "Gourmet Kafa", description = "It was genius: kafa berries go in the goot, seeds come out.\n\nKafa'kota is already rare and worth a fortune, but my invention--Kafa'goot--is GOURMET.\n\nBut it's over now. Uncle is upset and peak is a muss. All that's left is to collect the rest of the Kafa'goot and never make it again.\n\nI won't ask you to gather it--kind of a mussy task, not fit for hero-- just mark it so I can find it easily when the mountain is safe again.", objectives = "" }
WordHunterWoW_QuestEN[30744] = { title = "Kota Blend", description = "Kota Peak is famous for its kafa bushes - no other can survive at this elevation.\n\nGrummles make very good living selling Kafa'kota Blend, but it's dangerous now thanks to my cousin here. He's got the wildlife up there hooked on kafa with his scheming.\n\nKafa'kota is more scarce than ever with goots gobblin' it up and yetis hoarding it in their caves.\n\nI pay you good for any berries you bring down from Kota.\n\nHere, take a sample. Eat it. See for yourself the power of kafa.", objectives = "" }
WordHunterWoW_QuestEN[30745] = { title = "Trouble Brewing", description = "Lots of yetis in Kota, yup. Usually not too dangerous. Usually just eat goots.\n\nThen they ate the goots full of kafa...\n\n<Keenbean shoots Gootfur a mean glance.>\n\nNow they're moody, cranky, sleep a lot but never seem rested. Typical kafa addicts.\n\nGonna come outta those caves soon, I'm sure. Come lookin' for more kafa.\n\nThen we all in trouble.", objectives = "" }
WordHunterWoW_QuestEN[30746] = { title = "A Fair Trade", description = "<The roar bellows out again, louder and more fierce than any of the yetis you've encountered so far. Again, a grummle voice replies...>\n\nEep! Please, great Kota Kon, forgive grummle. Let me go, I'll bring lots of kafa right away! Promise!\n\n<The beast called Kota Kon answers with another meaty roar.>", objectives = "" }
WordHunterWoW_QuestEN[30747] = { title = "The Burlap Grind", description = "Okayyy... well, she's not eating anybody. That's a good start.\n\nShe must want more kafa, but we gotta give her somethin' to do with all the extra energy...\n\nI got it! The Burlap Trail! She can smash hozen out there all day!\n\n<Burrberry turns to the massive beast.>\n\nWhat do you think, pretty girl? Wanna smash hozens?!\n\nI think so. Here, feed her my emergency flask of kafa. She likes you.", objectives = "" }
WordHunterWoW_QuestEN[30750] = { title = "Off the Wall!", description = "The yaungol on the wall here are providing covering fire for the ones below. I don't know what Lao-chen is thinking, but I want you to deal with these archers.\n\nThe good news is, up here we've got the spirit of the Ox helping us. When they're weakened, the ox spirit will stun them and you can use it to knock 'em off the wall.\n\nYou'll find the archers just out that door.", objectives = "" }
WordHunterWoW_QuestEN[30751] = { title = "A Terrible Sacrifice", description = "I have an idea, and... am prepared to make a terrible sacrifice.\n\nAs much as I know that we need my stout brew, to fortify our defenders for the long-term security of the Ox Gate...\n\nIt is too painful to discuss details now, but please - while you are up here defending the wall, gather the barrels of oil they are using to light their arrows. We will need them.", objectives = "" }
WordHunterWoW_QuestEN[30752] = { title = "Unbelievable!", description = "I simply refuse to believe the guards will not grant us entry to the monastery should we impress upon them the seriousness of the situation.\n\nFriend, go east, to the sentinel in front of the Monastery, and demand admittance. I will come with you.", objectives = "" }
WordHunterWoW_QuestEN[30753] = { title = "Jumping the Shark", description = "There is only one way to kill sharks where I come from, with your bare hands!\n\nI dumped a good amount of chum in the water just off the dock here, this place should be crawling with the local reef sharks in no time.  Hop on the first one you see and take it out!", objectives = "" }
WordHunterWoW_QuestEN[30754] = { title = "Bright Bait", description = "Certain fish are only attracted to bright lights.  The forest north of here is home to a local pandaren firefly called a suncrawler.\n\nYou should be able to find them on the base of the tree trunks all around that area.  Bring me back a handful of them and I can use them for bait!", objectives = "" }
WordHunterWoW_QuestEN[30757] = { title = "Lord of the Shado-Pan", description = "Our lord, Taran Zhu, has been overcome by a sha of pure hatred. The whole monastery has been lost!\n\n{class}, you must find a way to free him of this possession. Last I knew, he was meditating in the Grove of Falling Blossoms.", objectives = "" }
WordHunterWoW_QuestEN[30763] = { title = "Piranha!", description = "Certain fish are very difficult to catch.  The wolf piranha falls squarely into this category.\n\nLucky for me that you showed up!  Put those fishing skills to the test and bring me back a few from the krasarang river due northwest of here.", objectives = "" }
WordHunterWoW_QuestEN[30765] = { title = "Regaining Honor", description = "{name}, the yaungol warchief, Humongous, killed Shado-Master Zhen. He has his banner.\n\nYou have to kill Humongous and regain Zhen's honor! If you don't, I will.", objectives = "" }
WordHunterWoW_QuestEN[30766] = { title = "Profiting off of the Past", description = "<A relic drops off of the statue. Hmm, these could prove to be valuable to the right person.>\n\n<There's a collector on the outskirts of the ruins. Perhaps he'd be interested in purchasing them from you?>", objectives = "" }
WordHunterWoW_QuestEN[30767] = { title = "Risking It All", description = "Wait, what?! How could he be so reckless? Blowing the ship free is insane! They could kill Shen-zin Su, and all of us with it. \n\nI know we don't have much time, but we need to think of another way...", objectives = "" }
WordHunterWoW_QuestEN[30768] = { title = "My Husband...", description = "Lin...\n\nI don't care what Ban, Lao-Chin, or even Taran Zhu says. I'm moving ahead into Townlong. I may not be able to save Lin myself, but I'm not going to sit around waiting for everyone else to catch up.\n\nOnce Taran Zhu opens the doors to his precious monastery, we'll save Lin. Until then, I'll scout ahead and make sure he's alright.", objectives = "" }
WordHunterWoW_QuestEN[30769] = { title = "First Assault", description = "Now that we have had time to assess our enemies' weaknesses, it is time for us to deal the yaungol a direct blow.\n\nGo and confront the Osul Sharphorn up the mesa to the west.\n\nLet them know that we are here, and that we are not scared of their threats.", objectives = "" }
WordHunterWoW_QuestEN[30770] = { title = "Running Rampant", description = "There is one thing that every army needs, and that is a supply line.\n\nThe enemy camp to the west contains a large beast herd, which serves as the yaungol army's main source of food.\n\nLuckily for us, the yaks and mushan beasts of this region are easily scared.\n\nSneak in, give the beasts a good slap, and watch the results.", objectives = "" }
WordHunterWoW_QuestEN[30771] = { title = "Perfect Pitch", description = "When the Osul tribe goes to war, they coat their spears and arrows with a highly flammable, ever-burning pitch.\n\nThey use this terrible weapon to shed not only blood, but to raze the homes of their enemies.\n\nI need you to collect some of this pitch while you are in their camp.\n\nWe will use it to show the yaungol that when you play with fire, you can get burned.", objectives = "" }
WordHunterWoW_QuestEN[30772] = { title = "Seeing Red", description = "Ahead of us is the main thrust of the yaungol army.\n\nHere, they prepare their vast army to attack the villages of Kun-Lai.\n\nIf we strike at the Osul now, we can cut them at their very core.\n\nRemember, for every of their number that we strike down here, we save one of our own back at home.", objectives = "" }
WordHunterWoW_QuestEN[30773] = { title = "Pitching In", description = "The yaungol's siege weapons - those ballista spearthrowers down there - are tearing apart our defenses both at Longying Oupost and in Kun-Lai Summit.\n\nThose terrible weapons must be destroyed.\n\nTake these explosives. I've covered them in the pitch that you collected.\n\nToss them at those ballistas, and we'll give the yaungol a little taste of their own medicine.", objectives = "" }
WordHunterWoW_QuestEN[30774] = { title = "Ranger Rescue", description = "I must ask a most important task of you, {name}.\n\nSomewhere among the cages in the Osul camp is my husband, Lin. He is the light of my world.\n\nPlease find him and return him to me, and save as many of our fellow Shado-Pan as you can as well.\n\nYou should find keys to those cages on the Osul Marauders.", objectives = "" }
WordHunterWoW_QuestEN[30775] = { title = "The Exile", description = "What is there to say, stranger?\n\nI fought Jung Duk and lost. I was the fool to believe he would fight fairly.\n\nNow, my own brothers turned against me, and here I am, speaking to our enemies.\n\nI know you have come for Osul blood.\n\nI only ask that you hunt down the three who betrayed me.\n\nUrang, who poisoned my drink. Ku-Tong, who bent my spear. And Battat, whose dagger slipped into my side as my victory was assured.\n\nDo this, and I can die in peace.", objectives = "" }
WordHunterWoW_QuestEN[30776] = { title = "Jung Duk", description = "THIS. IS. WAR.\n\nI will have the heads of everyone who took Lin from me. EVERYONE!\n\nWe will begin with the Osul leader, Jung Duk.\n\nTake this Shado-Pan war banner and place it at the center of their camp.\n\nJung Duk will have no choice but to face you.\n\nShow him no mercy, {name}.", objectives = "" }
WordHunterWoW_QuestEN[30777] = { title = "In Search of Suna", description = "I have bad news. When I returned, Suna was already gone.\n\nThe others say that she took her things and headed down the road to the east, muttering about hunting down the source of the yaungol aggression.\n\nI cannot allow her to venture into dangerous territory alone.\n\nI've already prepared a group of soldiers to push further east.\n\nWe are leaving shortly. Hop on the caravan if you wish to travel with the Shado-Pan. You can also meet us there if you wish.", objectives = "" }
WordHunterWoW_QuestEN[30778] = { title = "Dust to Dust", description = "If we are to make camp here, we cannot leave all of these yaungol bodies lying to rot.\n\nTake this torch and set fire to the villagers' corpses.\n\nThe incense from the torch should purify the earth and air around them as well.\n\nEven our enemies deserve to be laid to rest.", objectives = "" }
WordHunterWoW_QuestEN[30779] = { title = "Slaying the Scavengers", description = "The rotting corpses are attracting hyena scavengers.\n\nIn addition to spreading diseases from feeding on the dead, the feral creatures will attack us on sight.\n\nGo and eradicate the beasts. It is unfortunate, but ultimately for the best.", objectives = "" }
WordHunterWoW_QuestEN[30780] = { title = "Totemic Research", description = "As we entered the village, I couldn't help but notice yaungol totems lying around this camp.\n\nI have a suspicion that there are dark forces at work here, and those totems may be the key to drawing them out.\n\nCould you bring me some of these totems for further inspection? I would like to study them.", objectives = "" }
WordHunterWoW_QuestEN[30781] = { title = "Last Toll of the Yaungol", description = "Ban has asked me to explore the village to determine what happened here.\n\nI noticed smoke rising up from the east, the west, northwest, and the south.\n\nI need someone I trust to watch my back.\n\nWhat do you say? Want to help me on my first scouting mission?", objectives = "" }
WordHunterWoW_QuestEN[30782] = { title = "Spiteful Spirits", description = "The spirits of the fallen villagers have risen! I can feel the hatred emanating from the spirits.\n\n{name}, if we are to survive here, we must defend ourselves. This is the only way we can put them to rest.", objectives = "" }
WordHunterWoW_QuestEN[30783] = { title = "Hatred Becomes Us", description = "I should have suspected a sha presence earlier!\n\nWe are safe as long as we stand inside the Totem of Harmony's protective wards, but many of our people were not so lucky.\n\nThey were trapped outside the camp when the sha's powers manifested, and now they turn upon each other!\n\nTake one of my totems with you. Place the totem near a crazed ally to purify them, but beware.\n\nYou may have to face the darkness that gripped them.", objectives = "" }
WordHunterWoW_QuestEN[30784] = { title = "The Point of No Return", description = "One of our rangers reported seeing Suna up the hill to the northwest.\n\nI am relieved to find her safe. I had feared what she would do in her grief.\n\nWould you go speak to her on my behalf?\n\nTake this totem with you. If you encounter any danger along the way, you may find it useful.", objectives = "" }
WordHunterWoW_QuestEN[30785] = { title = "Gao-Ran Battlefront", description = "With your help, we have quelled the spirits of this place.\n\nAt last, they may rest in peace.\n\nOur journey into this cursed land, I am afraid, has only begun.\n\nI have some important matters to finish up here, but we will be moving out soon.\n\nI need someone to go ahead and tell Lord Taran Zhu that we are joining him.\n\nFind him at the Gao-Ran Battlefront. Tell him what has transpired here.", objectives = "" }
WordHunterWoW_QuestEN[30786] = { title = "A Spear Through My Side, A Chain Through My Soul", description = "My fate is sealed. The yaungol put this spear in my side. The wound will kill me.\n\nThe yaungol hold me in place with their twisted, corrupted magic. The indignity of it hurts worse than my spear-wound.\n\nMy death, I cannot stop. My imprisonment... you may be able to help me with this.", objectives = "" }
WordHunterWoW_QuestEN[30787] = { title = "The Torches", description = "Until recently, the yaungol shaman would come here to work alongside us. Now, they bend my people to their will.\n\nIf we refuse, they kill us. Even if we oblige... they kill us.\n\nThe yaungol mist-shaman's magic flows through his torch. Take his torch away, and he has nothing.", objectives = "" }
WordHunterWoW_QuestEN[30788] = { title = "Golgoss", description = "The leader of the yaungol mist-shaman is named Jahesh. He is known for his strength.\n\nOne of my kind is also known for his strength. His name is Golgoss.\n\nGolgoss sleeps within the mists of the Upper Sumprushes. Help me to summon him, and he will join me in avenging our people.", objectives = "" }
WordHunterWoW_QuestEN[30789] = { title = "Arconiss", description = "If I am to fight Jahesh, leader of the yaungol mist-shaman, I must have Arconiss by my side. Arconiss' ferocity is second to none.\n\nHe rests beneath the mists of the Upper Sumprushes. Find his resting place, and then use these torches to awaken him.", objectives = "" }
WordHunterWoW_QuestEN[30790] = { title = "Golgoss Hungers", description = "Golgoss' strength is great, but he requires nutrition before he can use it.\n\nThe snarlthorn bushes in the Upper Sumprushes have heavy, fibrous branches. These should sate his appetite.", objectives = "" }
WordHunterWoW_QuestEN[30791] = { title = "Arconiss Thirsts", description = "Arconiss fights with unmatched fury, but his extended stay beneath the mists has left him weakened.\n\nThe rodents of the swamp are plentiful, and their bodies are filled with nourishing blood. Return with blood enough to reignite Arconiss' spirit.", objectives = "" }
WordHunterWoW_QuestEN[30792] = { title = "Orbiss Fades", description = "I knew death would come. I did not know that it would come this fast.\n\nI must buy time. The mist of the Upper Sumprushes is warm and fragrant. Such mist is nutritive to my kind.\n\nGather this mist however you can... in jars, in vials, within the interior of your bags. Bring it back to me, and I can use it to remain corporeal for a bit longer.", objectives = "" }
WordHunterWoW_QuestEN[30793] = { title = "Mists' Opportunity", description = "Now is the time to strike.\n\nGolgoss, Arconiss, and I will go east, into Jahesh's domain. Meet us there, and prepare for battle.\n\nToday, we restore the pride of our people.", objectives = "" }
WordHunterWoW_QuestEN[30794] = { title = "Emergency Care", description = "I... am alive... but barely. They killed the rest. My friends... and family...\n\nI must return to the village... But, I do not have long, and cannot move on my own... are you a healer? I... have a healing potion in my hut... search my belongings. You can use your magic, if you have it.", objectives = "" }
WordHunterWoW_QuestEN[30795] = { title = "Staying Connected", description = "The Tongue of Ba-Shon should allow us to communicate from long distances, {name}.\n\nIf the relic works the way I think it will, I should be able to stay here and continue my meditations while you do some scouting in the Valley of Emperors.\n\nMishi will take you to the edge of the valley so that we can test my theory. I would hate for you to be in the tombs with no way to contact me. That would be horrible!", objectives = "" }
WordHunterWoW_QuestEN[30796] = { title = "An End to Everything", description = "These spirits must have been released when the tombs were opened... \n\nDeath was not final for the Mogu. Instead, death was merely a stop over on the path to a new body. Spiritbinders used a foul magic to transfer spirits from one shell to the next.\n\nYears of being trapped in the tombs has left them confused. They need to be destroyed before their confusion turns to anger or worse, they find a new shell.", objectives = "" }
WordHunterWoW_QuestEN[30797] = { title = "It Was Almost Alive", description = "A ritual took place here, and from the looks of it wasn't successful.\n\nAmong the abandoned items a book lies open. The text on the pages is foreign to you.\n\nCarrying the whole book may be difficult, but a single page might be enough. If you can get the page to Lorewalker Cho he may be able to tell you what it says.", objectives = "" }
WordHunterWoW_QuestEN[30798] = { title = "Breaking the Emperor's Shield", description = "The Mogu have been scattered and sparse in number for many years. Their purpose in the valley makes sense now.\n\nWith this many restless spirits they can build themselves an army using the guardians buried in each tomb. Combined with the Zandalari forces this would be devastating!\n\nThe Tomb of Secrets houses elite warriors called the Emperor's Shield. They must not be resurrected! You'll find the tomb on the highest rise to the southwest. ", objectives = "" }
WordHunterWoW_QuestEN[30799] = { title = "The Tomb of Shadows", description = "Given the artifacts you found on the altar, I would guess they were attempting to perform a Spiritbinding ritual.\n\nMost of the texts involving Spiritbinding were locked away in the Tomb of Shadows. Perhaps we will find the answers we seek there.\n\nLook for anything that might help us. You'll find the tomb on the first rise closest to the ritual altar.", objectives = "" }
WordHunterWoW_QuestEN[30800] = { title = "Stealing Their Thunder King", description = "Our only hope is to find the Thunder King's remains before they do. He must be buried within the Tomb of Conquerors.\n\nGetting to his remains will not be easy, {name}. The tomb will no doubt be defended by guardians and other unfriendly surprises intended to ward off thieves.\n\nOnce inside we will need to figure out where his remains have actually been placed.", objectives = "" }
WordHunterWoW_QuestEN[30801] = { title = "Lessons from History", description = "The Thunder King was a vicious Emperor and with the Zandalari at his side he was unstoppable. His return would surely return this land to turmoil and misery.\n\nYou must locate his remains and take them somewhere safe. The Tablet of Thunder should help you figure out how to access his tomb.", objectives = "" }
WordHunterWoW_QuestEN[30802] = { title = "Chasing the Storm", description = "We need to figure out where they are taking the Thunder King's remains. It won't be possible for them to resurrect him in the Valley of the Emperors. They would need to be somewhere remote and secure.\n\nIt appears that getting out of here may also prove to be a challenge....\n\nFight your way out and look for information concerning the location of the remains.", objectives = "" }
WordHunterWoW_QuestEN[30804] = { title = "The Fearmaster", description = "I am not gonna take this anymore. My wife, bless her, poured her heart and soul in to that ranch making it what it is today.\n\nThem yaungol got a leader over there being all smug and what not. I'll pay you handsomely if you knock that smug smile off his filthy, stinking, good for nothing face.", objectives = "" }
WordHunterWoW_QuestEN[30805] = { title = "Justice", description = "After the mercenaries robbed us, most left.\n\nBut one of them... after the others took all we had, he ran the rest of us through. For sport!\n\nGet justice for the fallen. Perhaps news of their death will raise my spirits enough to go on.\n\nYou'll find them just west of here.", objectives = "" }
WordHunterWoW_QuestEN[30806] = { title = "The Scent of Life", description = "Many have perished here. We will need to honor them properly, which means gathering the makings of incense of life. \n\nIt doesn't just smell nice - it has restorative properties, and can even help plants grow. Maybe I can get a whiff of the ingredients to get me back on my feet.\n\nThe materials can be found on creatures around here - except for the spices, which were stolen by the mercenaries who pillaged the village. ", objectives = "" }
WordHunterWoW_QuestEN[30807] = { title = "By the Falls, For the Fallen", description = "I do not wish to dishonor my friends and leave them in unmarked graves.\n\nYet, we have never needed to bury so many at once, and I am in no condition to gather materials.\n\nPlease, visit the lakes that hug the mountains edge along the road to the south. Underneath the waterfalls there, you will find stones that have been polished to a sheen by the falling water. They will make suitable headstones.", objectives = "" }
WordHunterWoW_QuestEN[30808] = { title = "A Grummle's Luck", description = "The yaungols stole our luckydos! Mean riders with spears took them from our caravan of brothers coming down the Burlap Trail.\n\nThis is very bad fortune. If the yaungol discover the secrets of luckydos all grummles will be in big trouble.\n\nRecover our luckydos from Fire Camp Ruqin north of here and we will pay many fortunes to you.", objectives = "" }
WordHunterWoW_QuestEN[30814] = { title = "A Foot in the Door", description = "<Lord Taran immediately pins you down with his steely gaze.>\n\n{class}, you bear the marks of many a past battle.\n\nGood! We need more seasoned people like you to hold back the front.\n\nWe've managed to secure a foothold here, but the yaungol are desperate to remove our presence.\n\nIf you wish to prove your worth, go down the hill and show the yaungol that we will not back down.", objectives = "" }
WordHunterWoW_QuestEN[30815] = { title = "The Death of Me", description = "I have resolved to remove this spear from my side.\n\nFor this, I require your assistance. Your grasping hands are stronger than mine.", objectives = "" }
WordHunterWoW_QuestEN[30816] = { title = "Checking In", description = "When the trolls came, they brought their mercenary... friends with them. I saw them go past us, to the fishing camp in the northwest. My cousin, a healer, lives there - can you check in with him and make sure he and his village are well?", objectives = "" }
WordHunterWoW_QuestEN[30817] = { title = "The Healing of Shen-zin Su", description = "This is what comes of such recklessness. How could he think this was even a possibility?\n\nNevermind, there's no time for that now. We need to act to save Shen-zin Su.\n\nFind any healers you can! Rescue them, relieve them - whatever you need to do to get them over here healing the wound.\n\nKeep the healers safe at all costs!", objectives = "" }
WordHunterWoW_QuestEN[30818] = { title = "A New Fate", description = "{name}, I'm thankful the plan worked, but just barely. We would be sinking to the bottom of the ocean with all of Shen-zin Su if you hadn't been here. I don't think I can ever forgive Ji for this kind of recklessness.\n\nThere will be plenty of time for reflection, but for now, we need to return to the Temple of Five Dawns. We need to let them know that Shen-zin Su has been saved, and we need to sort out the fates of these new allies.", objectives = "" }
WordHunterWoW_QuestEN[30819] = { title = "Preparing the Remains", description = "Thank you much, friend. After this tragedy, it is good that fortune has smiled on us and sent you.\n\nYou have gotten justice for my fallen friends, and gathered the necessary materials to honor them. I will gather their bodies, prepare the materials for their funerals, and meet you at the graveyard. \n\nIn the meantime, however, please return to my cousin and ask him to gather the villagers for the funeral.", objectives = "" }
WordHunterWoW_QuestEN[30820] = { title = "A Funeral", description = "As I said, I will gather the town - we will be at the funeral. \n\nAs the one who has done so much to honor our friends, we feel it is only right that you will be the one to light the Incense of Life and usher their spirits to the life beyond.", objectives = "" }
WordHunterWoW_QuestEN[30821] = { title = "The Burlap Grind", description = "Alright, it's time to take Kota Kon out for her \"walk.\"\n\nWe brewed two fresh pots of kafa just for her and she's all fueled up!", objectives = "" }
WordHunterWoW_QuestEN[30823] = { title = "Shut it Down", description = "My cousin over at Kota Basecamp mussed up. He mussed up bad.\n\nHe was too lazy to cut seeds out of kafa berries by hand, but he noticed goots eat the berries up and give back the seeds... in a day or so.\n\nHe fed everything he had to the goots on Kota Peak and now they're nuts! Chargin' everything that moves.\n\nKota used to be safe for Grummles to gather kafa. Not anymore. Not with them goots. Will you help?", objectives = "" }
WordHunterWoW_QuestEN[30824] = { title = "Gourmet Kafa", description = "It was a crazy idea: kafa berries go in the goot, seeds come out.\n\nKafa'kota is already rare and worth a fortune, but my cousin's invention--Kafa'goot--is GOURMET.\n\nBut it's over now. Uncle Keenbean is upset and peak is a muss. All that's left is to collect the rest of the Kafa'goot and never make it again.\n\nI won't ask you to gather it--kind of a mussy task, not fit for hero-- just mark it so we can find it easily when the mountain is safe again.", objectives = "" }
WordHunterWoW_QuestEN[30825] = { title = "Kota Blend", description = "Kota Peak is famous for its kafa bushes - no other can survive at this elevation.\n\nGrummles make very good living selling Kafa'kota Blend, but it's dangerous now thanks to our cousin. He's got the wildlife up there hooked on kafa with his scheming.\n\nKafa'kota is more scarce than ever with goots gobblin' it up and yetis hoarding it in their caves.\n\nUncle Keenbean will pay you good for any berries you bring down from Kota.\n\nHere, take a sample. Eat it. See for yourself the power of kafa.", objectives = "" }
WordHunterWoW_QuestEN[30826] = { title = "Trouble Brewing", description = "Lots of yetis in Kota, yup. Usually not too dangerous. Usually just eat goots.\n\nThen stupid Cousin Gootfur over at Kota Basecamp fed kafa to the goots, and the yeti ate them goots.\n\nNow they're moody, cranky, sleep a lot but never seem rested. Typical kafa addicts.\n\nGonna come outta those caves soon, I'm sure. Come lookin' for more kafa.\n\nThen we all in trouble.", objectives = "" }
WordHunterWoW_QuestEN[30827] = { title = "What Lies Beneath", description = "If my suspicions are correct, this place still reels from some lingering darkness.\n\nWhatever happened here... it could not have been the natural course of events.\n\nEven the yaungol are not so brutal as to slaughter their own kind to the point of... this.\n\nI will use the totems that you brought me to perform a cleansing ritual.\n\nI need someone to assist me in the ceremony. Let me know when you are ready.", objectives = "" }
WordHunterWoW_QuestEN[30828] = { title = "Cleansing the Mere", description = "Pools of the same murky substance that came out of Mei emerged in the lake recently.\n\nI will travel into the Mere with you. Point out the pools of corruption that you are ready for me to cleanse.\n\nYou will need to deal with whatever comes out and protect me as I complete the ritual.", objectives = "" }
WordHunterWoW_QuestEN[30829] = { title = "The Tongue of Ba-Shon", description = "Thank you for coming, {name}. I am sorry to have been so cryptic, but I could not risk alerting the mogu to my work here.\n\nThey are seeking something in the valley. Plundering the tombs of their old kings for relics of power.\n\nI could not observe them long before having to flee, but I did manage to recover a relic of my own.\n\nThe Tongue of Ba-Shon will let us communicate securely over long distances, but only after I have bound it to myself.\n\nI think I'm ready to begin, if you are.", objectives = "" }
WordHunterWoW_QuestEN[30834] = { title = "Father and Child Reunion", description = "They survived? My father is alive!\n\nI thought we would all die here in this horrible mere, at the hands of these insane Jinyu.\n\nI will find my way back - meet me back at camp.", objectives = "" }
WordHunterWoW_QuestEN[30855] = { title = "The Fall of Shai Hu", description = "I can hear the voice of the Mere - it has been purified.\n\nBut, this chapter in my people's history will never be closed - not until we defeat Shai Hu.\n\nHe has retreated to the central island in the Mere, corrupting our holiest of sites.\n\nBeware - he is strong. But, after all we have done, I am confident we will be stronger.", objectives = "" }
WordHunterWoW_QuestEN[30879] = { title = "Round 1: Brewmaster Chani", description = "Welcome, Challenger, to my tournament of champions! Today we test the strengths of Pandaria's most dedicated heroes.\n\nYour first opponent awaits you under the eastern gazebo. Defeat her, and you may proceed to the next round.\n\nFight with strength, fight with honor.", objectives = "" }
WordHunterWoW_QuestEN[30880] = { title = "Round 1: The Streetfighter", description = "Welcome, challenger, to my tournament of champions! Today we test the strengths of Pandaria's most dedicated heroes.\n\nYour first opponent awaits you under the eastern gazebo. Defeat her, and you may proceed to the next round.\n\nFight with strength, fight with honor.", objectives = "" }
WordHunterWoW_QuestEN[30881] = { title = "Round 2: Clever Ashyo & Ken-Ken", description = "You may know your next challengers. They were arguing fiercely when they arrived, so I have charged them with fighting side by side.\n\nThis will teach them the strength of friendship, and possibly entertain me in the process.\n\nGo to the north eastern arena and face this jinyu and hozen.\n\nDo not be gentle, they need to learn to work together.", objectives = "" }
WordHunterWoW_QuestEN[30882] = { title = "Round 2: Kang Bramblestaff", description = "Your next challenger is a Bramblestaff. Strength is in their blood. I remember a full century of only Bramblestaff champions.\n\nNo pressure, little {race}.\n\nGo to the eastern arena north of here and face this young challenger. See first hand if strength is earned or inherited. ", objectives = "" }
WordHunterWoW_QuestEN[30883] = { title = "Round 3: The Wrestler", description = "Your next challenger is a favorite of mine. He draws strength from raw force and determination.\n\nPlus he has a mask.\n\nFace him in the western arena when you are ready, and good luck.", objectives = "" }
WordHunterWoW_QuestEN[30884] = { title = "Behind the Battlefront", description = "This battlefront has been undermanned and unsupplied for too long during my absence in Kun-Lai. We need to get things back in order here before we can pick up the trail of the Sha of Hatred.\n\nTaoshi is my best. I've sent her north to investigate rumors of mantid that have somehow made it through the battlefront. I need someone I can trust to get out there and work with her to plug any holes in our defenses.\n\nIf my reports on you are correct, I can trust you with this, right {class}?", objectives = "" }
WordHunterWoW_QuestEN[30885] = { title = "Round 3: Master Boom Boom", description = "Your next challenger found his strength on a beach. Particularly in a box labeled \"dynamite.\"\n\nHe proves however that found strength can be as deadly as personal strength.\n\nWhen you are ready, face this Master Boom Boom in the Western Arena.", objectives = "" }
WordHunterWoW_QuestEN[30887] = { title = "Unwelcome Intruders", description = "Those are mantid scouts down there. Gao-Ran's Battlefront is meant to keep them out of eastern Townlong Steppes. If we allow them north of the barricade, we may lose our foothold here.\n\nLet's clear them out. I'll be with you.", objectives = "" }
WordHunterWoW_QuestEN[30888] = { title = "Breach in the Defenses", description = "Normally, it only takes a few scouts to hold this pass. Most of this territory is in sight of the wall, so archers would devastate any mantid force attempting to push through here. The problem is, most of the archers are occupied with the onslaught at the gate.\n\nTake this flare - it will help you locate the mantid that are sneaking through the eastern pass under our diminished watch. Kill any you find. We can't let them lay a trail that might lead the mantid swarms farther into the steppes.", objectives = "" }
WordHunterWoW_QuestEN[30889] = { title = "Trap Setting", description = "Good to meet you, {class}. We have traps all along the pass to help us catch mantid that might be sneaking through, but their numbers have been so great that most of the traps have already been triggered.\n\nTaoshi said you might be able to reset some of them while you're out there. Can you help?", objectives = "" }
WordHunterWoW_QuestEN[30890] = { title = "The Restless Watch", description = "I'm being told that our scouts have been on duty in Shallowstep Pass for more than 2 days straight, no rest. No wonder mantid are slipping through. Even the most dedicated scouts would slip with those kinds of shifts.\n\nI want you to go out there and deliver orders to the scouts that they are to return to the battlefront immediately for rest and rations. I'll arrange for a new shift to be posted.", objectives = "" }
WordHunterWoW_QuestEN[30891] = { title = "Treatment for the Troops", description = "A new face! Pleasure to meet you. I'm Septi. I keep the Shado-Pan fighting.\n\nThe mantid have poison that chews through the skin and infects the blood. It makes for a slow, excruciating death when not treated.\n\nI need pollen from the violet citron flowers. The nearest place to find them is around Dampsoil Burrow just north of the battlefront. If you happen to go in that direction, could you bring some back for me?", objectives = "" }
WordHunterWoW_QuestEN[30892] = { title = "Back on Their Feet", description = "{name}, I could use your help. With their long shifts, our warriors down at the southern front of the battlefront are fighting to the point of exhaustion, and many of them have been exposed to the mantid poison.\n\nWe need more people to tend to the wounded. I've prepared some bandages with the herbs you brought me, but if you have some healing skills, those might work even better.\n\nPlease, {name}, get our men back on their feet so that they can get back here to safety.", objectives = "" }
WordHunterWoW_QuestEN[30893] = { title = "The Endless Swarm", description = "Gao-ran's men need help down on the southern front. If you want to stand by the Shado-Pan, that's where you should do it.", objectives = "" }
WordHunterWoW_QuestEN[30894] = { title = "Rummaging Through the Remains", description = "I do have another task for you, {name}, though it's a might grim. I really need to get to the bottom of this mantid poison, but to do that, I need more information directly from the source.\n\nWhile you're down on the southern battlefield, could you bring me back some mantid limbs so that I can examine their intact poison glands.", objectives = "" }
WordHunterWoW_QuestEN[30895] = { title = "Improvised Ammunition", description = "I've got another job for you.\n\nThe dragon cannons we depend on to keep the thicker swathes of mantid back are running low on ammo. The camp's cannoneers developed an improvised explosive that's made from the globe seeds down the western ridge.\n\nThey dispatched a couple initiates to bring some back hours ago, but have heard nothing from them. I want to send someone a bit more capable to make sure that this gets taken care of.\n\nAre you my man for this?", objectives = "" }
WordHunterWoW_QuestEN[30896] = { title = "Thieves and Troublemakers", description = "I can't catch the little buggers for the life of me.\n\nKill any you can get your hands on. And keep a close eye on your valuables, they like to steal anything that isn't tied down.", objectives = "" }
WordHunterWoW_QuestEN[30897] = { title = "In the Wrong Hands", description = "Look... um... this is really embarrassing. I set down my sword for like ONE SECOND to gather some orbs, and a big sprite sprung out of nowhere, snatched it, and bounded off down the western gap.\n\nI can't go back to camp without it. Losing your weapon is a sure way to get kicked out of the Shado-Pan. It's sacred.\n\nPlease, can you try to find this big sprite and get my sword back? It would mean a lot to me.", objectives = "" }
WordHunterWoW_QuestEN[30898] = { title = "Cutting the Swarm", description = "The mantid numbers have been increasing since you left for the cleft. Let's put these orbs you gathered to use.\n\nGet down on the battlefront and man one of the cannons. Let none through.", objectives = "" }
WordHunterWoW_QuestEN[30899] = { title = "In Skilled Hands", description = "{name}, take these crossbow bolts and then bring them to Hawkmaster Nurong at Farwatch Overlook to the southwest.\n\nNurong is praised among all the Wukao for being a flawless shot. His efforts are credited with holding the line here for these many months. I'm hoping you can work with him and judge for yourself. He may be the final Shado-Pan we need for the hunt.", objectives = "" }
WordHunterWoW_QuestEN[30900] = { title = "Terror of the Dread Wastes", description = "That thing is huge!\n\nThe Shado-Pan holding the battlefront were never trained for something like this... let's get down there and take it out ourselves.", objectives = "" }
WordHunterWoW_QuestEN[30901] = { title = "Along the Southern Front", description = "I'm heading westward with Taoshi to gather the strongest I can find to confront the Sha of Hatred.\n\nI would like you to come with me.", objectives = "" }
WordHunterWoW_QuestEN[30902] = { title = "Round 4: Master Windfur", description = "Well done, challenger. You have reached the final round.\n\nYour last opponent is a powerful master of the winds. He has defended his people for many years and stood as champion on more than one occasion.\n\nFace this Master Windfur in the main arena when you are ready.\n\nAnd challenger... good luck.", objectives = "" }
WordHunterWoW_QuestEN[30907] = { title = "Round 4: The P.U.G.", description = "And now the final round. I have selected three challengers for you to face. This may seem unfair... to a weakling. You are not a weakling, correct?\n\nGo to the main temple, stand in the grand arena, and face these three challengers. Prove you are stronger than their combined power!\n\nGood luck, Challenger!", objectives = "" }
WordHunterWoW_QuestEN[30921] = { title = "The Motives of the Mantid", description = "{class}. You may be of assistance.\n\nThe Shado-Pan wishes to know why the mantid are attacking so violently. We have our suspicions, but we cannot be sure. Furthermore, we do not want the mantid to know that we are investigating them.\n\nThat's where you come in.\n\nI need you to kill the mantid of Kri'vess, in the north. I will lurk behind you in the shadows, and search for clues on their bodies.", objectives = "" }
WordHunterWoW_QuestEN[30922] = { title = "Natural Antiseptic", description = "The Shado-Pan are rare, elite, and quite expensive to train and replace. We can't afford to have any falling to a poisoned weapon or an infected cut. That's why I need you to get... something.\n\nLet me be blunt. Mushan urine is a great, natural antiseptic. They produce a large amount of it, which is lucky... because we tend to use a lot.", objectives = "" }
WordHunterWoW_QuestEN[30923] = { title = "Set the Mantid Back", description = "Every day, the mantid build up munitions for use on their enemies. We cannot stop them, just you and I... but we can set them back.\n\n<Tai Ho hands you some explosives.>\n\nI need to keep a low profile. Would you do the honors?", objectives = "" }
WordHunterWoW_QuestEN[30924] = { title = "The Wisdom of Niuzao", description = "Niuzao, the Black Ox, rests in the temple to the west. He may know why the mantid are attacking.\n\nHe may, in fact, know much more than that.\n\nI will rendezvous with you at Niuzao Temple, {class}.", objectives = "" }
WordHunterWoW_QuestEN[30925] = { title = "Niuzao's Price", description = "Niuzao owns a statuette which he values greatly: a small icon, in his image, sculpted by one of his long-since fallen sentinels. This statuette was recently stolen by the Sra'thik mantid, and taken to their encampment to our north.\n\nBring back this statuette. Then we will give you - and your Shado-Pan associate - the answers you seek.", objectives = "" }
WordHunterWoW_QuestEN[30926] = { title = "The Terrible Truth", description = "It is with a heavy heart that I confirm your suspicions. The mantid are indeed under the sway of the Sha of Fear.\n\nIt was OUR sworn duty to confine that creature beneath our temple. Unfortunately, our vigil faltered, our defenses buckled, and the sha escaped. It is with the mantid now.\n\nSee for yourself. The mantid burrowed into the western side of our island.", objectives = "" }
WordHunterWoW_QuestEN[30927] = { title = "Give Them Peace", description = "I overheard. Our secret is out, then.\n\nWhen I learned that the mantid had burrowed beneath our temple, I reacted hastily. I sent dozens of guardians to defend what they could, but they were not prepared. They succumbed to fear, and never returned.\n\nA pandaren deserves to die embracing the ground, as he does in sleep... not flat on his back with his eyes transfixed in terror. Please, {name}. Give them the peace they deserve.", objectives = "" }
WordHunterWoW_QuestEN[30928] = { title = "A Trail of Fear", description = "You now know Niuzao's secret. We are not only the wardens of this temple... we were the wardens of the Sha of Fear that was buried beneath it.\n\nThe Sha itself may have escaped... but it left traces behind. If you're truly going down into the catacombs, you should eliminate those traces, before they escape and cause greater problems than those we already face.", objectives = "" }
WordHunterWoW_QuestEN[30929] = { title = "Bad Yak", description = "Is this the place where they replace defective yaks?\n\nCan anybody help me out, here?", objectives = "" }
WordHunterWoW_QuestEN[30930] = { title = "Pick a Yak", description = "I can't find a single good yak here. ALL the yaks are bad!\n\nSome are too stinky, some too fight-y, others just scared.\n\nYou look like a lucky {race}. Here, take a lasso. See if you can find a good yak for me.", objectives = "" }
WordHunterWoW_QuestEN[30931] = { title = "My Father's Crossbow", description = "I came here to visit my dad at the temple. As soon as I got here, I saw the most terrifying thing I've ever seen.\n\nIt was a mantid, walking right past me, carrying my father's crossbow.\n\nSomething's happened to my dad! We've got to find out what it is... but first, we'll need his crossbow back. I saw him heading west, behind the temple.", objectives = "" }
WordHunterWoW_QuestEN[30932] = { title = "Father's Footsteps", description = "Yes, the boy's father - Sentinel Ku-Yao - has gone missing. He could be any number of places... we have no shortage of enemies these days.\n\nYou're free to look around, if you wish. You might start by looking for his yak, or by asking Sentinel Yalo what he knows.", objectives = "" }
WordHunterWoW_QuestEN[30933] = { title = "Seeking Father", description = "I've searched everywhere... but I haven't found my father. I KNOW he's alive still. He just needs his crossbow... then he'll be OK.\n\nI've heard that you Shado-Pan guys sometimes fight the mantid on Sra'vess. I don't have any way of getting there. If you ever go over there, can you look for my dad?", objectives = "" }
WordHunterWoW_QuestEN[30935] = { title = "Fisherman's Tale", description = "The villagers of Zouchin know the coast better than anyone in Kun-Lai. If the Zandalari are hiding on one of the islands, they will know.\n\nMishi will take you as far as Emperor's Path. I will go ahead to speak with the village elders.\n\nFollow the path to Whispercloud Rise. Shin Whispercloud will help you reach the village.", objectives = "" }
WordHunterWoW_QuestEN[30942] = { title = "Make A Fighter Out of Me", description = "Shhh! Don't speak so loudly! My father might hear you.\n\n<Shomi gestures to Steelbender Doshu.>\n\nMy father is delusional! He thinks I should be studying my tea pouring while our village is under attack. It's ridiculous! I have just as much courage as any man. I just don't know how to fight... yet.\n\nThat's where you come in. Let me travel with you! I'm a fast learner and I won't get in the way I promise!\n\nPleaseeeeee!\n\nIf we get separated I'll meet you back in the village.", objectives = "" }
WordHunterWoW_QuestEN[30943] = { title = "Handle With Care", description = "I've seen the numbers these invaders have brought with them, this will not be an easy victory. I do know of one thing that may help us gain an advantage.\n\nThere is a plant that grows around the village that can be used to make a rather effective explosive liquid. If you can gather enough I can begin brewing the mixture.\n\nThe plant you are looking for is appropriately named volatile bloom. Handle it with care, {class}.", objectives = "" }
WordHunterWoW_QuestEN[30944] = { title = "It Takes A Village", description = "The villagers have been guarding Zouchin since the first attack. They are exhausted and many are injured.\n\nIf the Zandalari attack again the last thing we need is for the defenders to fall asleep on the job.\n\nRelieve them of their posts so that they might have time to heal and see their families.\n\nYou'll find them stationed around the village.", objectives = "" }
WordHunterWoW_QuestEN[30945] = { title = "What's Yours Is Mine", description = "The elders want us to mount a defense? We're not monks, {class}; we need weapons if we hope to fight!\n\nScavenge some arms from those barbarians for me. I should be able to melt them down and make something more suitable for our villagers to fight with.\n\nBring me as many as you can carry and I'll take care of the rest. ", objectives = "" }
WordHunterWoW_QuestEN[30946] = { title = "Revelations", description = "The prisoner is being kept upstairs, {name}. It will be difficult to get information from him, but even the slightest detail about their location will help.\n\nThe elders have begun questioning him already. With their help we should be able to figure out our next move.\n\nGo speak with him and see if he has any useful information.", objectives = "" }
WordHunterWoW_QuestEN[30952] = { title = "The Unending Siege", description = "The mantid continue to attack us. Their numbers ebb and flow, but they do not stop.\n\nIt is no matter. The yak is stamina embodied. We will not bend to them.  We will defend his home forever.\n\nWill you help us?", objectives = "" }
WordHunterWoW_QuestEN[30953] = { title = "Fallen Sentinels", description = "Our sentinels can fight for days on end, but even they have their limits. Since the mantid swarm began, too many of them have pushed themselves beyond their abilities.\n\nPlease, aid them in whatever way you can. If you are unable to heal them yourself, you may give them some of this. A mouthful of nutritious yak's milk will give them the strength they need.", objectives = "" }
WordHunterWoW_QuestEN[30954] = { title = "A Blade is a Blade", description = "This is no time to hold to tradition. Our masons' calloused hands bleed and tremble. Our blacksmiths cannot forge weapons as quickly as our sentinels can break them.\n\nIt is time to fight smart.\n\nMany of the mantid come bearing weapons, and when they die, they simply leave them on the battlefield. It would be a shame to see them go to waste.", objectives = "" }
WordHunterWoW_QuestEN[30955] = { title = "Paying Tribute", description = "Our patron Niuzao is a mountain on wheels... very difficult to move, even more difficult to stop. My point: once we get him moving, the mantid will have their arms full trying to slow him down.\n\nThe easiest way to get him moving is to put food in front of him. Luckily for us, food in our temple is plentiful... even in wartime.\n\nI will send one of my strongarms with you, to shoulder the load.", objectives = "" }
WordHunterWoW_QuestEN[30956] = { title = "The Siege Swells", description = "Today's mantid swarm is among the worst I've seen. We are lucky to have Niuzao join us in battle.\n\nHelp him, {class}. Return to the courtyard, and join in the defense of our temple.", objectives = "" }
WordHunterWoW_QuestEN[30957] = { title = "The Overwhelming Swarm", description = "I command the sentinels of Niuzao. Every defender out there can hold his own against the mantid swarm.\n\nThe kunchong, however, are something different.\n\nThey are massive, violent, and without a question the biggest threat to my sentinels' lives. Only Niuzao stands a chance against them. Niuzao... and perhaps you.", objectives = "" }
WordHunterWoW_QuestEN[30958] = { title = "In Battle's Shadow", description = "Niuzao's appearance on the battlefield is a blessing... in more ways than one.\n\nWith the distraction that he's caused, our stonemasons have seized the opportunity to build up our crumbling walls. They could use your help.\n\nToss any loose bricks you find up their way. And hurry! Niuzao will not rampage forever.", objectives = "" }
WordHunterWoW_QuestEN[30959] = { title = "The Big Guns", description = "The mantid now surround the Temple with their infernal war wagons. The sooner we are rid of those things, the better. You could destroy them with your own weapons and spells, but this will work much faster.\n\n<Ogo hands you a few small casks of hastily-packed explosives.>\n\nBeware of retaliation from mantid that remain be inside the war wagon when it explodes. In fact, I'd stay as far away from those things as possible.", objectives = "" }
WordHunterWoW_QuestEN[30960] = { title = "Returning from the Pass", description = "I still have some cleanup to do here in the pass - there are some mantid still making it through. You're a valuable person to have at hand though, and I know Taran wouldn't appreciate me keeping you longer for such basic work.\n\nTaran should still be in the main camp with Gao-Ran. Report back in. I'll catch up with you a bit later.", objectives = "" }
WordHunterWoW_QuestEN[30963] = { title = "The Field Armorer", description = "The Shado-Pan fight. As such, their armor often gets cut, scratched, torn, and burned. And it's my job to repair it.\n\nI'm no armorer, but I can repair a broken piece of mail as long as the hole's not too big.\n\nI prefer to use shell fragments from the tortoises that live in the wild fields to the northeast. Get some for me, and I can keep more Shado-Pan armored and alive.", objectives = "" }
WordHunterWoW_QuestEN[30964] = { title = "A Proper Poultice", description = "A dry bandage doesn't do much good, other than maybe keeping bugs out of the wound. In some camps, that's the best you can hope for.\n\nNot in my camp, though.\n\nI prefer to make a paste from whatever soothing herbs I can find, and layer that between bandages. The most soothing herbs I've been able to find in the field are the Mao-Willows from the fields in the northeast. If you run into any, bring them back.", objectives = "" }
WordHunterWoW_QuestEN[30967] = { title = "Free the Dissenters", description = "Not all of my fellow villagers from Inkgill are corrupted. Many heeded my warnings and did not drink of the sha-tainted waters.\n\nThey are in hiding, terrified, and intimidated by the guards.\n\nPlease, tell them there is hope! Go into the village to the north. Speak with them and send them to me.", objectives = "" }
WordHunterWoW_QuestEN[30968] = { title = "The Sha of Hatred", description = "The end of our hunt is upon us. We have gathered the strongest the Shado-Pan have to offer, and with your strength to aid us, we will defeat the Sha of Hatred and choke out its influence on the world.\n\nWhen we enter the tunnel, stay close, and keep hatred clear from your heart. The fight ahead will put all of us to the test.\n\nWhatever happens, it has been an honor traveling beside you, {name}.", objectives = "" }
WordHunterWoW_QuestEN[30969] = { title = "A New Enemy", description = "The power of these Dark Shaman has attracted many allies, {name}. Former members of the Horde that now work towards some dark purpose.\n\nWe need to make an example of them before we have another twilight's hammer on our hands.\n\nKill any cultist you come across and bring me their insignia.", objectives = "" }
WordHunterWoW_QuestEN[30970] = { title = "Enraged By Hatred", description = "These scorpions are infected with sha. It seems to have driven them out of their hole and into our camp, seething with hatred at invaders in their territory.\n\nWe need to clear the scorpions and secure the camp. Kill any you find.", objectives = "" }
WordHunterWoW_QuestEN[30971] = { title = "Taking Stock", description = "I was dispatched back to camp to gather pitch-tipped arrows for our archers at the bridge, and this is what I came to. I trained with most of these pandaren... I wasn't prepared for this.\n\nStill, the archers at the bridge need our help. If you could help gather arrows from the wreckage, then maybe we can salvage something from this horror.", objectives = "" }
WordHunterWoW_QuestEN[30972] = { title = "Joining the Fight", description = "Lao-Chin's archers will need these arrows down at the bridge. Can you bring them?", objectives = "" }
WordHunterWoW_QuestEN[30973] = { title = "Up In Flames", description = "The mantid coming across the bridge have thick carapaces that shrug off most of our attacks. They have a weakness though: fire.\n\nLao-Chen's men brought kegs to the battlefield for exactly this purpose.  Kick the kegs into groups of mantid, and Lao-Chin's archers will light them up.\n\nThey should be easy to finish off from there.", objectives = "" }
WordHunterWoW_QuestEN[30974] = { title = "Raising Spirits", description = "The kegs are full of my worst stock. Good for burning, crap for drinking.\n\nI've broken out some tankards of my best spirits and had them carried out amongst the kegs though - those are for my well-deserving men!  Spirits to raise their spirits after endless, grueling fighting.\n\nWould you be up for spreading the good cheer?", objectives = "" }
WordHunterWoW_QuestEN[30975] = { title = "The Taking of Dusklight Bridge", description = "Let's press these insects back across the bridge and break their spirits!\n\nFollow my lead.", objectives = "" }
WordHunterWoW_QuestEN[30976] = { title = "Joining the Hunt", description = "We are one stronger. Your help is invaluable.\n\nLet's move on westward to Rensai's Watchpost to find the last member for our party.", objectives = "" }
WordHunterWoW_QuestEN[30977] = { title = "Grounded Welcome", description = "All of my men are down at Farwatch Overlook to the southwest, holding off mantid that are trying to fly across the chasm. As long as my marksmen have arrows, they'll ground any mantid that clear the chasm.\n\nIf you're here to help, I could use some more men clearing the mantid out once they're on the ground. Are you willing, {class}?", objectives = "" }
WordHunterWoW_QuestEN[30978] = { title = "Hostile Skies", description = "We're about to get hit hard... \n\nPick up that cannon there and lend a hand, if you would.  There will be no shortage of targets.", objectives = "" }
WordHunterWoW_QuestEN[30979] = { title = "Devastation Below", description = "Let's get down there and finish that big bug off, you and I.", objectives = "" }
WordHunterWoW_QuestEN[30980] = { title = "Heroes of the Shado-Pan", description = "You said that Taran Zhu is in Townlong and was asking for me?  Must be something important...", objectives = "" }
WordHunterWoW_QuestEN[30981] = { title = "Taoshi and Korvexxis", description = "Taoshi is setting up an ambush for one of the mantid leaders on the south side of Sik'vess. She is tasked with retrieving his crystal so that we can use it to open the door.\n\nTwo are stronger than one. I want you there to make sure it goes smoothly.", objectives = "" }
WordHunterWoW_QuestEN[30983] = { title = "The Dark Shaman", description = "These dark shaman have been down here for months, raising beasts and performing dark rituals.\n\nI don't know what they aim to achieve with all of this, but it's clear that they are no friend of the Horde. That's where you come in, {name}.\n\nFight your way through the chasm and kill Dark Shaman Koranthal and Lava Guard Gordoth.", objectives = "" }
WordHunterWoW_QuestEN[30984] = { title = "No Orc Left Behind", description = "This was supposed to be a routine sweep, {name}. Clean up a few troggs, make sure there is no threat to the city and then be in the tavern by midday.\n\nInstead I've a group of scouts missing, flame hounds pouring out of the chasm and Xorenth going on about \"the next twilight's hammer.\"\n\n<Commander Bagran spits>\n\nGo in there and get my scouts back so we can figure out what is going on down here.", objectives = "" }
WordHunterWoW_QuestEN[30986] = { title = "Ancient Mogu Crypt", description = "Our scouting party got DESTROYED.  Help!", objectives = "" }
WordHunterWoW_QuestEN[30987] = { title = "Joining the Alliance", description = "We have a duty, {name}.\n\nIt is our responsibility to spread the Tushui philosophy beyond the edges of the Wandering Isle... and there is no better place to start doing that than here: Stormwind City, heart of the Alliance.\n\nLet's find out who their leader is. We need allies.", objectives = "" }
WordHunterWoW_QuestEN[30990] = { title = "Open the Golden Doors", description = "Defeat the mogu crypt guardian to open the golden doors.", objectives = "" }
WordHunterWoW_QuestEN[30991] = { title = "Do a Barrel Roll!", description = "When I trained as a Brewmaster, I didn't expect to use my knowledge like this...\n\nDid you know beer catches fire when lit? Well, with yaungol oil mixed in, it's downright explosive.\n\nI've mixed the oil in with these kegs. Roll them at the yaungol over by the gate, and ignite them when you get close. \n\nIt'll take a few seconds for the keg to blow, but when it does...\n\nWell, let's just say I wouldn't want to be over there.\n\nWhich is why I'll be over here. Mourning the loss of this brew.", objectives = "" }
WordHunterWoW_QuestEN[30992] = { title = "Finish This!", description = "We've heard back from Suna, on the wall. Something's going on...\n\nIt looks like they are preparing for their final push. It's time to finish this, friend.", objectives = "" }
WordHunterWoW_QuestEN[30993] = { title = "Where are My Reinforcements?", description = "This has simply gone too far. I cannot ignore our abandonment any longer.\n\nAfter all that's happened here, and all you've been through in Firebough, we must travel to the monastery.\n\nWhatever they are doing in there can wait! We can take my balloon up the mountain to the Monastery. It's anchored back by the camp, to the northeast.", objectives = "" }
WordHunterWoW_QuestEN[30994] = { title = "Lao-Chin's Gambit", description = "Alright. Thanks to you, we have the wall under control. Good job. \n\nI'll stay up here for a little while and make sure no more yaungol get up onto the wall.\n\nYou, though, should go back down and see what Lao-Chin has cooked up. I hate to say it, but maybe he had a good idea after all...", objectives = "" }
WordHunterWoW_QuestEN[30995] = { title = "No Man Left Behind", description = "I sent recon out over an hour ago and none of them have reported back. And now these damned hounds are pouring out of the chasm.\n\nI don't know what's going on down there, but I'm not going anywhere till I get my men back.\n\nI want you to head in there and find them, {name}, preferably while they are still alive.", objectives = "" }
WordHunterWoW_QuestEN[30996] = { title = "The Dark Shaman", description = "These dark shaman have been down here for months, raising beasts and performing dark rituals.\n\nI don't know what they aim to achieve with all of this, but it's clear that they are no friend of the Alliance. And I need your help stopping them, {name}. \n\nFight your way through the chasm and kill Dark Shaman Koranthal and Lava Guard Gordoth.", objectives = "" }
WordHunterWoW_QuestEN[30998] = { title = "A New Enemy", description = "The horde is using dark magic to control beasts and corrupt their brethren down here, {name}.\n\nI intend to put a stop to it, but first I need to know what it is we're fighting against. That's where you come in.\n\nFight through the caverns and collect the insignia that the cultists carry. With them, I can study what type of magic is at work here.", objectives = "" }
WordHunterWoW_QuestEN[30999] = { title = "Path Less Traveled", description = "The toughest roads often have the most to teach us, {class}. I will no doubt learn a great deal from following the path of Shaohao.\n\nMany years ago Shaohao traveled to the highest peak in Kun-Lai to seek the guidance of the Jade Serpent. I too will travel to Seeker's Point in search of wisdom.\n\nPerhaps you would be interested in a journey such as this? If so speak with Uncle Cloverleaf. He will help you prepare.", objectives = "" }
WordHunterWoW_QuestEN[31000] = { title = "Dread Space", description = "Shado-Pan marksmen keep a constant watch over the Dread Wastes from the top of the Serpent's Spine. They would surely welcome the aid of a skilled {class} such as yourself.\n\nTake a kite and check in with Bowmistress Li.", objectives = "" }
WordHunterWoW_QuestEN[31001] = { title = "Falling Down", description = "It's bad enough trying to hold off the mantid, but now we've got spiders swarming up from the ruins below.\n\nOne of my best marksmen caught a blast of webbing around his leg and got pulled straight down!\n\nWe think he's alive, but I don't have the manpower to send anyone in after him. We're stretched thin up here, {class}.\n\nIf you want to help, use the rope behind me to drop down into the ruins. You're not afraid of heights are you?\n\nHow about spiders?", objectives = "" }
WordHunterWoW_QuestEN[31002] = { title = "Nope", description = "We're holding, but just barely. Anything you can do to stem the tide of dreadspinners coming up the wall would be a big help.\n\nFeel like tearing open spider eggs one at a time by hand?\n\nI didn't think so. Take one of our dragon guns and light it up down there. I wanna hear those puppies pop.", objectives = "" }
WordHunterWoW_QuestEN[31003] = { title = "Psycho Mantid", description = "You aren't going to believe what I saw! Two mantid fighting each other, whipping some serious magic back and forth.\n\nOne of them didn't look like any mantid I've ever seen. Completely different color and dress to him, like some kind of... oracle or something. The other one was a total psycho, splashing sha energy around like it was a keg of Stormstout Special.\n\nLook, I gotta get back to my post, but those two are still fighting in the cave behind me and I have a feeling it's a big deal. Check it out?", objectives = "" }
WordHunterWoW_QuestEN[31004] = { title = "Preserved in Amber", description = "Take... this...\n\n<The dying mantid struggles to outstretch his arm. In his mangled grasp rests a metal fork with two long, thin prongs and an ornately jeweled handle.>\n\nAwaken... the Wind-Reaver...\n\nIt is the only way... to end the swarm.", objectives = "" }
WordHunterWoW_QuestEN[31005] = { title = "Wakening Sickness", description = "You will forgive my current state. I have slept for many years.\n\nA Klaxxi'va should have been here to attend my Wakening with kypari sap... but you will have to do.\n\nI sense the buzzing of sapflies to the south. They gorge on the nourishing sap I need. Bring them to me.", objectives = "" }
WordHunterWoW_QuestEN[31006] = { title = "The Klaxxi Council", description = "I must report to the Klaxxi. They would not have woken me unless the situation were dire.\n\nYou have not been entirely useless. For that, I will spare your life.\n\nThe council may even find a use for you.", objectives = "" }
WordHunterWoW_QuestEN[31007] = { title = "The Dread Clutches", description = "The imperial clutches have become an abomination! Clutch-Keepers rush the development of new swarmborn, saturating them in this vile \"sha\" energy before sending them away to the wall.\n\nThe Klaxxi wish to stem the tide of swarmborn production in these dread clutches. Put the keepers to death!", objectives = "" }
WordHunterWoW_QuestEN[31008] = { title = "Amber Arms", description = "You! Filth!\n\nYou work for me now!\n\nThe amber blades of the Shek'zeer Bladesworn are the finest weapons in the empire.\n\nIf you are not impaled upon them immediately after leaving here, bring me as many of the blades as you can carry! I want to make sure we have weapons in reserve, should we need them.", objectives = "" }
WordHunterWoW_QuestEN[31009] = { title = "Dead Zone", description = "A Klaxxi'va whispers to the tower. It carries their whisper far; to other towers, to mantid, to paragons. The whisper bounces back, and the Klaxxi hear it.\n\nThis way, they see all.\n\nA tower near the palace is quiet. This will not do. It must sing for the Klaxxi.\n\nIt is my job to fix the tower, but if you serve the Klaxxi, you should serve me as well. You fix the tower, and I will wait here!", objectives = "" }
WordHunterWoW_QuestEN[31010] = { title = "In Her Clutch", description = "The crystal sings to the Klaxxi. They sense a paragon in the clutch, east of the tower.\n\nClutch-keepers are trying to pollute this one. The Klaxxi will not permit this.\n\nGo and find the paragon. Place your hands on his chamber, and the Klaxxi will channel their whispers through you to break him free. Protect him if you can.", objectives = "" }
WordHunterWoW_QuestEN[31011] = { title = "Enemies At Our Door", description = "The Zandalari have begun their attack! You must help defend the village!\n\nIf we can't push them back, we will never find the Thunder King's remains!", objectives = "" }
WordHunterWoW_QuestEN[31012] = { title = "Joining the Horde", description = "Here we are, {name}... Orgrimmar, heart of the Horde.\n\nWe can be helpful beyond the edges of the Wandering Isle. There are innumerable problems out there, just waiting for us to solve them. This is what Master Shang Xi would have wanted.\n\nThere's no better place to start doing that than here, with the aid of the Horde. Let's find out who their leader is. We need allies.", objectives = "" }
WordHunterWoW_QuestEN[31013] = { title = "The Horde Way", description = "I recently received word that some of your kind might be coming our way.\n\nI've recently been trying to bolster the strength of the Horde. A few pandaren might do us good.\n\nWalk with me, {name}.", objectives = "" }
WordHunterWoW_QuestEN[31015] = { title = "Your Private Collection", description = "Pandaria is rich with history, legends, stories, and lore of every sort. While you are traveling throughout the world I would ask that you keep an eye open for artifacts and pieces of information that you feel would be pertinent to our work here.\n\nWhen you accumulate enough knowledge, we will compile it in to a volume for your personal collection here.\n\nYou can, of course, return whenever you like to review the volumes we are making for you.", objectives = "" }
WordHunterWoW_QuestEN[31016] = { title = "The Lorewalkers", description = "Dear {name},\n\nWe have uncovered something tremendous in the Vale of Eternal Blossoms. A great repository of books, scrolls, and lore that has remained untouched since the days of the mogu empire.\n\nPlease, join us at your earliest convenience. You can find this Seat of Knowledge by traveling to the infamous Mogu'shan Vaults, and then flying to the landing just above the entrance.\n\nI look forward to your arrival!\n\nSincerely,\n\nLorewalker Cho", objectives = "" }
WordHunterWoW_QuestEN[31018] = { title = "Beneath the Heart of Fear", description = "The Klaxxi have detected the existence of another paragon, Wakener.\n\nThis one was kept well-hidden from us, and for good reason.\n\nThe Empress already has possession of this one, and her adjuncts work to destroy it even now.\n\nThey are performing their sorcery in a chamber deep beneath the palace, and they must be stopped.\n\nWe hold Klaxxi'vess. You must go in our stead. Find the entrance to their chamber from the ledge to the west.", objectives = "" }
WordHunterWoW_QuestEN[31019] = { title = "Amber Is Life", description = "In order for our efforts against the mantid empire to continue, we require more amber.\n\nThere is a great deposit of amber underneath the lake to the south, but the area is inhabited by a savage saurok tribe.\n\nI cannot spare anyone else. You must go to the lake and test the tribe's strength. Thin their numbers and eliminate their leader, who is probably hiding in his underground cavern.\n\nSurely this is not too great a task for you?", objectives = "" }
WordHunterWoW_QuestEN[31020] = { title = "Feeding the Beast", description = "I must join the Klaxxi Council and the other paragons immediately, but I am barely strong enough to stand.\n\nI must feed, Wakener.\n\nI sense the beating hearts of creatures on the northern bank of the lake.\n\nKill them for me, and I shall do the rest.", objectives = "" }
WordHunterWoW_QuestEN[31021] = { title = "Living Amber", description = "Liquid amber is most efficient for restoring a newly awakened paragon's strength, and is usually provided at a wakening ceremony.\n\nUnfortunately, it seems you did not receive these instructions, so we shall have to improvise.\n\nI can sense a vast quantity of fossilized amber in the lake below us. It will serve, but I am too weak to dig it up myself.\n\nDo this for me, and I will see to it that you are rewarded.", objectives = "" }
WordHunterWoW_QuestEN[31022] = { title = "Kypari Zar", description = "What is that tree on the hill to the west? Can it be... Kypari Zar?\n\n<Korven the Prime lapses into silence.>\n\nWhen I returned from my final ravage, before being elevated to a paragon, I was given the honor of planting that very tree.\n\nI see it has grown into a great kypari, but... it seems something is amiss.\n\nThere is an old sonar tower at the base of the tree. Take me there, Wakener. I can use the tower to take a closer look.", objectives = "" }
WordHunterWoW_QuestEN[31023] = { title = "Relics of the Swarm", description = "This strange-looking carving is covered in a complex written language that might be mantid in origin.\n\nYou notice more relics strewn carelessly among the camps and inside the lake.\n\nPerhaps the Klaxxi would be interested in examining these artifacts.\n\nWho knows? Perhaps it will earn you some favor.", objectives = "" }
WordHunterWoW_QuestEN[31024] = { title = "Kunchong Treats", description = "As Kovok grows, he will require equal parts discipline and reward.\n\nI lack no shortage of discipline, but our supply of meat is almost empty.\n\nTo the south, you will find turtles roaming north of the Lake of Stars and Kypari Zar.\n\nHunt them. Kovok likes the taste of their flesh.", objectives = "" }
WordHunterWoW_QuestEN[31026] = { title = "The Root of the Problem", description = "Kypari Zar is dying.\n\nA creature of terrible darkness corrupts it from deep beneath its roots.\n\nThe tree cannot be saved, but at least we can lessen its pain.\n\nLook. The vile creature has carved a path to its own lair. We need only follow it down the hill, just behind this tower.", objectives = "" }
WordHunterWoW_QuestEN[31027] = { title = "Defeat the Abomination", description = "Now that the pool of life is cleansed, the way to the crypt's interior is open.  Make your way down there and defeat the abomination.", objectives = "" }
WordHunterWoW_QuestEN[31030] = { title = "Into the Monastery", description = "This... is unspeakable. If the monastery has truly been taken over by the Sha, we will need a great effort to purge the monks inside of corruption.\n\nGather a group of your allies, and meet me inside the Monastery.", objectives = "" }
WordHunterWoW_QuestEN[31031] = { title = "Into the Monastery", description = "This... is unspeakable. If the monastery has truly been taken over by the Sha, we will need a great effort to purge the monks inside of corruption.\n\nGather a group of your allies, and meet me inside the Monastery.", objectives = "" }
WordHunterWoW_QuestEN[31032] = { title = "Choking the Skies", description = "Nurong wants me to pass out torches for burning the bodies.\n\nThe flying mantid are fragile, and won't last long in the hot smoke.", objectives = "" }
WordHunterWoW_QuestEN[31033] = { title = "Adventurers Wanted: Ragefire Chasm", description = "The Warchief has requested that any able-bodied adventurer head to Ragefire Chasm, just beneath the great city of Orgrimmar, immediately!\n\nThe Dark Shaman are poised to launch an attack at any moment and the city guards cannot hold for much longer! If you so choose, head to Ragefire Chasm and speak with Commander Bagran, head of the defense initiative, to end the threat to Orgrimmar once and for all.", objectives = "" }
WordHunterWoW_QuestEN[31034] = { title = "Enemies Below", description = "There are enemies of the Horde beneath this very city, {class}.\n\nThe Searing Blade plots to take Orgrimmar for their own, and have already taken Ragefire Chasm! We need to storm their forces and retake what is ours!\n\nGo speak with Commander Bagran just inside Ragefire Chasm. He will have further orders for you.", objectives = "" }
WordHunterWoW_QuestEN[31036] = { title = "Enemies Below", description = "Orgrimmar's Ragefire Chasm has been taken by the Dark Shaman. {name}, we cannot allow this to pass unpunished, lest they next set their sights on Thunder Bluff.\n\nGo speak with Commander Bagran just inside the Chasm. Help him in any way you can, for our fates are intertwined.", objectives = "" }
WordHunterWoW_QuestEN[31037] = { title = "Enemies Below", description = "Orgrimmar's Ragefire Chasm has been taken by the Dark Shaman. {name}, we cannot allow this to pass unpunished, lest they next set their sights on Undercity.\n\nGo speak with Commander Bagran just inside the Chasm. Help him in any way you can, for our fates are intertwined.", objectives = "" }
WordHunterWoW_QuestEN[31038] = { title = "The Challenger's Ring: Snow Blossom", description = "News of your feats has been traveling around the camp, {name}.\n\nIn fact, Snow Blossom would like to test your skill in battle.\n\nYou had best prepare yourself, {class}. She is not easily defeated.\n\nIf you can prove your worth to her, you will win a valuable friend.", objectives = "" }
WordHunterWoW_QuestEN[31039] = { title = "The Mogu Menace", description = "Our scouts have discovered a heavy mogu force at Shan'ze Dao to the northwest.\n\nThe island was supposedly uninhabited, so their presence is disturbing news.\n\nEven more disturbing is the fact that they are performing sinister experiments on the island.\n\nI need a capable {class} to check out the situation.\n\nThe Shan'ze are likely to give you trouble, and if they do, kill them.", objectives = "" }
WordHunterWoW_QuestEN[31040] = { title = "Spiteful Sprites", description = "The Darkwoods sprites on Shan'ze Dao have fallen to the mogu's domination.\n\nThe once sly tricksters are now the full servants of the Shan'ze. They grow bolder each day, stealing and killing to satisfy their masters.\n\nThey must be eliminated, but be careful. They may look harmless, but they are actually quite vicious.", objectives = "" }
WordHunterWoW_QuestEN[31041] = { title = "Egg Rescue!", description = "Eggs. Yes, you heard me right. I said eggs, and these aren't for eating.\n\nHave you ever seen a cloud serpent egg?\n\nThese rare eggs look like jewels, and were once worth their weight in solid gold.\n\nShan'ze Dao to the north normally teems with wild cloud serpents, but the mogu and the sprites have their eggs on lock-down.\n\nWe need to save as many of these precious eggs as we can.\n\nI'm counting on YOU, {name}.", objectives = "" }
WordHunterWoW_QuestEN[31042] = { title = "Onyx Hearts", description = "The Shan'ze Serpentbinders dominate the minds of wild cloud serpents, but they also create their own dark creatures from stone, metal, blood, and ancient sorcery.\n\nTheir creations, the Onyx Stormclaws, guard the island to the northwest.\n\nI wish to study the magic binding these creatures. Bring me their hearts, so that I can better understand what sorcery we are up against.", objectives = "" }
WordHunterWoW_QuestEN[31043] = { title = "Dark Arts", description = "It is said that Shan'ze Dao was once home to a great mogu temple.\n\nThere, the Shan'ze studied and practiced the art of subjugating the dead or inanimate.\n\nMuch of their knowledge still remains on the island to the northwest, buried among the ruins.\n\nWe need to get our hands on their knowledge - both to keep it out of their hands, and to understand the nature of their experiments.", objectives = "" }
WordHunterWoW_QuestEN[31044] = { title = "Bronze Claws", description = "Among the Shan'ze's fiercest and most loyal creations are their quilen.\n\nThese beasts will hunt until they kill their prey, or die in the process.\n\nI need you to not only cull their numbers, but also to retrieve their bronze claws.\n\nTheir claws are strong and razor sharp, and we can use them to make weapons and hooks for our cause.", objectives = "" }
WordHunterWoW_QuestEN[31045] = { title = "Illusions Of The Past", description = "{class}, I need your strength to eliminate the Shan'ze Illusionists on Shan'ze Dao, to the northwest.\n\nIt wearies me to ask of you this difficult task.\n\nThe illusionists are among the strongest of the Shan'ze's elite sorcerors.\n\nThey will not be easy to defeat, but I know no {class} who is better suited to the task.", objectives = "" }
WordHunterWoW_QuestEN[31046] = { title = "Little Hatchlings", description = "I have seen the cruel experiments that the Shan'ze are performing on their island to the northwest.\n\nThe Shan'ze raise baby serpents from the egg. They keep the young in tiny cages, surrounded by squalor and filth.\n\nThe cruelest gaolers starve and torture them.\n\nWe must save as many hatchlings as we can. You have my full permission to punish any mogu that gets in your way!", objectives = "" }
WordHunterWoW_QuestEN[31047] = { title = "Born Free", description = "Do you know the story of the great cloud serpents of Pandaria, {name}?\n\nSomeday you must hear it. Unfortunately, there is no time to tell it now.\n\nWhat you must know is that the wild cloudrunner serpents of Townlong are in trouble.\n\nThe mogu are capturing wild serpents and corrupting their minds, bending them to their sinister will.\n\nGo to Shan'ze Dao, to the northwest. Free the adult serpents from their chains. Save them!", objectives = "" }
WordHunterWoW_QuestEN[31048] = { title = "Grave Consequences", description = "We've found ancient mogu burial urns among the ruins on Shan'ze Dao.\n\nThis is normally no problem, except these urns are home to angry mogu spirits.\n\nNot only do these urns pose a danger to anyone unlucky enough to find one, but they could be used for destruction if they were to fall into the wrong hands.\n\nWe must rid Shan'ze Dao of their presence.", objectives = "" }
WordHunterWoW_QuestEN[31049] = { title = "In Sprite Of Everything", description = "The sprites of Shan'ze Dao have always been capricious tricksters, but now they have fallen under the mogu's influence.\n\nEven as we speak, they gather under a new leader.\n\nWe cannot allow this to happen.\n\nTheir mischievous pranks were one thing, but united, their dark magic is too powerful and too dangerous to comprehend.\n\nTake out their leader before it is too late.", objectives = "" }
WordHunterWoW_QuestEN[31055] = { title = "Between a Saurok and a Hard Place", description = "Dear {name},\n\nWe have received your research on the saurok and believe we have pieced together clues about their past.\n\nIf you visit us at the Seat of Knowledge in Vale of Eternal Blossoms we can add this contribution to your personal collection.\n\nThank you for your diligence!\n\nSincerely,\n\nLorewalker Cho", objectives = "" }
WordHunterWoW_QuestEN[31058] = { title = "The Funky Monkey Brew", description = "Pirates! Our shores have been scoured by the most ill-tempered, ill-mannered, ill-hygienic, and ill-good hozen that ever was found in Pandaria. And to make matters worse, they claim to serve the legendary Captain Ook!\n\nWe see them every night partying and brewing punch on their island Unga Ingoo.\n\n I say we take their brew for a change! I think I can even improve their mix.\n\nGather up some friends and meet me on the southern side of Unga Ingoo. It is time for a Brew Run!", objectives = "" }
WordHunterWoW_QuestEN[31061] = { title = "Riding the Storm", description = "Shan Bu, the leader of the Shan'ze, is performing some kind of dark ritual at the summit of the island to the northwest.\n\nWe believe that the subjugated Shan'ze Cloudrunners are powering the spell. How, we still do not know.\n\nWe believe that the Shan'ze Cloudrunners can still be saved from the corruption that taints them.\n\nTake these bronze claws. Use them to mount the back of a Shan'ze Cloudrunner.\n\nAttack them. Beat some sense back into their heads!", objectives = "" }
WordHunterWoW_QuestEN[31062] = { title = "When The Dead Speak", description = "The Shan'ze's experiments are overseen by a powerful necromancer known as a Shan'ze Deathspeaker.\n\nIf we are to put an end to their operations, we must eliminate their leader.", objectives = "" }
WordHunterWoW_QuestEN[31063] = { title = "Lao-Chin and Serevex", description = "Lao-Chin is facing off against the leader just above the entrance in the tree, on the north side of Sik'vess. He is to bring back the second crystal that we need to get into the mantid tunnel.\n\nGo there and lend him your aid.", objectives = "" }
WordHunterWoW_QuestEN[31064] = { title = "Nurong and Rothek", description = "Hawkmaster Nurong has gone ahead to the northwest of Sik'vess to make sure the last mantid leader cannot escape.\n\nCatch up with him and help him kill the mantid leader. Nurong will bring back the final crystal once you've aided him in this.", objectives = "" }
WordHunterWoW_QuestEN[31065] = { title = "Buried Beneath", description = "Taoshi set up a spyglass on the ridge edge to show me what her scouting uncovered.\n\nGo over and take a look.", objectives = "" }
WordHunterWoW_QuestEN[31066] = { title = "A Cry From Darkness", description = "So, you survived the imperial clutches. You are... resilient.\n\nThe Klaxxi hear another paragon to the north, among the sha-scorched roots of Kypari Vor.\n\nThis one cries out in terror and agony. It cannot be saved.\n\nThe Klaxxi want him put down. Go and defeat him or do not return here.", objectives = "" }
WordHunterWoW_QuestEN[31067] = { title = "The Heavens Hum With War", description = "The mantid don't ever make my job easy, but now they've gone too far.\n\nWe can fend off the occasional attack from Kor'vess, but now... now they're starting to surround us. What's worse, they're draining the amber from our tree.\n\nThis will not stand! We need that amber! To make beer!\n\nThey've dug a burrow into the south side of the tree. I'm short-handed here. Could you take care of them for me?", objectives = "" }
WordHunterWoW_QuestEN[31068] = { title = "Sacred Recipe", description = "\"When the horror comes a-rising\nAnd the heavens hum with war\nOur great vessel of salvation\nMust be broken from its core.\"\n\nThe scroll continues on for several stanzas. Perhaps somebody at The Sunset Brewgarden will be able to decipher its cryptic message.", objectives = "" }
WordHunterWoW_QuestEN[31069] = { title = "Bound With Shade", description = "About that scroll you found...\n\nI keep looking at that line in the second stanza - \"bound with wood and shade\". The \"shade\", in particular, intrigues me.\n\nI must admit, I've often considered taking some of the area's residual sha essence and incorporating it into a brew. I suspect that this is the shade which our recipe calls for.\n\nYou will find large amalgamations of sha to the southeast of our tree... though you may also be able to harvest some from the local wildlife.", objectives = "" }
WordHunterWoW_QuestEN[31070] = { title = "Daggers of the Great Ones", description = "That recipe said: \"rending daggers of the great ones\"...\n\n<Olon ponders this line.>\n\nMushan! That's it!\n\nThere's plenty of mushan roaming out there with these great, big teeth... they're as long as daggers. That's gotta be what the recipe calls for.", objectives = "" }
WordHunterWoW_QuestEN[31071] = { title = "I Bring Us Great Shame", description = "I have failed my fellow brewers.\n\nI took some supplies out to the clearing, east of our tree... and I left them there. Now, with the sha corrupting the land, and the mantid on the prowl, it is too dangerous for me to bring them back.\n\nIf you would help me look for them, perhaps I could regain some of my lost honor.", objectives = "" }
WordHunterWoW_QuestEN[31072] = { title = "Rending Daggers", description = "Forget about them, and forget their BREW. We've got real work to do.\n\nThe scroll mentions \"rending daggers of the great ones\". I've got a feeling I know where to find them.\n\nA pair of mantid lieutenants patrol the Horrid March, to the south. Each one carries a ceremonial dagger.\n\nBring those daggers back here, {name}. We may be on the brink of something big.", objectives = "" }
WordHunterWoW_QuestEN[31073] = { title = "Bound With Wood", description = "<Vu eyes the recipe.>\n\nHmm... \"bound with wood\". We don't typically brew with wood. Sap, yes... but not wood.\n\nWe have, on rare occasions, infused our drinks with corewood from the treants to the west of here. Most of them have fallen to the mantid... but their remains should suffice for our recipe.", objectives = "" }
WordHunterWoW_QuestEN[31074] = { title = "Wood and Shade", description = "\"Rending daggers of the great ones shall be bound with WOOD and SHADE.\"  Hmm.\n\nI've learned a lot about the Kor'thik mantid in my time here. I know that they maintain shrines within their settlement, Kor'vess.\n\nOne is a heartroot of the very tree that they inhabit. The other is a dark pillar, connecting them with their queen.\n\nThese shrines are the wood and shade. If my predictions are right... the daggers should react in their presence.", objectives = "" }
WordHunterWoW_QuestEN[31075] = { title = "Sunset Kings", description = "Olon had a clever idea. He thinks that we should visit the sprites to the west, and ask them if they have any of these ingredients. Some of the elements to this recipe are seeming... strange.\n\nThe Rikkitun sprites have a village to the west of Kor'vess. I hope to see you there, {name}.", objectives = "" }
WordHunterWoW_QuestEN[31076] = { title = "Fate of the Stormstouts", description = "Greetings, {race}. I am Chen Stormstout.\n\nI'm looking for my family. I am told that several Stormstouts came across the wall to help face the mantid threat. I mean to find them, and join them.\n\nHave you seen anyone named Stormstout come through here? Would you mind helping me ask around?", objectives = "" }
WordHunterWoW_QuestEN[31077] = { title = "Evie Stormstout", description = "I was too late. She was so small... and I was too late.\n\nShe should be given a proper burial. A little warrior like her deserves better than this.", objectives = "" }
WordHunterWoW_QuestEN[31078] = { title = "Han Stormstout", description = "There will be time for mourning later. For now, there are other Stormstouts to be found.\n\nThey say that Han Stormstout was last seen exploring Kor'vess. I suspect he headed into that mantid burrow, just across the way.\n\nYou should meet me down there, {name}. I don't doubt that I can handle a few mantid by myself... but I'd feel better with you by my side.", objectives = "" }
WordHunterWoW_QuestEN[31079] = { title = "The Horror Comes A-Rising", description = "We are protected from the mantid. Such was the agreement made so many millennia ago.\n\nThere are forces from which we are not safe, however. The kyparites beneath the ground to the west will haunt us, chase us... even eat us. The mistlurkers eat our kind by the handful.\n\nHelp our people, outsider. Defeat our enemies.", objectives = "" }
WordHunterWoW_QuestEN[31080] = { title = "Fiery Wings", description = "I think that old paper said something about \"fiery wings.\" Those little dragons around here have wings. They're kind of fiery, in a way.\n\nYou're quicker than me. Try catching some of those dragons... or at least slapping the powder off of them.\n\nNo point in killing a harmless little dragon, if all you want is the sparkle from their wings.", objectives = "" }
WordHunterWoW_QuestEN[31081] = { title = "Incantations Fae and Primal", description = "I suspect we are going to need the help of these sprites.\n\nWe have two enchanted daggers, bound together with wood and shade. Now we need someone to perform ancient \"incantations\" on our artifact.\n\nBefore we ask for favors, let's show the sprites that we mean well. I heard their leader talking about a pair of mistlurkers that kidnapped several of their villagers. If we slay these fog beasts... we may get the \"incantation\" we need in return.", objectives = "" }
WordHunterWoW_QuestEN[31082] = { title = "Great Vessel of Salvation", description = "I know what you and the girl-panda seek. We can perform the rite for you... in time.\n\nFirst, I require aid. The seeds fall from our great mother-tree. It is our responsibility to collect them, even in dangerous times like these.\n\nEscort my chanters to the motherseeds, that they may bring them back to the collection pit.", objectives = "" }
WordHunterWoW_QuestEN[31083] = { title = "Promises of Gold", description = "As soon as the creature died, a strange group of sprites appeared and took its pearl away.\n\nThe sprites have a village nearby, called Rikkitun Village. Perhaps you should investigate.", objectives = "" }
WordHunterWoW_QuestEN[31084] = { title = "Bind the Glamour", description = "It has been a very, very long time since our tribe has been called on to perform this rite. I will do the best I can.", objectives = "" }
WordHunterWoW_QuestEN[31085] = { title = "Fires and Fears of Old", description = "We've found the blades, bound them together with wood and shade, and blessed them with an ancient incantation. If I'm not mistaken, it's time to use this thing.\n\nThe sprites spoke of an ancient piece of sap within the Amber Hibernal, a mantid cave near their empress' palace. That must be the \"Blood of Ancients\" that the prophecy spoke of.\n\nWhatever's inside that sap must be important. Good luck, {name}.", objectives = "" }
WordHunterWoW_QuestEN[31086] = { title = "Blood of Ancients", description = "Lya and I agree on one thing: \"Blood of Ancients\" is almost certainly the sap from the great trees of the area. I should know - I brew with the stuff all the time.\n\nThe most ancient tree of all is the one that Grand Empress Shek'zeer calls her home, now known as the Heart of Fear. Find some amber from that tree, and our brew should be complete.", objectives = "" }
WordHunterWoW_QuestEN[31087] = { title = "Extending Our Coverage", description = "The Klaxxi'va hear another paragon. His cries are weak and lost in darkness. The signal must be strengthened.\n\nThere is a tower in Amberglow Hollow that has been silent for many years. It must sing; the Klaxxi demand it!\n\nThis time I will go with you. You will help me repair it.\n\nTake the resonating crystal and meet me in Amberglow.", objectives = "" }
WordHunterWoW_QuestEN[31088] = { title = "Crime and Punishment", description = "The Stinging Trail nurtures young Kypari trees. The empress drains the saplings too early, outsider. They must grow before the amber can be taken.\n\nThe Klaxxi'va demand punishment for this crime! It will please them if you rain death on the Ik'thik harvesters.", objectives = "" }
WordHunterWoW_QuestEN[31089] = { title = "By the Sea, Nevermore", description = "The Klaxxi'va have spoken to me, outsider. The paragon is hidden in the Briny Muck only, he is not so hidden anymore.\n\nThe lizard men surround him. He cannot fall into their scaly hands.\n\nYou will find him; you will awaken him. Do not return without him!\n\nIf you do this the Klaxxi will be pleased with us.", objectives = "" }
WordHunterWoW_QuestEN[31090] = { title = "Better With Age", description = "It is a crime to harvest the young trees, but a much bigger crime to waste the amber.\n\nYoung amber is not as strong, but the Klaxxi need it to continue the fight. We will bring them more and they will sing my praises!\n\nGather the young amber. We will store it until it is aged and can be consumed.", objectives = "" }
WordHunterWoW_QuestEN[31091] = { title = "Reunited", description = "You look at me and see I am no great warrior. Why was I chosen to be a Paragon? Not all weapons can be seen, Wakener. One should not judge by appearance alone.\n\nBefore I explain further, I need to know that you are trustworthy.\n\nSomething precious to me was hidden at the time of my preservation. I am nothing without it.\n\nDefend me as I unearth my greatest weapon, and you will have my trust.", objectives = "" }
WordHunterWoW_QuestEN[31092] = { title = "Feed or Be Eaten", description = "After years of working with the Kunchong I developed a theory; raising one from infancy would strengthen the bond and therefore strengthen the sonic connection.\n\nI had just begun training Kovok when I was chosen for encasement. He is still very young and will need diligent training to reach his full potential.\n\nI'm entrusting Kovok to you, but be warned; if any harm comes to him your life is forfeit.\n\nFirst, you must feed him to gain his trust. The turtles in the area should be suitable for this.", objectives = "" }
WordHunterWoW_QuestEN[31093] = { title = "Hozen in the Mist", description = "Dear {name},\n\nYour research into the hozen has proven quite enlightening.\n\nIf you visit us at the Seat of Knowledge in Vale of Eternal Blossoms we can add this contribution to your personal collection.\n\nThank you for your diligence!\n\nSincerely,\n\nLorewalker Cho", objectives = "" }
WordHunterWoW_QuestEN[31094] = { title = "Fish Tales", description = "Dear {name},\n\nI have thoroughly enjoyed reading your research in to the jinyu. A fascinating people and quite clever too.\n\nIf you visit us at the Seat of Knowledge in Vale of Eternal Blossoms we can add this contribution to your personal collection.\n\nThank you for your diligence!\n\nSincerely,\n\nLorewalker Cho", objectives = "" }
WordHunterWoW_QuestEN[31095] = { title = "The Dark Heart of the Mogu", description = "Dear {name},\n\nWe have always known the mogu to be dark and sinister. Your research however would imply that they are far worse.\n\nIf you visit us at the Seat of Knowledge in Vale of Eternal Blossoms we can add this contribution to your personal collection.\n\nThank you for your diligence!\n\nSincerely,\n\nLorewalker Cho", objectives = "" }
WordHunterWoW_QuestEN[31096] = { title = "What is Worth Fighting For", description = "Dear {name},\n\nYou have recovered the story of our people's freedom from the mogu empire.\n\nIf you visit us at the Seat of Knowledge in Vale of Eternal Blossoms we can add this contribution to your personal collection.\n\nThank you for your diligence!\n\nSincerely,\n\nLorewalker Cho", objectives = "" }
WordHunterWoW_QuestEN[31097] = { title = "Heart of the Mantid Swarm", description = "Dear {name},\n\nWhile we appreciate your efforts to investigate the lore of Pandaria, the documents you sent us on the mantid managed to rob me of several nights sleep. Terrifying stuff.\n\nIf you visit us at the Seat of Knowledge in Vale of Eternal Blossoms we can add this contribution to your personal collection.\n\nThank you for your diligence!\n\nSincerely,\n\nLorewalker Cho", objectives = "" }
WordHunterWoW_QuestEN[31100] = { title = "The Song of the Yaungol", description = "Dear {name},\n\nYour research in to the yaungol has proven most insightful.\n\nIf you visit us at the Seat of Knowledge in Vale of Eternal Blossoms we can add this contribution to your personal collection.\n\nThank you for your diligence!\n\nSincerely,\n\nLorewalker Cho", objectives = "" }
WordHunterWoW_QuestEN[31102] = { title = "The Seven Burdens of Shaohao", description = "Dear {name},\n\nIt would seem you have discovered the full tale of Shaohao, the last emperor of Pandaria.\n\nIf you visit us at the Seat of Knowledge in Vale of Eternal Blossoms we can add this contribution to your personal collection.\n\nThank you for your diligence!\n\nSincerely,\n\nLorewalker Cho", objectives = "" }
WordHunterWoW_QuestEN[31103] = { title = "The Ballad of Liu Lang", description = "Dear {name},\n\nAt long last thanks to your research we have the full Ballad of Liu Lang.\n\nIf you visit us at the Seat of Knowledge in Vale of Eternal Blossoms we can add this contribution to your personal collection.\n\nThank you for your diligence!\n\nSincerely,\n\nLorewalker Cho", objectives = "" }
WordHunterWoW_QuestEN[31104] = { title = "The Challenger's Ring: Yalia Sagewhisper", description = "The Shado-Pan brothers and sisters continue to whisper of your deeds, {name}.\n\nIn fact, Yalia herself has taken quite an interest in your studies.\n\nShe wishes to challenge you in the training ring.\n\nYou would do well to impress her. If you do, she just may be willing to help you in the future.", objectives = "" }
WordHunterWoW_QuestEN[31105] = { title = "The Mogu Menace", description = "Our scouts have discovered a heavy mogu force at Shan'ze Dao to the northwest.\n\nThe island was supposedly uninhabited, so their presence is disturbing news.\n\nEven more disturbing is the fact that they are performing sinister experiments on the island.\n\nI need a capable {class} to check out the situation.\n\nThe Shan'ze are likely to give you trouble, and if they do, kill them.", objectives = "" }
WordHunterWoW_QuestEN[31106] = { title = "The Mogu Menace", description = "Our scouts have discovered a heavy mogu force at Shan'ze Dao to the northwest.\n\nThe island was supposedly uninhabited, so their presence is disturbing news.\n\nEven more disturbing is the fact that they are performing sinister experiments on the island.\n\nI need a capable {class} to check out the situation.\n\nThe Shan'ze are likely to give you trouble, and if they do, kill them.", objectives = "" }
WordHunterWoW_QuestEN[31107] = { title = "Citizens of a New Empire", description = "At Shek'zeer's command, the great kypari tree of Kypari Vor was twisted into a totem of horror.\n\nLike those outside of the palace, the clutch nearby is now used to corrupt our swarmborn.\n\nRecover the eggs of the Vor'thik before they are tainted. We shall raise them here. They will be the citizens of a new empire, free from the sha.", objectives = "" }
WordHunterWoW_QuestEN[31108] = { title = "Concentrated Fear", description = "Amber is power. It brings life.\n\nThis... dread amber you brought me has been twisted. It is concentrated fear.\n\nThe Vor'thik know this well. Their kypari has been completely engulfed by sha, and they use the dread amber to quicken their own swarmborn.\n\nBring me the crystals used by the Vor'thik fear-shapers in their rituals. The Klaxxi will study them and decide on a protocol for disposal.", objectives = "" }
WordHunterWoW_QuestEN[31109] = { title = "Culling the Swarm", description = "The Empress continues to amass her forces. Without intervention, they WILL overrun that wall - even if it means smothering it in the corpses of a million swarmborn.\n\nLet us find a better place for those corpses.\n\nLet me know when you are ready to depart for the clutches - I will gladly drop you in from above.", objectives = "" }
WordHunterWoW_QuestEN[31110] = { title = "Through the Portal", description = "Ah, just the {class} I wanted to see!\n\nWe've finally figured out why the portal is not working. We need more arcane powder!\n\nIt would take us months to get a shipment sent out to us, but luckily, the mogu on this island carry plenty for their own spells.\n\nThey tend to use some older stuff, so we're going to need a lot of it.", objectives = "" }
WordHunterWoW_QuestEN[31111] = { title = "Eradicating the Zan'thik", description = "The warriors of Zan'vess are some of the most feared and respected in the empire, for good reason.\n\nImpalers are unmatched in their mastery of the polearm - no doubt Malik trained among the Zan'thik in his time. Their manipulators command terrifying sonic power with the ease and subtlety of a breath.\n\nBoth will need to be dealt with.", objectives = "" }
WordHunterWoW_QuestEN[31112] = { title = "They're So Thorny!", description = "The crate, once full of desperately needed supplies, has been thoroughly pillaged.\n\nA quick scan of the area shows evidence left behind by the thieves. Icy thorns, just like the ones on the water sprites on the shoreline to the east.\n\nThis is a life or death situation for your band of survivors. Those supplies need to be retrieved from these thieving pests and returned to camp.", objectives = "" }
WordHunterWoW_QuestEN[31113] = { title = "Assault Fire Camp Gai-Cho", description = "The Yaungol are a constant nuisance, but the group at Fire Camp Gai-Cho, to the northeast, conspired with the Osul yaungol in their recent incursion into Kun-Lai.\n\nWe cannot allow such an incursion to go unpunished.\n\nGo, attack Fire Camp Gai-Cho. We need to make sure they remain occupied, so that they cannot rise up and threaten The Ox Gate again.", objectives = "" }
WordHunterWoW_QuestEN[31114] = { title = "Assault Deadtalker's Plateau", description = "We have always left the Deadtalkers alone. For so long, they were just responsible for maintaining the sacred burial grounds of the yaungol tribes.\n\nNow, though, they are practicing dark magic, defiling the corpses of their former clanmates... \n\nI know not where they learned those dark magics, or why they no longer treat their dead with respect, but we do not have time to find out. \n\nWe need to stop them.", objectives = "" }
WordHunterWoW_QuestEN[31116] = { title = "Spirit Dust", description = "The spirits that the Yaungol are entrapping from the remains of their ancestors still have a bit of the essence of life within them. \n\nIf you defeat the spirits in battle, you can collect essence from the spirits as dust, and then return it to the corpses in the area, which will send the spirits, finally, to the next life.\n\nThis is the only way to set right what the Deadtalkers have done. It will also help keep us safe.", objectives = "" }
WordHunterWoW_QuestEN[31117] = { title = "Uruk!", description = "Uruk is the Deadtalker of the Townlong yaungol. Your mission will not be truly complete until you defeat him. Go to it!", objectives = "" }
WordHunterWoW_QuestEN[31118] = { title = "The Deadtalker Cipher", description = "We need to understand what went wrong with the Deadtalkers. \n\nFor so many years, the Deadtalkers were simply responsible for maintaining the burial grounds and holding funerals for fallen warriors.\n\nFrom a recent raid, we've recovered a tablet from the grounds that is clearly written using a cipher, but it isn't one we've encountered before. If you can gather a ciphered scroll from one of the Deadtalkers, we can begin to put together the cypher and understand what's happened.", objectives = "" }
WordHunterWoW_QuestEN[31119] = { title = "The Enemy of My Enemy... Is Still My Enemy!", description = "The mantid are our enemies. As are the yaungol at Fire Camp Gai-Cho.\n\nIt is fortunate, then, that they are also each other's enemies. Mantid from Kri'vess constantly attack the Gai-Cho yaungol, who hold them off at their front gates.\n\nI want you to wreak havoc. \"Borrow\" some highly explosive oil barrels from camp Gai-Cho, and toss them down onto the battlefield from the air.\n\nI don't care which ones you kill, just kill a lot of them.", objectives = "" }
WordHunterWoW_QuestEN[31120] = { title = "Cheng Bo!", description = "Cheng Bo is the Warbringer of Fire Camp Gai-Cho. While you've made a dent in their operations, you now have an opportunity to strike a major blow. \n\nSlay the Warbringer!", objectives = "" }
WordHunterWoW_QuestEN[31121] = { title = "Stay a While, and Listen", description = "Rush rush rush - are your people always in such a hurry?\n\nSit and have some tea with me a moment, and we will discuss your plight.\n\n<Lorewalker Cho's features settle into a patient smile.>", objectives = "" }
WordHunterWoW_QuestEN[31127] = { title = "The Challenger's Ring: Chao the Voice", description = "It looks like you're quite the fighter, {name}.\n\nChao heard about it, and she's been talking about how she'd kick your...\n\nWell, let's just say I think you should challenge her and try to get her respect.", objectives = "" }
WordHunterWoW_QuestEN[31128] = { title = "The Challenger's Ring: Lao-Chin the Iron Belly", description = "Lao-Chin seems to have his head in the clouds... or, rather, in his beer.\n\nAfter all of his recent battles, he seems completely obsessed with with trying to develop the perfect brew for fighting. \n\nThat's well and good, but we need him to actually do some fighting!\n\nYou should go challenge him, see if you can snap him out of his rut. \n\nIf you beat him, he'll probably want to go out and help fight just to try to one-up you!", objectives = "" }
WordHunterWoW_QuestEN[31129] = { title = "Fate of the Stormstouts", description = "{name}! It is so great to see you healthy, and traveling so far. It would seem that our paths are quite tightly intertwined.\n\nI'm here looking for my family. I am told that several Stormstouts came across the wall to help face the mantid threat. I mean to find them, and join them.\n\nHave you seen anyone named Stormstout come through here? Would you mind helping me ask around?", objectives = "" }
WordHunterWoW_QuestEN[31130] = { title = "A Visit with Lorewalker Cho", description = "Stranger, I may be able to help you find your prince. But first, I would like to know a little more about you and your people.\n\nCome, help me with my chores, and we will chat.\n\nYou have the look of a grizzled war veteran, but certainly you have a few minutes to help a bookish Pandaren like myself putter around the house, yes?", objectives = "" }
WordHunterWoW_QuestEN[31131] = { title = "Whitepetal Lake", description = "Reports suggest that things are quiet at Whitepetal Lake today, but I've dispatched Ren Firetongue and He Softfoot to make sure it stays they way.\n\nIf you want to aid the effort further, head to the west to the lake, meet up with He, and help him keep things secure from any hostile threats.", objectives = "" }
WordHunterWoW_QuestEN[31132] = { title = "A Mile in My Shoes", description = "Oh, where have my manners gone? Technically, I suppose I am the host here.\n\nAllow me to tell you a little bit about myself and my people before asking questions of you.", objectives = "" }
WordHunterWoW_QuestEN[31133] = { title = "Kor'thik Aggression", description = "I'm no brewer - just looking at all those heaps of ingredients makes my head spin. Just put the brew in front of me when it's finished, thank you.\n\nNo, I'm here to make sure that the brewers don't get cut in half while they're trying to make that perfect brew. It's not an easy job.\n\nThe Kor'thik mantid across this basin have been attacking us nightly. If you're already heading over there, why don't you return the favor and attack a few of them?", objectives = "" }
WordHunterWoW_QuestEN[31134] = { title = "If These Stones Could Speak", description = "This is a very ancient place, traveler.\n\nOnly recently have I pieced together a method of translating the forgotten language carved into these stones.\n\nOh, the thrill of discovery! This never gets old, I assure you.\n\nHere, you are the guest. You do the honors. I insist.\n\nUse this key to unlock the secrets the stones contain.", objectives = "" }
WordHunterWoW_QuestEN[31135] = { title = "The Future of Gnomeregan", description = "It's a victory for us every time we're able to help another survivor escape from the contaminated halls of Gnomeregan. {class}s like you will play an important part in the future of Gnomeregan. To that end, our leader, High Tinker Mekkatorque, has assembled a team of trainers to help you learn your arts.\n\nXi, Friend of the Small has visited us from a faraway land and will help oversee your training and adjustment to life on the surface. She's waiting for you on the small practice field across the road.", objectives = "" }
WordHunterWoW_QuestEN[31136] = { title = "Behind Our Lines", description = "Scouts bring me reports of a powerful Imperion that slipped through our lines in the south and is now heading for the road in the eastern vale.\n\nI need someone I can trust to stop it. Find it and kill it quickly, {name}.", objectives = "" }
WordHunterWoW_QuestEN[31137] = { title = "Meet the High Tinker", description = "I don't know if you'll remember Mekkatorque or not. Nevin and the other gnomes have mentioned that memory loss is pretty common for you survivors.\n\nAnyways, High Tinker Mekkatorque is the leader of all the gnomes. He has made a habit of meeting with every rescued survivor personally. You should introduce yourself to him. He'll be with his war council beneath the tent in the center of town.", objectives = "" }
WordHunterWoW_QuestEN[31139] = { title = "Beating Them Back!", description = "So you're the new recruit from Stormwind, eh? I'm Marshal McBride, commander of this garrison. Glad to have you on board...\n\n<McBride looks through some papers.>\n\n{name}. It is {name}, right?\n\nYou've arrived just in time. The Blackrock orcs have managed to sneak into Northshire through a break in the mountain. My soldiers are doing the best that they can to push them back, but I fear they will be overwhelmed soon.\n\nHead northwest into the forest and kill the attacking Blackrock worgs! Help my soldiers!", objectives = "" }
WordHunterWoW_QuestEN[31140] = { title = "Lions for Lambs", description = "The invading orcs aren't fools. They are sizing us up, making sure that when they attack it will be to their advantage.\n\nIn the forest, to the northwest, are Blackrock spies. They peer at us through spyglasses, watching our every move - waiting. I want you take the fight to them!\n\nKill the Blackrock spies! We must show them that we know they are watching us and that we are prepared!", objectives = "" }
WordHunterWoW_QuestEN[31143] = { title = "Join the Battle!", description = "I received an urgent message from Sergeant Willem. Turns out that the Blackrock orcs have hired goblin assassins. They ambushed our battalion behind the abbey. Willem has asked me to send him a hero. You have to go help them, {name}!\n\nFind Sergeant Willem north of the abbey at the command tent. Go!", objectives = "" }
WordHunterWoW_QuestEN[31144] = { title = "They Sent Assassins", description = "Have you ever seen a goblin, {name}? They're wretched little monsters that love only two things: gold and themselves.\n\nThe Blackrock orcs have enlisted the aid of goblin assassins to kill our soldiers. If you look to the field in the north you can barely make out their silhouettes, sneaking about in the grass.\n\nI need you to head out there and kill every goblin that you see. They need to learn that nobody messes with the Alliance!", objectives = "" }
WordHunterWoW_QuestEN[31145] = { title = "The Rear is Clear", description = "Excellent work, {name}! The rear is now officially clear. We'll take care of the stragglers. I want you to go back to Marshal McBride, standing in front of Northshire Abbey, south of here, and let him know that the goblin situation is under control.\n\nFarewell, {class}.", objectives = "" }
WordHunterWoW_QuestEN[31152] = { title = "Peering Into the Past", description = "Just a moment, now. Allow me to gather my things.\n\nWouldn't want me to lose these notes now, would we? Especially after you risked life and limb for them!\n\nThere, all set. Let us be off, shall we?\n\nI must say, I feel much safer traveling with you after seeing how you handled that saurok!", objectives = "" }
WordHunterWoW_QuestEN[31158] = { title = "The Basics: Hitting Things", description = "Alright, mon. We start with da basics. I need ta know dat you know how ta swing dat weapon you're totin' around.\n\nGo thrash dose tiki targets. Take it slowly. Natural-like. I'll watch ya fighting form and we'll go from dere.", objectives = "" }
WordHunterWoW_QuestEN[31159] = { title = "The Rise of the Darkspear", description = "Tha Darkspear tribe have long been victims. Outcasts. We found ourselves fleein' our homes time 'n time again... but dis time, it's not fleein' dat drives us here.\n\nVol'jin has offered us leadership through wisdom, and it has kept us alive dis long. Now dat same wisdom offers portents of a chaotic future for tha Horde unda Garrosh Hellscream.\n\nNo, dis time we not fleein'. Dis time, we are fightin' for a home dat will last.\n\nIt's time to begin ya trainin', {name}. Speak with Zabrax to the east.", objectives = "" }
WordHunterWoW_QuestEN[31160] = { title = "A Rough Start", description = "Lets put dose skills ta use. I'll start ya off easy, mon.\n\nThere be cats killing our boars. Dat food ain't for sharin'. Dose boars are gonna need ta be alive if ya be wanting food tonight.\n\nDey're all over the island. Bring me some cat pelts.", objectives = "" }
WordHunterWoW_QuestEN[31161] = { title = "Proving Pit", description = "Ya done quite well for ya'self, {class}. I'm sure I could teach ya a trick or two here and dere, but I not be wastin' ya time on tiki targets no longer.\n\nl put one last trial before ya den, mon. Head over to da provin' pit in the middle of dis area and fight a real baddy - one dat wants ta kill ya back. Just let the jailor by the pit know when ya ready.", objectives = "" }
WordHunterWoW_QuestEN[31163] = { title = "More Than Expected", description = "Ya definitely more den expected, mon. I'm sure dere's more important stuff we can be usin' ya talents on now. Ya don't need ta hang out with da newbloods no more.\n\nHead down to da village to da southeast and make yaself known. Lend a hand here and there and I'm sure ya make yer way up to sometin' more prestigious quick enough.", objectives = "" }
WordHunterWoW_QuestEN[31167] = { title = "Family Tree", description = "So there you have it, traveler, or as much of it as would make for a proper introduction, hmm?\n\nWhat of you, then? Are your people so much different than mine?\n\nSurely, there must be things we share in common. Let us see...", objectives = "" }
WordHunterWoW_QuestEN[31175] = { title = "Skeer the Bloodseeker", description = "Our efforts to secure the shallows before Zan'vess have paid off.\n\nWe have spotted another paragon buried in amber, hidden in the waters to the southwest.\n\nAdding another paragon to our numbers is vital. Another champion from ages past could turn the tide in our favor.\n\nI would go immediately, but unfortunately, I am needed here.\n\nSince you are already a Wakener, you can carry out this task in my stead.", objectives = "" }
WordHunterWoW_QuestEN[31176] = { title = "A Strange Appetite", description = "Food. I must have food.\n\nIn my time, the meat of the starfish brought not only strength, but also clarity of mind. This is what I must eat.\n\nBring this to me from the nearby shallows.\n\nWait much longer, and I will devour you instead.", objectives = "" }
WordHunterWoW_QuestEN[31177] = { title = "Fine Dining", description = "In my living years, I was the greatest warrior of the swarm.\n\nHelp me regain my strength, and I shall show you.\n\nI smell the salt sea nearby, and where you can find the sea, you will find briny clackers.\n\nBring me their tails. I must feast upon their flesh.", objectives = "" }
WordHunterWoW_QuestEN[31178] = { title = "A Bloody Delight", description = "A warrior is not ready for battle until he tastes the blood of his enemies.\n\nI am still too weak to hunt, so you must go in my stead.\n\nOnly the blood from the fiercest predators will do. I can smell their presence in the waters outside this cave!\n\nBring this to me, and then perhaps you shall see why they call me the Bloodseeker.", objectives = "" }
WordHunterWoW_QuestEN[31179] = { title = "The Scent of Blood", description = "I'm afraid that I wet my hands with saurok blood while you were away.\n\nI'm sorry, but I could not help myself. Now, watch them attack me.\n\nPitiful!\n\nDo they think to take vengeance for their fallen? Do they come challenge ME?\n\nI, who have won a hundred wars? I, who stood alone against thousands and still shouted for my enemies to come?\n\nNo, these... saurok... will crumple before me like paper before the flame!\n\nI shall show you my might, Wakener. Fight alongside me and see.\n\nHere they come!", objectives = "" }
WordHunterWoW_QuestEN[31181] = { title = "Fresh Pots", description = "We got a load of empty crab pots out there that need fresh bait.\n\nNow, we COULD pull them one at a time and bait them up here in comfort. A nice chair to sit on, maybe a hot cup of tea to keep you warm. Sounds nice, doesn't it?\n\nNever gonna happen.\n\nHead to Lonesome Cove, immediately southeast, and bait those pots with two chunks of fresh sea monarch. By \"fresh\" I mean killed right there in the water.\n\nOh, and by \"pots\" I mean traps. If you wanna be part of the crew, you'd better learn the lingo.", objectives = "" }
WordHunterWoW_QuestEN[31182] = { title = "You Otter Know", description = "You know what happened to the bait in those pots?\n\nOtters. That's what happened.\n\nThey prefer fresh clams, but they'll pick our crab traps clean if they're hungry enough.\n\nThe otters in Lonesome Cove are protected by law and we run a legitimate operation here. As much as I'd love to chum those little rats and call it a day, we just make sure they aren't hungry enough to raid the crab pots.\n\nToss 'em a few clams to keep them busy while you're out there.", objectives = "" }
WordHunterWoW_QuestEN[31183] = { title = "Meet the Cap'n", description = "Alright, {name}, I got another job for ya.\n\nYou see that lion seal in the pen over there? Name's Dog. He's been Soggy's pet for years.\n\nDog's acting up lately - I think he's getting restless in that pen. Why don't you go talk to Soggy and let him know.\n\nI'd say it's about time you meet the cap'n anyway.", objectives = "" }
WordHunterWoW_QuestEN[31184] = { title = "Old Age and Treachery", description = "Look, I ain't got reason to trust you, but there's a task I can't give to my crew.\n\nI need you to search the wreck of our old ship, the Mist-Hopper, and bring back the charter. It'd be sealed up in a silver tube, in a footlocker.\n\nIt's sort of, uh... incriminating. I can't risk any of the crew finding it if they decide to visit the ol' girl. She's resting on the Shelf of Mazu, to the west.\n\nI'd suggest riding a rip current out there, if you got the stomach. They're all over the shelf.", objectives = "" }
WordHunterWoW_QuestEN[31185] = { title = "Walking Dog", description = "Dog ain't my \"pet.\" He's a member of this crew, and my best friend. Saved my life more than once, you know.\n\nBut I'm gettin' too old to walk him anymore, and he still needs his exercise. Take Dog for a trip around the shelf for me, would ya?\n\nHe loves to swim through the hot geysers just southeast of the shallows.\n\nHe absolutely has to... er... \"leave his mark\" on the dead whale at the far western edge of the shelf.\n\nOh, and he'll want to visit our old shipwreck, too. He likes to reminisce.", objectives = "" }
WordHunterWoW_QuestEN[31186] = { title = "Dog Food", description = "<Dog whines as best as a lion seal can, feebly lifting one flipper toward his massive jaws.\n\nHe's hungry.\n\nThe Shelf of Mazu is covered in rockshell makrura that should make a fine meal for him.>", objectives = "" }
WordHunterWoW_QuestEN[31187] = { title = "On the Crab", description = "I just got word that a string of pots we dropped this morning hit it BIG. We're on the crab!\n\nProblem is, the rips are getting stronger and we lost track of some of the pots. They're just sitting out there, filled with spiky blue GOLD!\n\nI need you back out there. Hook one of these buoys up to any of the full traps you find and send it to the surface for us.", objectives = "" }
WordHunterWoW_QuestEN[31188] = { title = "Shark Week", description = "Crabbing is our big money-maker, but we send all kinds of goods back around the wall. Oils, plants, even rare minerals - the sea's bounty is rich out here!\n\nRight now the big craze in the markets back home is thresher teeth. Apparently they make great necklaces?\n\nThreshers are all over the Shelf of Mazu to the west. Bring me lots of teeth!", objectives = "" }
WordHunterWoW_QuestEN[31189] = { title = "Reeltime Strategy", description = "I never thought I'd see the day, but for the first time since... well, EVER, Master Angler Ju Lien asked for some help with his lines.\n\nApparently the sea is going crazy today and he can't keep up. See if you can give him a hand. He's fishing just south of here.", objectives = "" }
WordHunterWoW_QuestEN[31190] = { title = "The Mariner's Revenge", description = "I'm not gonna sit in a damn rocking chair while my crew gets devoured by a leviathan!\n\nCome on, let's get to the dock and launch a dinghy. I got a special one set up just for this kind of situation. My own little Mist-Hopper Jr.\n\nWe'll give that thing a case of harpoon fever.", objectives = "" }
WordHunterWoW_QuestEN[31194] = { title = "Slitherscale Suppression", description = "The Slitherscale take orders from their leader, the Slitherscale Lizard-Lord. He can be found celebrating his victories on the southeastern corner of Windward Isle.\n\nIf we can destroy this leader, we can deal their tribe a great blow.\n\nWithout their lord, the Slitherscale will think twice before attacking the gentle cloud serpents of the east.", objectives = "" }
WordHunterWoW_QuestEN[31196] = { title = "Sra'vess Wetwork", description = "The mantid outnumber us quite badly. Hundreds of them for each of us.\n\nAnd, they surround us on two sides - at Gao-Ran in the south we're holding them off, but to the west, on the island they call Sra'vess, they continue to mass unabated.\n\nWe're not stupid. We're not going to launch a full scale attack on them. We can't sustain an intense battle on multiple fronts.\n\nInstead, we're going to send you, and one of our Wu Kao, to do some dirty work. Sounds fun, doesn't it?", objectives = "" }
WordHunterWoW_QuestEN[31197] = { title = "The Bigger They Come...", description = "Killing the smaller mantid works mostly as a distraction. It forces them to replenish their numbers before they consider any serious offensive.\n\nThe big ones, though - we kill a few of those, and we really disrupt operations on the island. That buys ourselves a substantial amount of time. With mantid, it's like their size is directly proportional to their importance in the empire.\n\nSo kill some of the big ones for me, while you're out there.", objectives = "" }
WordHunterWoW_QuestEN[31198] = { title = "A Morale Victory", description = "The mantid have statues built on Sra'vess. We don't know exactly what they use them for. They may have some sort of religious significance, or maybe they assist with their sonic communication.\n\nWhen you fight your opponent, you don't just engage them physically, you also engage them mentally. Whatever they use them for, the fact is that those statues are important to them.\n\nWhich is why I want you to blow them up. Losing something important will be a substantial hit to morale.", objectives = "" }
WordHunterWoW_QuestEN[31199] = { title = "Destroy the Siege Weapons!", description = "The mantid don't just attack in swarms. \n\nThey're smart. They use alchemy, bombs... and what's worst, they've got siege weapons. Those have the potential to be incredibly destructive if they attack with them.\n\nWe've got reports that they're building up a force of siege weapons to the west at Sra'vess. Go and destroy them.", objectives = "" }
WordHunterWoW_QuestEN[31200] = { title = "Fumigation", description = "Our alchemists have cooked up a set of gas bombs that will discourage mantid from staying anywhere that we set them off. \n\nIf we plant these in the critical structures of Sra'vess, they'll need to evacuate. That should sow some chaos and delay any action from the mantid there for days.\n\nGet to it, {name}.", objectives = "" }
WordHunterWoW_QuestEN[31201] = { title = "Friends, Not Food!", description = "Our scouts have sent a very troubling report. \n\nThree of our trainees have gone missing, and our scouts found them... \n\nThey've been captured by the mantid and sent to their Kunchong pits. \n\nTheir Kunchong FEEDING pits. We're lucky that the Kunchong don't eat that often.\n\nI need you to get in there, give them these escape kites, and get them out!", objectives = "" }
WordHunterWoW_QuestEN[31203] = { title = "Target of Opportunity: Sra'thik Swarmlord", description = "While we're here, we should do one more thing.\n\nThe Sra'thik Swarmlord is responsible for directing the mantid forces from the air. If we leave it alive, it's going to cause trouble for the garrison.\n\nSo we're not going to leave it alive. Let's take it out, {name}.", objectives = "" }
WordHunterWoW_QuestEN[31204] = { title = "Target of Opportunity: Sra'thik Hivelord", description = "Near the ocean, on the eastern side of Sra'vess, there is a cavern that leads to a network of caves.\n\nFrom there, the Sra'thik Hivelord maintains Sra'vess and plots against us. If we manage to take him out, we'll disrupt their operations for days.\n\nLet's go to it.", objectives = "" }
WordHunterWoW_QuestEN[31206] = { title = "The Crucible of Carnage: The Bloodeye Bruiser!", description = "I'll tell you what, buddy, this place is a far cry from the rolling plains of Nagrand or the bloodbowl in Zul'Drak, but hey, I go where the gold's at! So welcome to Twi-Hi, pal.\n\nYou're new to this pit, so let me set you straight. I'm the fight promoter and this feisty troll next to me is Wodin, my bodyguard. You're the entertainment. When you wanna fight, let me know and I'll set up the match.\n\nIf you're ready and got a group of friends with you, we can start! What do you say?", objectives = "" }
WordHunterWoW_QuestEN[31207] = { title = "The Arena of Annihilation", description = "Ah, I can still remember running fights out of a muddy hole in the ground back in Nagrand. We've come a long way, eh, Wodin?\n\nI tell you, there's nothing more these Tiger monks like than a good scrap. So much so that they've paid good coin for me to set up shop here and help draw the strongest fighters from all around!\n\nSo how about it? You and a couple friends up for a few rounds in the Arena of Annihilation...? Big money, big prizes!", objectives = "" }
WordHunterWoW_QuestEN[31208] = { title = "Venomous Intent", description = "If we are to strike against the Empress, we must arm ourselves with weapons. My own choice of weapon is of a particularly toxic design.\n\nThe scorpions wandering the ledge produce a deadly venom that they store in their tails.\n\nBring me their stingers, and I will show you how I earned the title of paragon.", objectives = "" }
WordHunterWoW_QuestEN[31209] = { title = "Dark Wings, Dark Things", description = "I require another ingredient to create my first poison, Wakener.\n\nThis ingredient you can easily find on the scarabs nearby.\n\nKill them and bring me their wings.", objectives = "" }
WordHunterWoW_QuestEN[31210] = { title = "A Shade of Dread", description = "The last ingredient is perhaps the deadliest.\n\nThe dreadshade flower grows all along these hills.\n\nIt is by eating these poisonous plants that the local wildlife has become so venomous.\n\nA single drop of dreadshade nectar can stop a kunchong's heart.\n\nGo and bring me some of these flowers. Do not be tempted to taste them.", objectives = "" }
WordHunterWoW_QuestEN[31211] = { title = "The Poisoned Mind", description = "Before we return to Klaxxi'vess, I wish to look upon the empire.\n\nThe Klaxxi Council told me that the enemy gathers outside the Empress's palace.\n\nMy poisons are ready. What better way to announce my return than with death and destruction?\n\nJust be careful not to mix the two serums... at least not while you're holding the vessels.\n\nSpeak to me when you are ready to fly.", objectives = "" }
WordHunterWoW_QuestEN[31216] = { title = "Dark Skies", description = "The swarm begins, Wakener! The mantid amass at the Heart of Fear.\n\nAlready they fill the skies with their wings and rend the earth with their claws. They shall not stop the dark march until their bodies are laid open and bleeding upon the ground.\n\nThis we shall gladly do. We will attack them from above. While I fly, use my poisons to destroy their advance.\n\nDo not mix the two serums until you are ready to attack. The reaction can be quite... violent.\n\nSpeak to me when you are ready to go.", objectives = "" }
WordHunterWoW_QuestEN[31220] = { title = "The Challenger's Ring: Hawkmaster Nurong", description = "You've really been building up respect with the Shado-Pan, {name}.\n\nNurong's interested in trying out his skills against you.\n\nThe good news is, if you win, I'll allow him to go with you on your missions.\n\nThe bad news is, I really don't think you'll win.", objectives = "" }
WordHunterWoW_QuestEN[31221] = { title = "The Challenger's Ring: Tenwu of the Red Smoke", description = "So... you've been challenged by the infamous Tenwu of the Red Smoke.\n\nThat's what he calls himself, at least. He's a good fighter, and a good rogue, but it's a wonder he manages to sneak up on anyone with how loudly he brags about himself.\n\nAnyways, I think you should answer the challenge. Maybe it'll give him a touch of humility. Maybe not. Either way, if you win, he'll probably be willing to go with you on your missions. \n\nAnd I get some entertainment.", objectives = "" }
WordHunterWoW_QuestEN[31228] = { title = "Prophet Khar'zul", description = "Prophet Khar'zul is a powerful caster, but he is also underestimating your abilities.\n\nKhar'zul and his forces must be destroyed to protect this village. His death will send a strong message to the Thunder King that we will not be defeated!\n\nYou'll find him on the Isle of Reckoning.", objectives = "" }
WordHunterWoW_QuestEN[31230] = { title = "Welcome to Dawn's Blossom", description = "Cho's off on another one of his adventures, and this one requires a big order of jade. I'm going to have to call in some favors.\n\nHow 'bout in the meantime you introduce yourself to some of the locals.\n\nKai Wanderbrew is a good guy to know, as is Master Windfur. Oh, and say hi to Peiji Goldendraft up at the inn.\n\nBetween the three of them, you should get the feel for life in Dawn's Blossom.", objectives = "" }
WordHunterWoW_QuestEN[31231] = { title = "Dreadspinner Extermination", description = "Back in Gurthani Terrace where you found me, dreadspinners continue to occupy the attention of Shado-Pan marksmen who could otherwise be thinning out this wretched swarm.\n\nEradicate those spiders and offer some relief to the archers on that wall.", objectives = "" }
WordHunterWoW_QuestEN[31232] = { title = "An Ancient Empire", description = "My brothers speak of an ancient mogu empire that once dwelled in the ruins to the east.\n\nOnce, this tribe knew untold secrets of sorcery and subjugation.\n\nI have a curious mind, Wakener, and I wish to learn of the empires that ruled after my time.\n\nKnowledge of the past will determine our future.\n\nGo search the ruins for their ancient tablets. I will study their secrets and make them our own.", objectives = "" }
WordHunterWoW_QuestEN[31233] = { title = "Sap Tapping", description = "I found a grove of young amber trees to the east, Wakener.\n\nI've placed tapping devices on these trees, but I have been too busy to retrieve the sap.\n\nI need someone to find the extractors. Activate them, then bring me samples of the amber.", objectives = "" }
WordHunterWoW_QuestEN[31234] = { title = "Putting An Eye Out", description = "Ah! Wakener! You must help me! (You will help me, or else I will help myself to you!)\n\nI need more materials for my experiments, yes yes! (Blood and guts, hearts and brains, tongues and eyes, eyes, eyes!)\n\nTo the west, I have seen creatures of mist and fog. They possess such big, round, wonderful globes! Big for seeing, round and unblinking!\n\nGo now, little Wakener. Bring me back a single pristine eye!", objectives = "" }
WordHunterWoW_QuestEN[31235] = { title = "Nope Nope Nope", description = "I recovered this weapon on a recent scouting run near the wall. It would seem ideal for helping your Shado-Pan with their infestation problem in Gurthani Terrace.\n\nThe more they are focused on keeping spiders off the wall, the less time they are killing fear-gripped swarmborn.", objectives = "" }
WordHunterWoW_QuestEN[31237] = { title = "Debugging the Terrace", description = "If this Empress is truly possessed by fear and paranoia, she will have sent scouts to every corner of the land in order to cement her control.\n\nThese scout grubs are likely everywhere, but difficult to spot with the naked eye. Better to track them by the pheromone trails they leave behind.\n\nI've already... gifted you... a reactive toxin that will reveal these trails to you for a brief time after experiencing the thrill of victory.\n\nGo now to the Terrace of Gurthan and root out these spies.", objectives = "" }
WordHunterWoW_QuestEN[31238] = { title = "Brain Food", description = "Kovok is growing at an accelerated rate, but his brain may not be able to keep up. He'll require a special diet to ensure that he does not outgrow the capacity to control his own body.\n\nMushan tongue is rich in the nutrients that promote brain growth in kunchong, but they normally eat the beasts whole and fill up quickly. If we feed Kovok only mushan tongues every couple of days or so, it should balance out his growth.\n\nGreatback mushan graze the hills east of here, near the Gurthani Terrace.", objectives = "" }
WordHunterWoW_QuestEN[31239] = { title = "What's in a Name Name?", description = "So, you wanna be a hozen. Huh, wikket?\n\nHozen defend their lands from enemies, like jinyu.\n\nKah Kah fought many jinyu fights, and won them all.\n\nHozen only give name name to good grookers. Go grook jinyu and maybe they call you {name} {name}.\n\nJinyu creepin' down by the river. Ook 'em in the dooker!", objectives = "" }
WordHunterWoW_QuestEN[31240] = { title = "Guo-Lai Infestation", description = "Anji came by and asked for you. Said she was heading to the northeast ruins.\n\nOh, Anji, such a fiery spirit, that girl! Probably better for your long-term health if you not keep her waiting.", objectives = "" }
WordHunterWoW_QuestEN[31241] = { title = "Wicked Wikkets", description = "{name} good wikket, they say...\n\n{name} help hozen, they say...\n\nNo more grookin' {name}, they say.\n\nThat ok. Look out there. Wicked wikkets fallin' like rain, ripe for the grookin'!\n\nGo, join the fun. But remember, Chief Kah Kah gets all the shinies! That's hozen rule number two.\n\n<Jeek Jeek scratches his head.>\n\nHmm, all hozen rules are number two...", objectives = "" }
WordHunterWoW_QuestEN[31242] = { title = "Mistfall Village", description = "My scouts have spotted no mogu near Mistfall Village today, but I've been hearing of some troubles with local wildlife and spirits in the graveyard. I dispatched Che to assess the situation, but he'll most likely need your help.\n\nFind your way southwest to the village and meet Che there. Do what you can.", objectives = "" }
WordHunterWoW_QuestEN[31243] = { title = "Attack on Mistfall Village", description = "Mogu have been sighted at Mistfall Village to the southwest. I dispatched Rook and Sun immediately, but I need another capable hand there as soon as possible.\n\nDon't delay. The villagers need you.", objectives = "" }
WordHunterWoW_QuestEN[31244] = { title = "Guo-Lai Encampment", description = "Leven came by in quite a huff! Said something about mogu in the ruins.\n\nBest be off to find him I think. Angry Leven is not a fun Leven.", objectives = "" }
WordHunterWoW_QuestEN[31245] = { title = "Mistfall Village", description = "Che stopped by on the way to the village and ask if I'd seen you. I told him no.\n\nYou can go see him if you want. But now you're not obligated to see him! I am so marvelously considerate, am I not?", objectives = "" }
WordHunterWoW_QuestEN[31246] = { title = "Attack on Mistfall Village", description = "I can see smoke from the village. And it's not my fault this time!\n\nBest go and help.", objectives = "" }
WordHunterWoW_QuestEN[31247] = { title = "Setting Sun Garrison", description = "Anji and Kun stopped by on the way to the garrison. Lovely pair, don't you think? So different, yet so devoted to each other... ah, it makes my heart swoon just thinking about it.\n\nThey asked for you by name. Maybe they want to put you through some of the training paces? I certainly hope they don't have something more naughty in mind...", objectives = "" }
WordHunterWoW_QuestEN[31248] = { title = "The Ruins of Guo-Lai", description = "I've instructed Anji and Kun to resume investigation of the Ruins of Guo-Lai. We have no reports of any significant mogu presence there today, but it seems to be one of their central interests here in the Vale, and want it under thorough watch consider their attack on the lake.\n\nThat's why I'm sending you as well.\n\nHead west, past the lake, to the ruins. Anji will instruct you further.", objectives = "" }
WordHunterWoW_QuestEN[31249] = { title = "Mistfall Village", description = "Everything I've heard suggests the village has been unaffected by the Shao-Tien offensive at the lake, but I won't take any risks.\n\nI'm dispatching you and Che Wildwalker to keep watch at the village, and aid the townsfolk while you're there.", objectives = "" }
WordHunterWoW_QuestEN[31250] = { title = "Setting Sun Garrison", description = "We've taken losses from the mogu forces descending the Golden Stair and their flanking attackers at Whitepetal Lake. Our lines are thin.\n\nI'm dispatching Anji and Kun to the Setting Sun Garrison to double our efforts at training new recruits. I'd like you there with them, {name}. Show them what a true {class} is made of.", objectives = "" }
WordHunterWoW_QuestEN[31251] = { title = "Best Meals Anywhere!", description = "Yeah, yeah.\n\nEveryone knows us goblins do tinkering. And explosives. And... well, ya' know, the less reputable stuff.\n\nBut what nobody knows is that I'm really a great chef! It's a hobby of mine.\n\nGather us up some meaty bits from the creatures around here, and I'll cook us up the best meals ANYWHERE!\n\nAnd I promise, I'll only use three or four percent rocket fuel.", objectives = "" }
WordHunterWoW_QuestEN[31252] = { title = "Back to Westwind Rest", description = "Well, far as I figure, we've got quite a lot of rebuildin' to do.\n\nI'm not one for joining any big causes, but my farmhands aren't gonna have much to do 'round here, to be honest. And, since you helped them out, they want to join your \"Alliance.\" So, who am I to stop 'em?\n\nBring 'em with you, back to Farmhand Bo. I'll miss 'em, but they're better off with you.", objectives = "" }
WordHunterWoW_QuestEN[31253] = { title = "Back to Eastwind Rest", description = "Well, far as I figure, we've got quite a lot of rebuildin' to do.\n\nI'm not one for joining any big causes, but my farmhands aren't gonna have much to do 'round here, to be honest. And, since you helped them out, they want to join your \"Horde\". So, who am I to stop 'em?\n\nBring 'em with you, back to Farmhand Ko. I'll miss 'em, but they're better off with you.", objectives = "" }
WordHunterWoW_QuestEN[31254] = { title = "The Road to Kun-Lai", description = "Ah! Greetings friend of Lorewalker Cho. I have a message for you.\n\n<The strange little creature hands you a battered scroll case.>\n\nThe Lorewalker waits for you in Kun-Lai. Very dangerous to travel there, yes, very dangerous.\n\nLook for guides along the road to help you find your way.", objectives = "" }
WordHunterWoW_QuestEN[31255] = { title = "The Road to Kun-Lai", description = "Ah! Greetings friend of Lorewalker Cho. I have a message for you.\n\n<The strange little creature hands you a battered scroll case.>\n\nThe Lorewalker waits for you in Kun-Lai. Very dangerous to travel there, yes, very dangerous.\n\nLook for guides along the road to help you find your way.\n", objectives = "" }
WordHunterWoW_QuestEN[31256] = { title = "Round 'Em Up", description = "Lok'tar, {class}.\n\nWe've made progress, but we're going to need mobility if we want to maintain our foothold here in Kun-Lai.\n\nI don't see many worgs, kodo, or the like around here. What I do see are yaks. Our pandaren allies have said they make good mounts, so they'll have to do.\n\nGo round some up and return them here, so we can get our people riding them!", objectives = "" }
WordHunterWoW_QuestEN[31260] = { title = "Profit Mastery: Chasheen", description = "I am totally on to another great scam!\n\nWhen I was flying overhead I saw a really ancient tigress prowling about.\n\nDo you know how much her blood would go for on the black market? Not to mention if I convince some warlocks it adds extra potency to their summoning spells or something.\n\nIf you bring me back some of her blood I will cut you in on the scam. She was prowling about on the far side of the Dojani River from here.", objectives = "" }
WordHunterWoW_QuestEN[31261] = { title = "Captain Jack's Dead", description = "Gore from Captain Jack's head drips and mysteriously seeps into the ground as you examine your hard-won trophy.\n\nStrange, but no time to investigate that now. There's too much work to be done.\n\nThe chieftain of your newfound friends will doubtlessly be impressed with this proof of your grookin' skills.", objectives = "" }
WordHunterWoW_QuestEN[31262] = { title = "Crane Mastery: Needlebeak", description = "So, now that you've got a vibe for how cranes fight, I've got a doozy for you.\n\nNeedlebeak!\n\nOr at least, that's what I'm calling him. Biggest crane I ever saw. And its beak is so sharp it's like a sword.\n\nNorthwest of here you'll find the big water fall that kicks off the Dojani River. Needlebeak likes to hang out by the waterfall.\n\nYou bring me its beak as a trophy and I will talk you up a good game to Nesingwary.", objectives = "" }
WordHunterWoW_QuestEN[31265] = { title = "Mazu's Breath", description = "Here to help, are ya? Well, first thing's first.\n\n<Arie rummages through her pockets for a moment before producing a small vial of glowing blue fluid.>\n\nHere it is! \"Mazu's Breath.\" Cap'n's own formula.\n\nWhat? You thought I'd send you out to sea without a means of breathin'? I need deckhands, not corpses!\n\nDown the hatch with it, green. This'll give you a fighting chance out there on the shelf.", objectives = "" }
WordHunterWoW_QuestEN[31266] = { title = "Mogu Incursions", description = "We've heard reports of a group of Mogu infiltrating the coast here in Townlong. I have no idea what they are doing. Frankly, I don't care. \n\nYou've proven yourself, so we've decided to give this mission to you.\n\nWhat's going to happen is this - you're going to go, find them, and kill them.\n\nOur scouts reported the first group landed to the north, between here and Deadtalker's Plateau. Go there and wipe them out.", objectives = "" }
WordHunterWoW_QuestEN[31267] = { title = "Mistblade Destruction", description = "Korven has told me of his findings. There is an enormous amber deposit sitting at the bottom of the Lake of Stars.\n\nUnfortunately, a hostile saurok tribe lives at the edge of the lake, and revere the amber as their own.\n\nThey will not allow us to enter their territory easily.\n\nGo south to the lake. Kill the Mistblade saurok, so that we can more easily harvest the nearby amber.", objectives = "" }
WordHunterWoW_QuestEN[31268] = { title = "A Little Brain Work", description = "Far to the south, the swarm breeds weapons of destruction - enormous, nearly unbreakable amber scorpions.\n\nLike all other creatures, they are subject to manipulation, but unlike other creatures, they have not yet submitted to my mind control.\n\nIt appears that further research is necessary before I can dominate them for our own purposes.\n\nI must study their brains, and you must retrieve some specimens for me.\n\nTake this sonic emitter. I have found it to be quite effective against the beasts.", objectives = "" }
WordHunterWoW_QuestEN[31269] = { title = "The Scale-Lord", description = "The saurok at the Lake of Stars take their orders from their Scale-Lord, a vicious, merciless leader who guards his territory fiercely.\n\nIf we can eliminate this leader, then we can gain access to the enormous amber lode beneath the lake.\n\nGo. Their leader gives his orders from his underground dwelling, at the southern edge of the lake.", objectives = "" }
WordHunterWoW_QuestEN[31270] = { title = "The Fight Against Fear", description = "When we discovered the sha influence at Kypari Zar, I had hoped the corruption could still be cleansed.\n\nUnfortunately, the Klaxxi Council has confirmed that the sha of fear's corruption is deep-seated, and continues to spread.\n\nTo the south, I have observed some of the local wildlife consumed by an unnamed terror.\n\nThe sha can warp and twist its victims into unimaginable horrors.\n\nWe must stop the corruption before it becomes worse. Seek out the sha-infected Horrorscale Scorpids. Eliminate them.", objectives = "" }
WordHunterWoW_QuestEN[31271] = { title = "Bad Genes", description = "Far to the south, Wakener, the Empress's genemancers set about their dark experiments. (Dark yes, but not as dark as mine!)\n\nThey dissect and mutate the nearby wildlife, breeding creatures of their own design. (Their design, which will become my design!)\n\nWe must not let them succeed! (No, no! Only I am allowed such power!)\n\nTheir mutations are already being unleashed for war. Go! Destroy them at any cost!", objectives = "" }
WordHunterWoW_QuestEN[31272] = { title = "Infection", description = "The Empress's genemancers play with dangerous toys.\n\nTo the south, they are injecting local wildlife with pheromone-laden parasites, in an attempt to create monstrous mutations for war.\n\nCarelessly, they have allowed their parasitic worms to escape into the local ecosystem.\n\nLeft unchecked, the infection will spread from one animal to another, until we have an outbreak.\n\nI will inject you with a mild toxin. With it, you will be able to identify infected creatures.\n\nKill the carriers at once.", objectives = "" }
WordHunterWoW_QuestEN[31277] = { title = "Surprise Attack!", description = "Those damnable Mogu...\n\nThose scouts were a distraction! While we were hunting their spies, the main force moved on Niuzao Temple. Corrupted serpents, Mogu everywhere... this is a disaster!\n\nThankfully, Ban was able to make it past their lines with the most elite members of our order. If you can slip past, too, meet up with him. We need to put a stop to this!", objectives = "" }
WordHunterWoW_QuestEN[31279] = { title = "Everything I Know About Cooking", description = "I'm so glad you enjoy my food. Are you interested in the recipes?  If so, you should learn them properly, from my teachers in Halfhill Market.  Everything I know about the kitchen, I learned from them.\n\nSay, if you happen to pass through there, would you deliver this note to Sungshin Ironpaw for me? She was my favorite teacher, and I want her to know that I miss her.", objectives = "" }
WordHunterWoW_QuestEN[31281] = { title = "So You Want to Be a Chef...", description = "You wish to be a chef? If you are dedicated, I can unlock your hidden potential, no matter how inexperienced you are.\n\nIf you wish to learn, show me you can at least follow basic instructions. Learn how to slice peaches and show me what you've learned.  I have fresh pandaren peaches which I will sell to you at a token price.", objectives = "" }
WordHunterWoW_QuestEN[31285] = { title = "The Spring Drifter", description = "Nobody really travels up the Ancient Passage on foot. That is just asking for a faceful of saurok if you are not careful.\n\nTell you what, Egg Shell and I were just about to set off upriver to Binan Village. Want a lift?", objectives = "" }
WordHunterWoW_QuestEN[31286] = { title = "Robbing Robbers of Robbers", description = "Ah, a {class}. I could make good use of your skills.\n\nA convoy was struck just up the road by a band of marauding saurok. These marauders made off with some... merchandise... her ladyship, the Madam Goya, had a mind to sell.\n\nOne does not steal from her ladyship.\n\nIf you recover these items I will gladly provide you a finders fee.", objectives = "" }
WordHunterWoW_QuestEN[31287] = { title = "Educating Saurok", description = "The Spring Road is under the protection of her ladyship, the esteemed Madam Goya.\n\nThe saurok of Hatescale Burrow northeast of here require \"education\" in this fact. We have warned them before but sadly they seem to have a very short memory.\n\nTravel northeast to this burrow and find their shaman leader. Eliminate him and you will have the gratitude of her ladyship. As well as an appropriate bounty.", objectives = "" }
WordHunterWoW_QuestEN[31288] = { title = "Research Project: The Mogu Dynasties", description = "Ah, an explorer. Just what I could use. I am on the verge of discovering the dark secrets of the mogu.\n\nNot all of the secrets, mind you. They kept a lot of dark secrets. But I am on the verge of discovering \"a\" secret at least.\n\nIf, in your travels, you come across some fragments of the mogu past, bring them to me and I will happily reimburse you for them.", objectives = "" }
WordHunterWoW_QuestEN[31289] = { title = "Research Project: The Pandaren Empire", description = "Ah, adventurer. You come at a most opportune time. My daughter and I are researching the history of our people and have hit a roadblock in our research.\n\nShould you come across fragments of the pandaren past, please, bring them to us here. We would benefit greatly from the additional information.", objectives = "" }
WordHunterWoW_QuestEN[31291] = { title = "Uncovering the Past", description = "Interested in being a Lorewalker? There is lots of digging and reading and digging and more reading.\n\nI have entire days where I stare at a broken vase trying to figure out how it goes back together.\n\nShould give it a try. Go solve one artifact of Pandaria and we will appreciate you sharing the knowledge of how you did it.", objectives = "" }
WordHunterWoW_QuestEN[31293] = { title = "Mogu Make Poor House Guests", description = "Leven sent Rook here to stop mogu, but there are more than Rook can kill alone.\n\nYou help?  Rook will tell Leven you helped.  Promise.", objectives = "" }
WordHunterWoW_QuestEN[31294] = { title = "The Ruins of Guo-Lai", description = "I have my heartfelt thanks for your continued aid. Anji awaits at the Ruins of Guo-Lai to northwest.\n\nGo with courage in your heart, young {class}.", objectives = "" }
WordHunterWoW_QuestEN[31295] = { title = "Mogu within the Ruins of Guo-Lai", description = "Thank you for your help, {class}.\n\nI would enjoy your company for longer, but Leven is leading an attack on the mogu within the Ruins of Guo-Lai to the northwest, and awaits your capable hands.\n\nMay the celestials protect you, young one.", objectives = "" }
WordHunterWoW_QuestEN[31296] = { title = "The Ruins of Guo-Lai", description = "The villagers seem to be safe and the mogu are losing their foothold. We should be able to handle the rest from here. Thank you for your kind aid, {name}.\n\nAnji lead a group to investigate and clear out the Ruins of Guo-Lai to the northwest this morning. I am certain she would appreciate someone as capable as yourself. You should go to her.", objectives = "" }
WordHunterWoW_QuestEN[31297] = { title = "Setting Sun Garrison", description = "The mogu will not be able to maintain this attack much longer. We should be able to handle it here, thanks to your kind aid.\n\nMight you be willing to find Anji at the Setting Sun Training Camp to the west? She's been tasked with preparing fresh-faced pandaren to aid the cause. You could show them a thing or two as well, I imagine.", objectives = "" }
WordHunterWoW_QuestEN[31302] = { title = "Ready for Greatness", description = "You seem to know your way around the kitchen. Demonstrate to me your skills and make me 5 bowls of rice pudding.", objectives = "" }
WordHunterWoW_QuestEN[31303] = { title = "The Seal is Broken", description = "<Cho looks at you in disbelief.>\n\nI... I thought Sha of this immensity were a myth - we all did. Just a story to keep our children from fighting.\n\nNo time to talk now. Those fissures - they're feeding it... it grows stronger by the moment!\n\nI must research the scrolls from my family archives. You, take this cannon and ride Mishi.\n\nYou must find a way to contain this horror that has been unleashed! ", objectives = "" }
WordHunterWoW_QuestEN[31306] = { title = "Seeker's Folly", description = "I'm sure your pandaren friend has some ideas about what the mogu are after.\n\nHe headed up the mountain a few days ago without a guide, and asked that only you be sent up after him. He was very specific:\n\n\"The {class} must endure the trek alone, with only his thoughts. He will honor each shrine before meeting me at the top.\"\n\nThe path is just northwest of the camp, marked by flags. Please be careful! Seeker's Folly is a dangerous trek even on a lucky day.", objectives = "" }
WordHunterWoW_QuestEN[31308] = { title = "Learning the Ropes", description = "Now that you are a pet trainer, it's time to test your skills!\n\nHead out into the forest and pick a fight with a battle pet.  Make sure to use your Track Pets skill so you can see pets you can fight on the minimap.  Come back to me after you have won and I will continue your training. Good luck!", objectives = "" }
WordHunterWoW_QuestEN[31309] = { title = "On The Mend", description = "Now that you have won a battle, we need to heal up your pets so they can fight another day!  Visit Erma, our local stable master, to heal and revive your pets.", objectives = "" }
WordHunterWoW_QuestEN[31311] = { title = "Way of the Grill", description = "The Pandaren Way of the Grill produces foods that increase your physical strength. Bring some raw tiger steaks to the Master of the Grill, and he will teach you what you can do with them. There are many tigers in the Jade Forest and the Krasarang Wilds, but you can also find them in other places.", objectives = "" }
WordHunterWoW_QuestEN[31312] = { title = "The Old Map", description = "The old, faded leather is falling apart, but still legible.\n\nScrawled on it is some kind of map, and the following lines:\n\n\nDeep in the valley where four winds blow,\nThe maiden laughs behind her golden fan.\nAt the feet of her ancestors' stair,\nShe whispers secrets into the echoing dark.", objectives = "" }
WordHunterWoW_QuestEN[31313] = { title = "Just A Folk Story", description = "What!?! This don't make any sense! <Fish's face falls.>\n\nWhat's this mumber jumber about a maiden and an ancestor and a buncha stairs?\n\nI can't make any reason outta this, can you?\n\nWell, there are lotsa folks 'round here who're much older than you and me, {name}.\n\nCan you go talk to the folks in Halfhill? I betcha they might know somethin'! ", objectives = "" }
WordHunterWoW_QuestEN[31314] = { title = "Old Man Thistle's Treasure", description = "Well high golly! This is turning into a real life treasure hunt!\n\nThere's gotta be some kind of entrance or opening to the north, where the mountains meet Cattail Lake.\n\nI'll meet ya at the entrance! Let's go get that treasure!", objectives = "" }
WordHunterWoW_QuestEN[31315] = { title = "The Heartland Legacy", description = "At the very bottom of the treasure chest, you find a stack of scrolls and a soft leather sack with seeds.\n\nUnrolling the scrolls, you see they contain detailed farming notes, drawings of plants, numbers and calculations, locations of nearby water springs, and countless other snippets.\n\nThere might be someone at the Tillers Union who would like to see this.", objectives = "" }
WordHunterWoW_QuestEN[31316] = { title = "Julia, The Pet Tamer", description = "I can tell you have been honing your pet battle skills, {name}.  I think it's time for you to take on a real challenge.\n\nJulia Stevens can be found at the Maclure Vineyards south of Stormwind.  She is an up and coming wild pet tamer and I think it's time you faced her in battle!", objectives = "" }
WordHunterWoW_QuestEN[31319] = { title = "Emergency Response", description = "Your companions have made themselves at home in our land, and brought with them a dangerous conflict.\n\nThe full extent of their destruction here we cannot yet know. Already it is... unspeakable.\n\nNevertheless, to forsake your friends out of spite would be against our way. Any that yet live are doubtlessly wounded and in desperate need of care.\n\nThese fireworks were to celebrate the statue's completion. Use them near your companions to signal Mishi, and she will bear them off to safety.", objectives = "" }
WordHunterWoW_QuestEN[31320] = { title = "Buy A Fish A Drink?", description = "Heeeey buddy, how'sh it goin'? You wanna buy a jinyu a drink?", objectives = "" }
WordHunterWoW_QuestEN[31321] = { title = "Buy A Fish A Round?", description = "Heeeey it's my friend, the {race}!\n\nI guesh you've seen me hanging 'round, but I should 'splain that I'm not drunk.\n\nI mean, look at me now! Shober as a freshwater fish!\n\nSure I like to drown my sorrowsh in some good brew now and then, but you can't inebriate a jinyu! Might as well try to drown a fish!\n\nNo, the brewsh make me shleepy, and when I shleep, I have vishions of the future.\n\n\n\nThe shtronger the brew, the more potent my dreamsh! If you bring me a drink, I'll owe you one.", objectives = "" }
WordHunterWoW_QuestEN[31322] = { title = "Buy A Fish A Keg?", description = "My dreams grow dim recently, {race}.\n\nI need something powerful to kick myshelf back into gear!\n\nI heard there'sh a delishush drink that folksh are making nowadays.\n\nIt'sh called Jade Witch Brew.\n\nI'd sure like to taste some.", objectives = "" }
WordHunterWoW_QuestEN[31323] = { title = "Buy A Fish A Brewery?", description = "All right, {name}, in order to continue my vishions, I must now have my own brewery.\n\n...\n\nJust kidding! You should have sheen your own face! Hilarioush... hic!\n\nAnyway, I heard of a new drink that is unlike any other, and I would like a tashte.\n\nHave you heard of the Mad Brewer'sh Breakfasht? If you can bring me some of thish shtuff, you will be my friend for life.", objectives = "" }
WordHunterWoW_QuestEN[31324] = { title = "Family Secrets", description = "Our secret recipes! I was gathering them up. But then... hozen?\n\n<Auntie looks very confused.>\n\nHow is Gao to brew anything? He needs those recipes or disaster is sure to strike!", objectives = "" }
WordHunterWoW_QuestEN[31325] = { title = "A Very Nice Necklace", description = "The beautiful necklace is only partly smudged by dirty hozen hands.\n\nThere's only one person in the Valley who would own such a beautiful piece of jewelry.", objectives = "" }
WordHunterWoW_QuestEN[31326] = { title = "Tina's Tasteful Tiara", description = "It's a dazzling diamond tiara. Who in the valley would be wealthy enough to own such a piece of jewelry?\n\nWhoever it is, they might be willing to give a nice reward.", objectives = "" }
WordHunterWoW_QuestEN[31327] = { title = "Trouble Brewing", description = "With the brewery infested by hozen and... and who knows what else, I'm sure that the brewers are in trouble.\n\nWould you mind helping me find out what's going on, my friend?", objectives = "" }
WordHunterWoW_QuestEN[31328] = { title = "An Exquisite Earring", description = "You unhook the earring off the furry creature's ear. It looks like he was having some fun wearing the dangly hoop. TOO much fun.\n\nPerhaps the owner of this dainty bauble would like to see it returned. You don't have to tell her where you found it... or who was wearing it.", objectives = "" }
WordHunterWoW_QuestEN[31329] = { title = "A Beautiful Brooch", description = "It is a very old, antique brooch with very detailed molding and filigree worked into the edges. It looks very valuable.\n\nThere's only one person who keeps losing jewelry to furry hooligans, and she would probably want to see this heirloom returned.", objectives = "" }
WordHunterWoW_QuestEN[31332] = { title = "Lesson 1: Sliced Peaches", description = "I'm excited to start my training. We start with sliced peaches, right?", objectives = "" }
WordHunterWoW_QuestEN[31333] = { title = "Lesson 2: Instant Noodles", description = "Instant noodles aren't that hard to cook, right?", objectives = "" }
WordHunterWoW_QuestEN[31334] = { title = "Lesson 3: Toasted Fish Jerky", description = "Cooking is harder than I thought.  It's so easy to burn things.", objectives = "" }
WordHunterWoW_QuestEN[31335] = { title = "Lesson 4: Dried Needle Mushrooms", description = "I'm not very fond of mushrooms... but I'll do my best to learn.", objectives = "" }
WordHunterWoW_QuestEN[31336] = { title = "Lesson 5: Pounded Rice Cake", description = "I love rice cakes.  I'll do my best to make good ones!", objectives = "" }
WordHunterWoW_QuestEN[31337] = { title = "A Token of Appreciation", description = "Thanks for checking to make sure I'm doing well!  I've been able to help out the Ironpaws today, and they said I could give this to you.", objectives = "" }
WordHunterWoW_QuestEN[31338] = { title = "Lost Sheepie", description = "Chee Chee's prize sheep, Sheepie, is missing!\n\nThat bad sheep is always wandering off the farm.\n\nStupid sheep! I looked everywhere and couldn't find him.\n\nCan you help me, {race}?", objectives = "" }
WordHunterWoW_QuestEN[31339] = { title = "Lost Sheepie... Again", description = "That stupid sheep! He wandered off again!\n\nCan you find him for me again?", objectives = "" }
WordHunterWoW_QuestEN[31340] = { title = "Oh Sheepie...", description = "Sigh... you guessed it... Sheepie is gone... AGAIN.\n\nStupid sheep! Gives me so much trouble!\n\nI hate to ask you again, but I promise this will be the last time.\n\nCan you find him for me?", objectives = "" }
WordHunterWoW_QuestEN[31341] = { title = "A Wolf In Sheep's Clothing", description = "AAAIIIIEEUUGGHHHH!!!! This is the last straw!\n\nThose stupid hozen on the mountain killed my SHEEPIE!\n\nI know exactly who did this, and it is time for REVENGE.\n\nIf you are willing to help me, take this old sheepskin.\n\nUse it to disguise yourself anywhere on the mountain to the north, wait for that little dooker Krungko to come out of hiding, and then break his bones!", objectives = "" }
WordHunterWoW_QuestEN[31342] = { title = "The Path to Respect Lies in Violence", description = "You have proven yourself in battle.\n\nStill, if you would aid us further, I must ask something else of you.\n\nThe Sha of Violence awaits beyond within the Sealed Chambers. Destroy it if you would earn my respect.", objectives = "" }
WordHunterWoW_QuestEN[31354] = { title = "Mazu's Bounty", description = "That was some amazing work you and the captain did out there, {name}! It's an honor to have you on the crew.\n\nOh! And Ju Lien survived! He swam ashore just after you started letting the harpoons fly. He was raving about some kind of gigantic egg or something that washed in with Jiao.\n\nGo check up on him, will you? He's probably hauled it out of the water by now.", objectives = "" }
WordHunterWoW_QuestEN[31355] = { title = "Restoring Jade's Purity", description = "{class}, will you aid us?\n\nThe temple's purity has been jeopardized. Even now the three masters struggle against their doubts.\n\nPlease, I beg you, head in and help Wise Mari, Liu Flameheart, and Lorewalker Stonestep in their fight against the sha.", objectives = "" }
WordHunterWoW_QuestEN[31356] = { title = "Deep Doubts, Deep Wisdom", description = "There is an ancient pandaren saying that states, \"With deep doubts comes deep wisdom.\"\n\nThe Sha of Doubt has infested the Heart of Jade within the temple. It must be destroyed.\n\nI dare say that you are about to become all the wiser, {class}.", objectives = "" }
WordHunterWoW_QuestEN[31357] = { title = "Relics of the Four Kings", description = "The mogu have reawakened and are a threat to all of Pandaria. They are on the cusp of becoming even more dangerous.\n\nThere are four great mogu kings of legend: Zian of the Endless Shadow, Meng the Demented, Qiang the Merciless, and Subetai the Swift. Four artifacts of these kings are secreted away in the Vault of Kings Past, below.\n\nYou must retrieve these relics before the mogu discover them and become unstoppable.", objectives = "" }
WordHunterWoW_QuestEN[31359] = { title = "The Kunchong Whisperer", description = "To really connect with Kovok you need to challenge him mentally and physically. You must respect his strength and intelligence; only then will he allow you to really train him.\n\nThe muckscale tribe may provide an adequate test of his abilities and with you there he shouldn't be in danger.\n\nAdditionally, this will allow us to decrease their numbers in the Briny Muck.", objectives = "" }
WordHunterWoW_QuestEN[31360] = { title = "A New Lesson for the Master", description = "A new king of the mogu has arisen: Xin the Weaponmaster.\n\nHe single-handedly subjugated the mogu clans, and now they and their new leaders vie for his favor.\n\nI've never seen or read of any who are his equal in battle. Do not underestimate Xin, {name}.\n\nOur fate rests in your hands.", objectives = "" }
WordHunterWoW_QuestEN[31362] = { title = "Last Piece of the Puzzle", description = "I must say, {name}, despite their skirmishes with the hozen, I've never seen the jinyu so militant.\n\nThis troubles me. We must discuss it another time, however. I have come to ask for your assistance.\n\nThe fresco, where last we spoke, is nearly unveiled. I am certain that it holds ancient wisdom - knowledge that the emperor would have us remember.\n\nMy meditations alone may not be enough to discern its meaning. Please, take this heirloom to the shrine of my ancestors. I shall require their assistance.\n\n", objectives = "" }
WordHunterWoW_QuestEN[31363] = { title = "Lighting the Way", description = "We need reinforcements! Someone has to fight through and light the signal flame.\n\nIt's all up to you, {class}. No pressure or anything.", objectives = "" }
WordHunterWoW_QuestEN[31364] = { title = "That's a Big Bug!", description = "The mantid have something they call Raigonn. It's a giant bug they're using to bust down the wall's gates!\n\nLet's keep that thing from getting into the vale!", objectives = "" }
WordHunterWoW_QuestEN[31365] = { title = "Somewhere Inside", description = "I sent a dozen of my best men ahead to infiltrate the mantid siege.\n\nNone have returned.\n\nSince you are taking the fight directly to the mantid, you will be in a position to free any who had the misfortune to be captured.\n\nYou will do this?", objectives = "" }
WordHunterWoW_QuestEN[31366] = { title = "Take Down the Wing Leader", description = "The mantid have lain siege to Niuzao Temple.\n\nEven now, Wing Leader Ner'onok and his forces work to cross the final chasm.\n\nYou must stop him before they reconstruct that bridge.", objectives = "" }
WordHunterWoW_QuestEN[31367] = { title = "The Lorewalkers", description = "So you are interested in learning more of the lore of this land?\n\nVery well! You should speak to Lorewalker Cho at the Seat of Knowledge.\n\nHe can be found in the room above the entrance to the Mogu'shan Palace. Speak with Mishi for a ride.", objectives = "" }
WordHunterWoW_QuestEN[31368] = { title = "The Lorewalkers", description = "So you are interested in learning more of the lore of this land?\n\nVery well! You should speak to Lorewalker Cho at the Seat of Knowledge.\n\nHe can be found in the room above the entrance to the Mogu'shan Palace. Speak with Mishi for a ride.", objectives = "" }
WordHunterWoW_QuestEN[31369] = { title = "The Anglers", description = "If you want to explore all the secrets of the deep ocean, and catch some big fish, speak to Haito at the Anglers Wharf in Krasarang Wilds.\n\nI'm sure he'd love to show you a thing or two about reeling!", objectives = "" }
WordHunterWoW_QuestEN[31370] = { title = "The Anglers", description = "If you want to explore all the secrets of the deep ocean, and catch some big fish, speak to Haito at the Anglers Wharf in Krasarang Wilds.\n\nI'm sure he'd love to show you a thing or two about reeling!", objectives = "" }
WordHunterWoW_QuestEN[31372] = { title = "The Tillers", description = "The Tillers do their business at Halfhill in the Valley of the Four Winds.\n\nIf you're interested in getting started, I hear there's a new farmer in town by the name of Farmer Yoon.\n\nI betcha he'll be looking for help.", objectives = "" }
WordHunterWoW_QuestEN[31373] = { title = "The Order of the Cloud Serpent", description = "The Order of the Cloud Serpent is always searching for talented riders.\n\nIf you wish to follow our way, you should speak to Instructor Skythorn at The Arboretum in the Jade Forest.\n\nI wish you luck, {race}.", objectives = "" }
WordHunterWoW_QuestEN[31374] = { title = "The Tillers", description = "The Tillers do their business at Halfhill in the Valley of the Four Winds.\n\nIf you're interested in getting started, I hear there's a new farmer in town by the name of Farmer Yoon.\n\nI betcha he'll be looking for help.", objectives = "" }
WordHunterWoW_QuestEN[31375] = { title = "The Order of the Cloud Serpent", description = "The Order of the Cloud Serpent is always searching for talented riders.\n\nIf you wish to follow our way, you should speak to Instructor Skythorn at The Arboretum in the Jade Forest.\n\nI wish you luck, {race}.", objectives = "" }
WordHunterWoW_QuestEN[31376] = { title = "Attack At The Temple of the Jade Serpent", description = "Darkness enshrouds the Temple of the Jade Serpent, and Yu'Lon's priests beseech us for aid.\n\nThey hold the sha in check, but just barely.\n\nYou may be able to turn the tide, {class}.", objectives = "" }
WordHunterWoW_QuestEN[31377] = { title = "Attack At The Temple of the Jade Serpent", description = "Darkness enshrouds the Temple of the Jade Serpent, and Yu'Lon's priests beseech us for aid.\n\nThey hold the sha in check, but just barely.\n\nYou may be able to turn the tide, {class}.", objectives = "" }
WordHunterWoW_QuestEN[31378] = { title = "Challenge At The Temple of the Red Crane", description = "The Temple of the Red Crane still reels from the aftermath of the sha's presence, and has only recently gathered to rebuild and retrain its warriors.\n\nIf you wish to help at the temple, speak to Thelonius at the Cradle of Chi-Ji.", objectives = "" }
WordHunterWoW_QuestEN[31379] = { title = "Challenge At The Temple of the Red Crane", description = "The Temple of the Red Crane still reels from the aftermath of the sha's presence, and has only recently gathered to rebuild and retrain its warriors.\n\nIf you wish to help at the temple, speak to Thelonius at the Cradle of Chi-Ji.", objectives = "" }
WordHunterWoW_QuestEN[31380] = { title = "Trial At The Temple of the White Tiger", description = "Xuen, the great Celestial of the North, seeks the greatest champions in the land.\n\nToday, he holds trials of battle at his temple in Kun-Lai Summit.\n\nIf you wish to test yourself against skilled fighters from all across Pandaria, then go to him and enter the challenger's ring!", objectives = "" }
WordHunterWoW_QuestEN[31381] = { title = "Trial At The Temple of the White Tiger", description = "Xuen, the great Celestial of the North, seeks the greatest champions in the land.\n\nToday, he holds trials of battle at his temple in Kun-Lai Summit.\n\nIf you wish to test yourself against skilled fighters from all across Pandaria, then go to him and enter the challenger's ring!", objectives = "" }
WordHunterWoW_QuestEN[31382] = { title = "Defense At Niuzao Temple", description = "Niuzao Temple, far to the west, is under attack by the mantid.\n\nThe great Celestial holds them back for now, but he cannot stand alone forever.\n\nGo and help the defenders, {class}. The Temple must not fall!", objectives = "" }
WordHunterWoW_QuestEN[31383] = { title = "Defense At Niuzao Temple", description = "Niuzao Temple, far to the west, is under attack by the mantid.\n\nThe great Celestial holds them back for now, but he cannot stand alone forever.\n\nGo and help the defenders, {class}. The Temple must not fall!", objectives = "" }
WordHunterWoW_QuestEN[31384] = { title = "The Golden Lotus", description = "The Golden Lotus have guarded the Vale for centuries, keeping it safe and hidden from harm.\n\nRecent events have unleashed terrible horrors upon our sacred vale, but allies of the Golden Lotus still stand against them, attempting to bring peace.\n\nIf you wish to help, you had best join them at the Setting Sun Garrison.", objectives = "" }
WordHunterWoW_QuestEN[31385] = { title = "The Golden Lotus", description = "The Golden Lotus have guarded the Vale for centuries, keeping it safe and hidden from harm.\n\nRecent events have unleashed terrible horrors upon our sacred vale, but allies of the Golden Lotus still stand against them, attempting to bring peace.\n\nIf you wish to help, you had best join them at the Setting Sun Garrison.", objectives = "" }
WordHunterWoW_QuestEN[31386] = { title = "The Shado-Pan Offensive", description = "We Shado-Pan have amassed our forces for the first time in many ages.\n\nThe Sha of Hatred has escaped beyond the Serpent's Spine, and it is our sacred duty to imprison it once more.\n\nHowever, our warriors are great, but our numbers too few. Help from a capable {class} may not be turned away.\n\nIf you wish to join the offensive, speak to Taran Zhu in the Townlong Steppes.", objectives = "" }
WordHunterWoW_QuestEN[31387] = { title = "Understanding The Shado-Pan", description = "The Shado-Pan rank among Pandaria's oldest defenders.\n\nFor years we train in our snow-capped monastery high in the Kun-Lai Summit, perfecting the martial secrets passed down by our ancestors.\n\nOur numbers may seem few, but a single Shado-Pan can be deadlier than a hundred trained soldiers.\n\nTo join the Shado-Pan order is a long journey full of hardship. If this is the path you seek, then you must first prove your worth.\n\nThere is urgent work to be done here. Help the Golden Lotus defend the Vale.", objectives = "" }
WordHunterWoW_QuestEN[31388] = { title = "The Shado-Pan Offensive", description = "We Shado-Pan have amassed our forces for the first time in many ages.\n\nThe Sha of Hatred has escaped beyond the Serpent's Spine, and it is our sacred duty to imprison it once more.\n\nHowever, our warriors are great, but our numbers too few. Help from a capable {class} may not be turned away.\n\nIf you wish to join the offensive, speak to Taran Zhu in the Townlong Steppes.", objectives = "" }
WordHunterWoW_QuestEN[31389] = { title = "Understanding The Shado-Pan", description = "The Shado-Pan rank among Pandaria's oldest defenders.\n\nFor years we train in our snow-capped monastery high in the Kun-Lai Summit, perfecting the martial secrets passed down by our ancestors.\n\nOur numbers may seem few, but a single Shado-Pan can be deadlier than a hundred trained soldiers.\n\nTo join the Shado-Pan order is a long journey full of hardship. If this is the path you seek, then you must first prove your worth.\n\nThere is urgent work to be done here. Help the Golden Lotus defend the Vale.", objectives = "" }
WordHunterWoW_QuestEN[31390] = { title = "The Klaxxi", description = "The Klaxxi are only rumored to exist, far beyond the wall in the Dread Wastes.\n\nFew have ventured into that territory, and none have returned to tell the tale.\n\nIf you are set on finding these... Klaxxi... there is a small group of Shado-Pan manning the wall to the far southwest who may know more.", objectives = "" }
WordHunterWoW_QuestEN[31391] = { title = "The Klaxxi", description = "The Klaxxi are only rumored to exist, far beyond the wall in the Dread Wastes.\n\nFew have ventured into that territory, and none have returned to tell the tale.\n\nIf you are set on finding these... Klaxxi... there is a small group of Shado-Pan manning the wall to the far southwest who may know more.", objectives = "" }
WordHunterWoW_QuestEN[31392] = { title = "Temple of the White Tiger", description = "Have you heard the news, traveller? There's been an attack at one of our most sacred places, the Vale of Eternal Blossoms!\n\nEven now, there's a human prince within the White Tiger Temple arguing that you and the other races from beyond the mists should be allowed within.\n\nThe temple is in the northeast of Kun-Lai. Maybe you can convince the White Tiger to allow you inside?\n\nI only hope the Vale has not been utterly destroyed...", objectives = "" }
WordHunterWoW_QuestEN[31393] = { title = "Temple of the White Tiger", description = "Have you heard the news, traveller? There's been an attack at one of our most sacred places, the Vale of Eternal Blossoms!\n\nEven now, there's a human prince within the White Tiger Temple arguing that you and the other races from beyond the mists should be allowed within.\n\nThe temple is in the northeast of Kun-Lai. Maybe you can convince the White Tiger to allow you inside?\n\nI only hope the Vale has not been utterly destroyed...", objectives = "" }
WordHunterWoW_QuestEN[31394] = { title = "A Celestial Experience", description = "Nobody is allowed into the Vale without the approval of the August Celestials. Xuen, The White Tiger, appears ready to listen to me.\n\nBut Taran Zhu of the Shado-Pan is reluctant to let the Alliance or Horde anywhere NEAR the Vale after all that's happened.\n\n<Anduin shakes his head.>\n\nMaybe you can help me make my case. Speak to the White Tiger on our behalf. Be careful! He may set a number of challenges before you...", objectives = "" }
WordHunterWoW_QuestEN[31395] = { title = "A Celestial Experience", description = "The human calf is arguing on our behalf. He is well-spoken; I can see why Baine Bloodhoof regards the prince so highly.\n\nStill, the argument does not go well. I am of little consequence, but you are a hero of the Horde. Perhaps you can intercede in our favor?\n\nSpeak with the White Tiger and plead our case, {race}.\n\nBe careful! He may set a number of challenges before you...", objectives = "" }
WordHunterWoW_QuestEN[31398] = { title = "Falling to Pieces", description = "Why would the saurok have amber? More importantly, why would Oracle Hiss'ir be so protective of it?\n\nIt is unlikely this came from the heavily guarded Zan'vess, so where did it come from?\n\nPerhaps the Klaxxi will know what to make of it.", objectives = "" }
WordHunterWoW_QuestEN[31439] = { title = "Dropping Our Signal", description = "The beacon in Amberglow Hollow seems to have been tampered with. Right before the signal cut out the Klaxxi'va picked up a signal for another paragon nearby.\n\nThey believe he is hidden in that wretched little swamp, Duskroot Fen.\n\nI will meet you in the fen to set up a temporary beacon until I can get Amberglow operational again.\n\nYou will wake the paragon and then you will help me.", objectives = "" }
WordHunterWoW_QuestEN[31440] = { title = "The Four Tomes", description = "There are four tomes of great necromantic evil studied in Scholomance: \"In the Shadow of the Light\", \"Kel'Thuzad's Deep Knowledge\", \"Forbidden Rites and other Rituals Necromantic\" and \"The Dark Grimoire\".\n\nAs we make our way through this cursed place, find and destroy each book so that no other fool can come along later and learn their vile secrets.", objectives = "" }
WordHunterWoW_QuestEN[31441] = { title = "Corruption Runs Deep", description = "Today you learn that no one can be trusted in times of war, Wakener. Even those closest to the Klaxxi are susceptible to corruption.\n\nWho knows how long this traitor has been corrupted. He must be destroyed!\n\nYou appear confused. Do you not see the traitor in our midst? Allow me to adjust your vision.", objectives = "" }
WordHunterWoW_QuestEN[31442] = { title = "The Four Tomes", description = "There are four tomes of great necromantic evil studied in Scholomance: \"In the Shadow of the Light\", \"Kel'Thuzad's Deep Knowledge\", \"Forbidden Rites and other Rituals Necromantic\" and \"The Dark Grimoire\".\n\nAs we make our way through this cursed place, find and destroy each book so that no other fool can come along later and learn their vile secrets.", objectives = "" }
WordHunterWoW_QuestEN[31443] = { title = "Flying Tiger Gourami", description = "You've caught a unique fish... with wings.  Perhaps it deserves the expert opinion of Nat Pagle in Anglers Wharf.\n", objectives = "" }
WordHunterWoW_QuestEN[31444] = { title = "Spinefish Alpha", description = "You have fished up something special.  It looks pretty aggressive.\n\nMaybe Nat Pagle at the Anglers Wharf might know more about it?\n", objectives = "" }
WordHunterWoW_QuestEN[31446] = { title = "Mimic Octopus", description = "You aren't sure how, but you've caught an extraordinary cephalopod.  Nat Pagle at Anglers Wharf would be very interested to see it.\n", objectives = "" }
WordHunterWoW_QuestEN[31447] = { title = "An End to the Suffering", description = "The key to lifting the curse of this place rests in the final death of Darkmaster Gandling.\n\nDo it, {name}, and make him suffer!", objectives = "" }
WordHunterWoW_QuestEN[31448] = { title = "An End to the Suffering", description = "The key to lifting the curse of this place rests in the final death of Darkmaster Gandling.\n\nDo it, {name}, and make him suffer!", objectives = "" }
WordHunterWoW_QuestEN[31450] = { title = "A New Fate", description = "These new allies have shed light on a great and important truth: it is not just Shen-zin Su that is ailing, but all of the land beyond the clouds. The world needs healing, and I think that you should be the ones to heal it.\n\nI would like you, Ji, and Aysa to leave and bring your strength and wisdom to the world. These Alliance and Horde have different ideals, but at the core of both lies noble intent.\n\nI will leave the choice of who you wish to accompany to you.", objectives = "" }
WordHunterWoW_QuestEN[31451] = { title = "The Missing Merchant", description = "Usually, Merchant Shi comes through Kun-Lai Summit to trade with the Jinyu and Grummle. We've heard word that he hadn't been seen at Binan, and we haven't seen him here...\n\nI'm worried something has happened to him. Can you go to the Inkgill Mere and see if he's there?", objectives = "" }
WordHunterWoW_QuestEN[31452] = { title = "The Missing Merchant", description = "Usually, Merchant Shi comes through Kun-Lai Summit to trade with the Jinyu and Grummle. We've heard word that he hadn't been seen at Binan, and we haven't seen him here...\n\nI'm worried something has happened to him. Can you go to the Inkgill Mere and see if he's there?", objectives = "" }
WordHunterWoW_QuestEN[31453] = { title = "The Shado-Pan", description = "Our new recruits have spoken in hushed tones about a group of Pandaren they call the \"Shado-Pan\". They are apparently very strong, and secretive.\n\nIt's clear that, no matter what happens here in Kun-Lai, making an alliance with these Shado-Pan will be critical to our foothold in Pandaria.\n\nThat's where you come in. Rumor is they have a base of operations to the southeast, near Firebough Nook.\n\nYou will go there, and curry their favor. For the Horde!", objectives = "" }
WordHunterWoW_QuestEN[31455] = { title = "The Shado-Pan", description = "Our new recruits have spoken in hushed tones about a group of Pandaren they call the \"Shado-Pan\". They are apparently very strong, and secretive.\n\nThat's where you come in. Rumor is they have a base of operations to the southeast, near Firebough Nook. You should travel there as an envoy of the Alliance. Give them any help they require.", objectives = "" }
WordHunterWoW_QuestEN[31456] = { title = "Muskpaw Ranch", description = "There's another Pandaren settlement out here, Muskpaw Ranch. I don't know if they're alright, what with everything that's been going on with the Yaungol invasion.\n\nYou've been so helpful - you should go check up on them, friend!", objectives = "" }
WordHunterWoW_QuestEN[31457] = { title = "Muskpaw Ranch", description = "There's another Pandaren settlement out here, Muskpaw Ranch. I don't know if they're alright, what with everything that's been going on with the Yaungol invasion.\n\nYou've been so helpful - you should go check up on them, friend!", objectives = "" }
WordHunterWoW_QuestEN[31458] = { title = "Damage Control", description = "Kor'ik has been sending signals to the empress for weeks. Everything the Klaxxi have done, the empress knows about.\n\nThat stops now!\n\nKypari Ik will be the first to receive news of Kor'ik's demise. It would benefit us to make sure that message does not make it to the empress.\n\nDestroying the whisperers and beacon there will buy us enough time to come up with a plan before the empress can act.", objectives = "" }
WordHunterWoW_QuestEN[31459] = { title = "Cho's Missive", description = "One of those grummles came by and said that Lorewalker Cho sent for you. You should go ahead and meet up with him, he might have something important to say.\n\nThe grummel said he's at Onekeg, to the north.", objectives = "" }
WordHunterWoW_QuestEN[31460] = { title = "Cho's Missive", description = "One of those adorable little grummles came by and said that Lorewalker Cho sent for you. You should meet up with him!\n\nThe grummel said he's at Onekeg, to the north.", objectives = "" }
WordHunterWoW_QuestEN[31465] = { title = "Extracting Answers", description = "Kypari Ik is just one of many locations that houses some of Empress Shek'zeer's offspring. In their juvenile state the young are reckless and difficult to control. They are also deadly.\n\nSwarmborn are hatched with a highly toxic venom that diminishes in potency with age. The venom can incapacitate even the strongest and most skilled fighter if it hits flesh.\n\nI would like you to bring me some of this venom.", objectives = "" }
WordHunterWoW_QuestEN[31467] = { title = "Strong as a Tiger", description = "With the grill, you can transform those raw tiger steaks into food that makes you stronger. Learn the recipe for charbroiled tiger steaks from me. Show me what you can do.", objectives = "" }
WordHunterWoW_QuestEN[31468] = { title = "Trial of the Black Prince", description = "I have on good authority that you are a champion among champions, but if you'll permit me this indulgence, I would like to test your mettle for myself.\n\nThe mogu who assault the Vale of Eternal Blossoms, the mogu minions who inhabit Shan'ze Dao, and the sha-corrupted mantid swarming the Dread Wastes... these may provide an adequate challenge for one of your stature.\n\nProve yourself to me. No rush - I expect this to take you some time.", objectives = "" }
WordHunterWoW_QuestEN[31470] = { title = "Way of the Wok", description = "If you wish to make dishes that enhance agility, you should bring some carrots and rice to the Master of the Wok. The virmen around here tend to carry a lot of carrots around. You can also grow your own, if you have a farm.", objectives = "" }
WordHunterWoW_QuestEN[31471] = { title = "Agile as a Tiger", description = "To cook with the wok, you need to be nimble. Your first lesson is sauteed carrots.\n", objectives = "" }
WordHunterWoW_QuestEN[31472] = { title = "Way of the Pot", description = "The cuisine of the Way of the Pot help expand your intellect. Bring some jade lungfish to the Master of the Pot and she will teach you. You can fish for jade lungfish in the Jade Forest.", objectives = "" }
WordHunterWoW_QuestEN[31473] = { title = "The Strength of One's Foes", description = "Great leadership requires the power to shape the destiny of your people, and the wisdom to make the right decisions. Pandaria boasts great power and ancient wisdom, but rarely in the same place.\n\nLet's see if you and I can change that!\n\nAcquire sigils of power and wisdom from fallen foes in the Mogu'shan Vaults, the Heart of Fear, or the Terrace of Endless Spring. We will put them to a much better use than their current owners.", objectives = "" }
WordHunterWoW_QuestEN[31474] = { title = "The Soup of Contemplation", description = "Watching over the pot, you get a lot of time to think. Let me show you how to make swirling mist soup and you'll know what I mean.", objectives = "" }
WordHunterWoW_QuestEN[31475] = { title = "Way of the Steamer", description = "A great meal can lift your spirits, and none more so than food from the Way of the Steamer. Bring the Master some giant mantis shrimp and he will show you. You can fish for giant mantis shrimp in the ocean.", objectives = "" }
WordHunterWoW_QuestEN[31476] = { title = "The Spirit of Cooking", description = "When I cook with steam, I infuse the food with my love. Let me teach you the recipe for shrimp dumplings.", objectives = "" }
WordHunterWoW_QuestEN[31477] = { title = "Endurance", description = "They say that the crane appointed sentry by its flock stands guard with a stone in its beak, so that, should it fall asleep, the stone drops and it awakens. To be skilled with the oven, you need to have endurance and patience. Learn the recipe for wildfowl roast and show me that you understand.", objectives = "" }
WordHunterWoW_QuestEN[31478] = { title = "Way of the Oven", description = "If you are looking for a hearty meal that will sustain you and increase your stamina, you should seek out the Way of the Oven. Bring some wildfowl breasts to the Master of the Oven and she will teach you. There are plenty of cranes in the Valley of the Four Winds and in the Jade Forest, but you can obtain wildfowl breasts from other birds as well.", objectives = "" }
WordHunterWoW_QuestEN[31479] = { title = "Way of the Brew", description = "The Pandaren Way of the Brew produces... Well, I'll let the Master of the Brew explain it. Bring him some ginseng and he will show you the way.", objectives = "" }
WordHunterWoW_QuestEN[31480] = { title = "Have a Drink", description = "My siblings are so serious. I think life's too short to be so serious all the time. Let's have some tea together. Let me teach you how to make ginseng tea.", objectives = "" }
WordHunterWoW_QuestEN[31481] = { title = "Fear Itself", description = "I've picked up a few motes of pandaren wisdom during my time here. I particularly enjoy this one:\n\n\"The timid feel fear before trouble starts; the cowards feel fear as trouble happens. The bravest among us feel fear only after the troubles have been taken care of.\"\n\nIs that true? Let's find out.\n\nThe Sha of Fear has fled into the Terrace of Endless Spring. Pursue it there, defeat it, and rip out its spirit - presuming it has one.\n\nYour bravery will be handsomely rewarded.", objectives = "" }
WordHunterWoW_QuestEN[31482] = { title = "Breath of the Black Prince", description = "<Wrathion's piercing red eyes fixate on you.>\n\nYou are among a rare breed, {name}.\n\nYou are just what I am looking for - an individual with the potential to shape events on a global scale.\n\nCome now, I promised you a reward, and you shall have it! East of this tavern is a series of stone steps leading up to a vista that the locals have named \"Mason's Folly.\" Meet me there.", objectives = "" }
WordHunterWoW_QuestEN[31483] = { title = "Incoming...", description = "The Pandaren campaign is only beginning! We turn our attention now to the ongoing conflict between the Alliance and the Horde.\n\nMy contacts in Ravenholdt tell me that the Alliance 7th Legion and a considerable Horde invasion force are converging toward Pandaria's southern shores. Like it or not, Pandaria may soon become a battlefield.\n\nWe are done for now, but I want you to contact me when your fleet arrives. Then... together we will spring into action!", objectives = "" }
WordHunterWoW_QuestEN[31486] = { title = "Everything I Know About Cooking", description = "I'm so glad you enjoy my food. Are you interested in the recipes?  If so, you should learn them properly, from my teachers in Halfhill Market.  Everything I know about the kitchen, I learned from them.\n\nSay, if you happen to pass through there, would you deliver this note to Sungshin Ironpaw for me? She was my favorite teacher, and I want her to know that I miss her.", objectives = "" }
WordHunterWoW_QuestEN[31487] = { title = "Sonic Disruption", description = "Relying on sonic whispers to manipulate the kunchong was only the most primitive stage of my research, and yet the Empire seems to have adopted the practice wholly. The manipulators of the Shek'zeer are too impatient to form a proper bond with their kunchong.\n\nTheir laziness will cost them dearly.\n\nStrike this tuning fork near the dread kunchong in the clutches - watch as they reel in confusion and lash out at their masters. Use this to your advantage and put them down.", objectives = "" }
WordHunterWoW_QuestEN[31490] = { title = "Rank and File", description = "First things first; let's kill us some crusaders.\n\nAnd when I say kill the Scarlet Crusade, I mean wipe them out, root and branch, rank and file.", objectives = "" }
WordHunterWoW_QuestEN[31492] = { title = "The Torch of Strength", description = "Xuen has this challenge he says helps \"refine strength.\" I am starting to think the word \"strength\" means something different to him than the rest of us.\n\nHere, take this torch to the top of the gates of the temple. If you can get it there without the torch being extinguished, you pass the challenge.\n\nWhatever you do, do not try carrying the torch on a mount. It will blow out if you do. Trust me on that one.", objectives = "" }
WordHunterWoW_QuestEN[31493] = { title = "Just for Safekeeping, Of Course", description = "There is a book of great value to me here in the halls.\n\nUnfortunately, it's in the possession of Flameweaver Koegler. I've tried to get close to him before, but it's never quite worked out.\n\nYou might have better luck. Just watch out -- I hear that he's gone well and truly insane. The Flameweaver plans to burn every tome they have in the library.\n\nHe'll probably burn the Scarlet Halls down in the process.", objectives = "" }
WordHunterWoW_QuestEN[31494] = { title = "Free From Her Clutches", description = "The Shek'zeer manipulators are corralling young kunchong into that clutch and exposing them to raw fear energies, twisting them and accelerating their growth.\n\nDisgusting! I will not allow it!\n\nBreak open the cages and set those hatchlings free.", objectives = "" }
WordHunterWoW_QuestEN[31495] = { title = "Rank and File", description = "First things first; let's kill us some crusaders.\n\nAnd when I say kill the Scarlet Crusade, I mean wipe them out, root and branch, rank and file.", objectives = "" }
WordHunterWoW_QuestEN[31496] = { title = "Sampling the Empire's Finest", description = "The wonders of the kypari sap never cease to amaze me. Among its numerous properties and applications, the sap can be refined into a nutritious and extremely delectable elixir.\n\nNowhere in the Empire will you find a finer execution of this brew than the palace itself. Surely, the homes of the loyalists have feeders brimming with this sweet nectar.\n\nFill this jar at their feeders and return it to me. I long to sample the imperial ambrosia once more.", objectives = "" }
WordHunterWoW_QuestEN[31497] = { title = "Just for Safekeeping, Of Course", description = "There is a book of great value to me here in the halls.\n\nUnfortunately, it's in the possession of Flameweaver Koegler. I've tried to get close to him before, but it's never quite worked out.\n\nYou might have better luck. Just watch out -- I hear that he's gone well and truly insane. The Flameweaver plans to burn every tome they have in the library.\n\nHe'll probably burn the Scarlet Halls down in the process.", objectives = "" }
WordHunterWoW_QuestEN[31502] = { title = "Wing Clip", description = "The young fliers of this era are fascinating. Their exceptional agility and endurance were, in my time, the feats of incredibly skilled or mature fliers.\n\nThis would seem to indicate some kind of evolution in wing structure... Or perhaps a result of advancements in training? Induced genetic mutation? Selective breeding?\n\nGah! There's no way to know for certain without tissue samples.\n\nBring me their wings! And try not to ruin them in the process, will you? I need them intact!", objectives = "" }
WordHunterWoW_QuestEN[31503] = { title = "Shortcut to Ruin", description = "There is a champion among the loyalists, Vess-Guard Na'kal, whose strength comes not from experience or development, but from genetic modification. He was meant to be an example of the future of mantid - the sick idea that we can be born strong, without earning it.\n\nHe's a mockery of my work! Gene augmentation was meant for mature, post-swarm veterans ONLY!\n\nEnd him. Perhaps it will serve as a lesson to Grand Empress Shek'zeer that taking shortcuts leads to ruin.", objectives = "" }
WordHunterWoW_QuestEN[31504] = { title = "Ordnance Disposal", description = "If the Grand Empress's agents are still operating under security standards from my time, they would have hidden powerful pheromone mines all around the clutches.\n\nWith mere whisper she could detonate them all simultaneously, engulfing the palace and rendering entire siege armies powerless.\n\nIf we hope to have any success in a large scale standoff, we need to disable those mines. My... \"gift\" to you when we met will allow you to see the mines. Disturb them and get to a safe distance.", objectives = "" }
WordHunterWoW_QuestEN[31505] = { title = "Vess-Guard Duty", description = "Vess-Guard Vik'az co-ordinates the defense forces at Zan'vess. He is worth ten mantid in battle, and his presence inspires the Zan'thik who fight alongside him.\n\nNeedless to say, we need him dead.\n\nHe patrols the housing area at the center of the island.", objectives = "" }
WordHunterWoW_QuestEN[31506] = { title = "Shackles of Manipulation", description = "The Zan'thik employ a sizable force of... indentured labor.\n\nYaungol are bound in special shackles which enhance and prolong the effects of sonic manipulation. It is this technology that allows the Zan'thik manipulators to command such large quantities of thralls to endlessly toil for them in the quarries.\n\nI would like to study these shackles.", objectives = "" }
WordHunterWoW_QuestEN[31507] = { title = "Meltdown", description = "The venomsting scorpions on Zan'vess are fed sap from a young age, causing a fascinating mutation in which their natural armor plating becomes infused with amber. Effectively, it's organic kyparite, the same substance used in forging most of the empire's weapons and armor.\n\nI think I've found a way to chemically break down kyparite, but it needs testing. Use these grenades on the Zan'thik venomstings and observe the results.", objectives = "" }
WordHunterWoW_QuestEN[31508] = { title = "Specimen Request", description = "Kyparite worms have shown extreme adaptations in order to mimic the environment around them. They can also grow to immense sizes at rates which are nearly unheard of for most creatures.\n\nTheir physiology could provide valuable insight into further mutations.\n\nBring me sample shards from the muck tunnelers in the shallows near Zan'vess.", objectives = "" }
WordHunterWoW_QuestEN[31509] = { title = "Fear Takes Root", description = "The fallout from Shek'zeer's madness will continue long after her reign has ended. We will struggle to heal our lands for many years to come, and even then our efforts may prove fruitless.\n\nA new species of sha-twisted flora has begun taking root near Zan'vess. Destroy any that you find, but beware - there is no telling what kind of sinister defenses it may have.", objectives = "" }
WordHunterWoW_QuestEN[31510] = { title = "Quiet Now", description = "On the southwestern corner of Zan'vess lie the Whispering Stones. Much like the towers here, they are critical in transmitting long-range sonic signals.\n\nAn adjunct of the Empress operates the stones, keeping her in communication with the Zan'thik forces. Disrupt the signal, then silence him.", objectives = "" }
WordHunterWoW_QuestEN[31511] = { title = "A Witness to History", description = "I will gather up the other Tauren pilgrims and we will travel into the Vale together.\n\nMeet me at the Gate of the August Celestials at the southern edge of Kun-Lai Summit and speak with me there.", objectives = "" }
WordHunterWoW_QuestEN[31512] = { title = "A Witness to History", description = "The celestials are allowing us back into the Vale! This will be a sight to behold.\n\nWe shouldn't waste any time. Head to the Gate of the August Celestials at the southern edge of Kun-Lai Summit and speak with me there.", objectives = "" }
WordHunterWoW_QuestEN[31513] = { title = "Blades of the Anointed", description = "The problem with the Scarlet Crusade is that they keep coming back, even after death.\n\nBehind those resurrections is High Inquisitor Whitemane. With her death, so goes the Crusade.\n\nTo give her the final rest, we need two swords of legend, each with a lost but storied history.\n\nLuckily for me... er, us, these two blades of the anointed are at rest here within the monastery.\n\nFind them and once you've killed Whitemane, plunge the blades into her corpse to make the death permanent.", objectives = "" }
WordHunterWoW_QuestEN[31514] = { title = "Unto Dust Thou Shalt Return", description = "<You take the second anointed blade in hand and feel the power of both swords course through you.>\n\n<There is but one thing left to do. As the mysterious, hooded woman explained, to put an end to the Scarlet Crusade, you must thrust both blades into the corpse of High Inquisitor Whitemane.>", objectives = "" }
WordHunterWoW_QuestEN[31515] = { title = "Blades of the Anointed", description = "The problem with the Scarlet Crusade is that they keep coming back, even after death.\n\nBehind those resurrections is High Inquisitor Whitemane. With her death, so goes the Crusade.\n\nTo give her the final rest, we need two swords of legend, each with a lost but storied history.\n\nLuckily for me... er, us, these two blades of the anointed are at rest here within the monastery.\n\nFind them and once you've killed Whitemane, plunge the blades into her corpse to make the death permanent.", objectives = "" }
WordHunterWoW_QuestEN[31516] = { title = "Unto Dust Thou Shalt Return", description = "<You take the second anointed blade in hand and feel the power of both swords course through you.>\n\n<There is but one thing left to do. As the mysterious, hooded woman explained, to put an end to the Scarlet Crusade, you must thrust both blades into the corpse of High Inquisitor Whitemane.>", objectives = "" }
WordHunterWoW_QuestEN[31517] = { title = "Contending With Bullies", description = "We honor strength here, not brutality. It is unfortunate but there are some who come to my doorstep oblivious to this distinction.\n\nI have turned away one such challenger. In retaliation, he sacked the village of Yinying.\n\nGo to Yinying Village southeast of the temple, and face this \"Shonuf.\" Give him a lesson in true strength.", objectives = "" }
WordHunterWoW_QuestEN[31518] = { title = "The Vale of Eternal Blossoms", description = "It's been many lifetimes since the gates to the valley were open, {name}.\n\nI wouldn't miss this for the world, and neither should you!\n\nMeet me at the southen edge of Kun-Lai Summit. I'll wait for you there.", objectives = "" }
WordHunterWoW_QuestEN[31519] = { title = "A Worthy Challenge: Yan-zhu the Uncasked", description = "{name}, I need you to assemble a hearty group and lead them into Stormstout Brewery. Activate the Challenger's Orb therein, and evaporate Yan-zhu the Uncasked.\n\nReturn to me when you've completed this challenge, and I shall reward you handsomely.", objectives = "" }
WordHunterWoW_QuestEN[31520] = { title = "A Worthy Challenge: Sha of Doubt", description = "{name}, I need you to assemble a hearty group and lead them into the Temple of the Jade Serpent. Activate the Challenger's Orb therein, and vanquish the Sha of Doubt.\n\nReturn to me when you've completed this challenge, and I shall reward you handsomely.", objectives = "" }
WordHunterWoW_QuestEN[31521] = { title = "To Be a Master", description = "There will come a day when you have mastered all that we have to teach you. When that day comes, it will be time for you to teach others in turn. When you have proven to yourself that you have mastered all the Ways, come back and speak with me.", objectives = "" }
WordHunterWoW_QuestEN[31522] = { title = "A Worthy Challenge: Sha of Hatred", description = "{name}, I need you to assemble a tranquil group and lead them into the Shado-Pan Monastery. Activate the Challenger's Orb therein, and rescue Taran Zhu from the Sha of Hatred.\n\nReturn to me when you've completed this challenge, and I shall reward you handsomely.", objectives = "" }
WordHunterWoW_QuestEN[31523] = { title = "A Worthy Challenge: Xin the Weaponmaster", description = "{name}, I need you to assemble a nimble group and lead them into Mogu'shan Palace. Activate the Challenger's Orb therein, and put an end to Xin the Weaponmaster.\n\nReturn to me when you've completed this challenge, and I shall reward you handsomely.", objectives = "" }
WordHunterWoW_QuestEN[31524] = { title = "A Worthy Challenge: Raigonn", description = "{name}, I need you to assemble a cracking group and lead them into the Gate of the Setting Sun. Activate the Challenger's Orb therein and lay waste to Raigonn.\n\nReturn to me when you've completed this challenge, and I shall reward you handsomely.", objectives = "" }
WordHunterWoW_QuestEN[31525] = { title = "A Worthy Challenge: Wing Leader Ner'onok", description = "{name}, I need you to assemble an eagle-eyed group and lead them into the Siege of Niuzao Temple. Activate the Challenger's Orb and ground Wing Leader Ner'onok.\n\nReturn to me when you've completed this challenge, and I shall reward you handsomely.", objectives = "" }
WordHunterWoW_QuestEN[31526] = { title = "A Worthy Challenge: Durand", description = "{name}, I need you to assemble a stout group and lead them into Scarlet Monastery. Activate the Challenger's Orb therein, and smite Durand with righteous fury.\n\nReturn to me when you've completed this challenge, and I shall reward you handsomely.", objectives = "" }
WordHunterWoW_QuestEN[31527] = { title = "A Worthy Challenge: Flameweaver Koegler", description = "{name}, I need you to assemble a cunning group and venture forth into the depths of Scarlet Halls. Activate the Challenger's Orb therein, and put a stop to Flameweaver Koegler's book-burning ways.", objectives = "" }
WordHunterWoW_QuestEN[31528] = { title = "A Worthy Challenge: Darkmaster Gandling", description = "{name}, I need you to assemble a fearless group and lead them into the depths of Scholomance. Activate the Challenger's Orb, and cleanse Scholomance of Darkmaster Gandling's evil presence.\n\nReturn to me when you've completed this challenge and I shall reward you handsomely.", objectives = "" }
WordHunterWoW_QuestEN[31529] = { title = "Mission: Culling The Vermin", description = "I was sent to this valley to protect The Heartland from any potential threats.\n\nI've identified a high priority target. The Springtail vermin burrow into the mountain cliffs, high above the farmlands.\n\nLeft unchecked, their numbers will multiply, and they will make their way down to the fields below.\n\nThey must be eliminated.", objectives = "" }
WordHunterWoW_QuestEN[31530] = { title = "Mission: The Hozen Dozen", description = "I've been watching the hozen since I arrived, and I don't like the pattern of activity that I'm seeing in their camp.\n\nMultiple hozen travel down the mountain under the cover of night, pillaging supplies from the farmlands below.\n\nWe must stop their rampant theft. I have been thinning their numbers when I can, but one soldier alone is not enough.\n\nI need your help. Kill as many of the hozen as you can.", objectives = "" }
WordHunterWoW_QuestEN[31531] = { title = "Mission: Aerial Threat", description = "I've identified another high risk target, one that most people would not suspect.\n\nThe cliff kites soaring above the hills to the east are quite dangerous.\n\nI have seen them swooping down to the farms, snatching grain and seed when no one is looking.\n\nIn order to protect the farms, we must thin their numbers.", objectives = "" }
WordHunterWoW_QuestEN[31532] = { title = "Mission: Predator of the Cliffs", description = "During my routine patrol of the mountains this morning, I spotted a huge white bird diving down to the farmlands.\n\nIt lifted an entire yak in its talons and disappeared among the cliffs.\n\nToday a yak, tomorrow a farmhand!\n\nWe must eliminate this bird before it chooses its next victim.", objectives = "" }
WordHunterWoW_QuestEN[31534] = { title = "The Beginner's Brew", description = "Can you keep a secret, {name}?\n\nI've been trying my hand at brewing. All I've got is this old hand-made still, but it still works pretty good.\n\nI've got an idea for a new brew, but I need some ingredients.\n\nI'm awful shy around the townsfolk, but I've seen you making friends all around.\n\nWould you be willing to ask the farmers for some ingredients for me?", objectives = "" }
WordHunterWoW_QuestEN[31536] = { title = "Preserving Freshness", description = "To preserve maximum freshness, cooking ingredients need to be stored properly. Fortunately, Merchant Cheng over there sells good containers.  I hate to send you on such a menial errand, but would you go purchase an empty tiger meat basket for me? ", objectives = "" }
WordHunterWoW_QuestEN[31537] = { title = "Ella's Taste Test", description = "Well, I finally got the brew made, but I won't know if it's any good unless some people taste it.\n\nWould you take my brew and see what the folks in Halfhill think?\n\nI... I couldn't face them myself.", objectives = "" }
WordHunterWoW_QuestEN[31538] = { title = "A Worthy Brew", description = "There's one final person who needs to taste my brew.\n\nI've heard that he's traveled far and wide, and tasted drinks from all over the world.\n\nHe happens to be in town, and I'd like to know what he thinks of my skills.", objectives = "" }
WordHunterWoW_QuestEN[31539] = { title = "A Thing of Beauty", description = "We live in a world of magic.The few among us who are skilled can imbue this magic into the things we craft and give them power. Such things are valued.\n\nFewer still, however, are those among us who can create things that are cherished through the ages not because they are imbued with power, but because of their great beauty.\n\nThe Temple of the Jade Serpent has commissioned us for such a work, and I believe you are the worthiest among us.  Will you accept the commission?", objectives = "" }
WordHunterWoW_QuestEN[31540] = { title = "Staves for Tian Monastery", description = "It seems like the Tian Monsatery is training a lot of monks this year. We've received a huge commission for staves. And by huge, I mean HUGE.\n\nCould you take on part of the commission? I'd very much appreciate it. You will receive the rewards for your portion, of course.", objectives = "" }
WordHunterWoW_QuestEN[31541] = { title = "Set in Jade", description = "One of the greatest poets of our time is Master Kwang. He has composed a poem of great beauty, and a merchant in Halfhill would like to have these words inscribed in stone, to display proudly in her home. She has requested a scribe of great skill to take on this job. Will you accept the commission?", objectives = "" }
WordHunterWoW_QuestEN[31542] = { title = "Incarnadine Ink", description = "The practice of caligraphy is an old custom in Pandaria. I am working on a piece about an ancient war, so I seek an ink that is suitable to the subject matter.\n\nI have searched high and low for the right hue, but it eludes me. Can you think of  a way to achieve the color I am seeking?", objectives = "" }
WordHunterWoW_QuestEN[31543] = { title = "Portrait of a Lady", description = "Many great pieces of art are results of great love.  A merchant in Halfhill wishes to have a portrait made for his beloved, as a birthday present.  Will you accept this commission?", objectives = "" }
WordHunterWoW_QuestEN[31544] = { title = "A Tribute to the Dead", description = "All things must come to an end - even the life of a good man.  A family in Kun Lai has commissioned a monument for their beloved patriarch who has passed on recently.  Will you accept the commission?", objectives = "" }
WordHunterWoW_QuestEN[31545] = { title = "The Finer Things", description = "The Pandaria Treasure Society is interested in purchasing finely crafted goods from skilled jewelcrafters such as yourself.  The items will be catalogued, and the most exceptional cuts stored in a secret vault, while the rest are sold to refresh our funds.\n\nOur goal is to eventually create a unique collection for a special event.", objectives = "" }
WordHunterWoW_QuestEN[31548] = { title = "Learning the Ropes", description = "Now that you are a pet trainer, it's time to test your skills!\n\nHead out into the valley and pick a fight with a battle pet.  Come back to me after you have won and I will continue your training.  Good luck!", objectives = "" }
WordHunterWoW_QuestEN[31549] = { title = "On The Mend", description = "Now that you have won a battle, we need to heal up your pets so they can fight another day!  Visit Shelby Stoneflint, our local stable master, to heal and revive your pets.", objectives = "" }
WordHunterWoW_QuestEN[31550] = { title = "Got one!", description = "Great work so far {name}.  You are going to be a pro at this pet stuff before you know it.  Now it's time to catch a pet of your own!\n\nHead back out and find a battle pet to fight, engage it in battle and throw your trap once it's low on health.  Bring your catch back for me to see once you are finished.\n\nRemember, you need at least one pet at level 3 to use your trap!", objectives = "" }
WordHunterWoW_QuestEN[31551] = { title = "Got one!", description = "Great work so far, {name}!  You are going to be a pro at this pet stuff before you know it.  Now it's time to catch a pet of your own!\n\nHead back out and find a battle pet to fight, engage it in battle, and throw your trap once it's low on health.  Bring your catch back for me to see once you are finished.\n\nRemember, you need at least one pet at level 3 to use your trap!", objectives = "" }
