WordHunterWoW_QuestEN[31598] = { title = "Kypa'rak's Core", description = "<As the ringworm tumbles apart, a massive chunk of organic kyparite falls from its core. Someone at Klaxxi'vess will want to see this.>", objectives = "" }
WordHunterWoW_QuestEN[31599] = { title = "The Matriarch's Maw", description = "<The enormous mandibles of the kunchong matriarch Karanosh should be of value to someone in Klaxxi'vess.>", objectives = "" }
WordHunterWoW_QuestEN[31605] = { title = "The Zan'thik Dig", description = "We have just intercepted a message from an adjunct on Zan'vess. Yaungol laborers there have unearthed a paragon in the amber quarry on the back side of the island.\n\nGet there immediately and free him before the Zan'thik destroy him!", objectives = "" }
WordHunterWoW_QuestEN[31606] = { title = "The Dissector Wakens", description = "You are... not like the others...\n\nI hear the Klaxxi calling... <cough>\n\nI just need a moment.", objectives = "" }
WordHunterWoW_QuestEN[31609] = { title = "The Wrath of Shek'zeer", description = "The rest of the freed paragons are scattered around the Heart of Fear, fighting off the mantid swarm. They may need your help!", objectives = "" }
WordHunterWoW_QuestEN[31611] = { title = "The Kun-Lai Kicker", description = "Have you ever seen the Brewmoon Festival?\n\nThe good folks of Binan Village host quite a party. And tonight's festivities are brew-catered by none other than yours truly here.\n\nI am making my famous Kun-Lai Kicker!\n\nThink you might come and join us for the festivities? It should be a completely relaxing event with absolutely no danger whatsoever.", objectives = "" }
WordHunterWoW_QuestEN[31612] = { title = "Shadow of the Empire", description = "You only understand part of our order. You are an outsider, and have been treated as such.\n\nIt is no longer appropriate that we keep our secrets from you. There is something you should see.", objectives = "" }
WordHunterWoW_QuestEN[31613] = { title = "Volatile Greenstone Brew", description = "I am working on a batch of my famous Volatile Greenstone Brew.\n\nShould be superb in countering the rascals and mischievous elementals we have been seeing around the mines lately.\n\nTell you what, how about you round up some of your friends and bring them back here to try out a round.\n\nFirst one's on the house!", objectives = "" }
WordHunterWoW_QuestEN[31656] = { title = "The Threat in the South", description = "With the Sha of Hatred dead, the greatest threat to this land is vanquished, but our travels along the southern border have made it exceedingly clear that the mantid forces in the Dread Wastes are on the move, and likely won't be held back for long.\n\nIf you wish to continue to aid the Shado-Pan, I would recommend reporting in to Bowmistress Li on the Serpent's Spine. She oversees the great wall that separates the terrors in the Dread Wastes from our bountiful lands to the east.", objectives = "" }
WordHunterWoW_QuestEN[31660] = { title = "Not Fit to Swarm", description = "Newly hatched mantid have only two instincts: kill and feed. They turn on one another, devouring the weak and leaving the strongest to mature.\n\nThose hatched during a swarm - the swarmborn - are turned loose on our enemies instead.\n\nThe swarmborn in the Clutches of Shek'zeer have been tainted. They are born into shadows and nightmares. Driven by terror, not hunger.\n\nThey are not fit to swarm. They must be purged.", objectives = "" }
WordHunterWoW_QuestEN[31661] = { title = "A Source of Terrifying Power", description = "<The clutch-keepers seem to be using these blinding white crystals as magical foci. Peering inside, you see thick tendrils of black smoke swirling in the center. One of the workers at Klaxxi'vess may know more about this material and why it is so abundant in the wastes.>", objectives = "" }
WordHunterWoW_QuestEN[31669] = { title = "The Cabbage Test", description = "Grandpa always said that the bellweather of a true farmer lies in the quality of his cabbage. Any time a new farmer came into town, he'd buy a few heads of cabbage to see what they knew.\n\nNow, I'm the new farmer, and this is my big chance to prove myself. Could you plant some cabbage for me?", objectives = "" }
WordHunterWoW_QuestEN[31670] = { title = "That Dangling Carrot", description = "Grandpa always said, \"Carrots ain't nothin but a welcomin' mat for virmen.\" I don't think I ever saw him grow a single carrot.\n\nFor once, I disagree with Grandpa. I like to live on the edge. Plus, I like to eat carrots.\n\nI like to eat carrots on the edge.\n\nCould you get some seeds and grow one for me?", objectives = "" }
WordHunterWoW_QuestEN[31671] = { title = "Why Not Scallions?", description = "I heard Haohan mentioning that he was going to plant scallions today. I'm not sure if today's the best day for scallions, but I'd like to hope that he knows what he's doing. He is the head of the Tillers' union, after all.\n\nCould you plant a scallion for me?", objectives = "" }
WordHunterWoW_QuestEN[31672] = { title = "A Pumpkin-y Perfume", description = "I heard a rumor around the market that Gina Mudclaw loves the smell of pumpkin blossoms. Maybe if I grow some pumpkins in my farm, she might come and visit a little more often.\n\nCould you plant a pumpkin for me?", objectives = "" }
WordHunterWoW_QuestEN[31673] = { title = "Red Blossom Leeks, You Make the Croc-in' World Go Down", description = "Grandpa once told me that the smell of leeks will keep crocolisks off of your property. He must have had a point... he always grew leeks, and I never saw a crocolisk anywhere NEAR his farm.\n\nWe're pretty far from the water... but I suppose you can never be too sure.", objectives = "" }
WordHunterWoW_QuestEN[31674] = { title = "The Pink Turnip Challenge", description = "Old Hillpaw bet me that my land couldn't grow a pink turnip.\n\nI'll show him. My land will grow the biggest, pinkest turnip that old coot's ever seen!", objectives = "" }
WordHunterWoW_QuestEN[31675] = { title = "The White Turnip Treatment", description = "Grandpa often told me to \"Keep my drawers clean and my dirt cleaner.\" It sounds like a joke, but he makes a good point.\n\nVegetables tend to leave behind bits of root that can contaminate your soil... but a nice, big, white turnip will clean that gunk right up. Think you could plant a white turnip for me?", objectives = "" }
WordHunterWoW_QuestEN[31676] = { title = "Ancient Vengeance", description = "I can hear them howling in rage... The spirits of the Gurthani mogu I slew so long ago. They wander this ruined terrace, seeking vengeance.\n\nIf they find me in this state, I will not have the strength to fend them off. Draw their attention and put them down.\n\nFinish what I started, and I will tell you who I am.", objectives = "" }
WordHunterWoW_QuestEN[31677] = { title = "The Warlord's Ashes", description = "<Kil'ruk the Wind-Reaver defeated Warlord Gurthan centuries ago, but the mogu beastmaster's spirit continues to haunt the ruins of his old stronghold.\n\nShowing proof of your victory over this spirit may gain you favor in the eyes of the Klaxxi.>", objectives = "" }
WordHunterWoW_QuestEN[31679] = { title = "Extending Our Coverage", description = "The Klaxxi'va hear another paragon. His cries are weak and lost in darkness. The signal must be strengthened.\n\nThere is a tower in Amberglow Hollow that has been silent for many years. It must sing; the Klaxxi demand it!\n\nThis time I will go with you. You will help me repair it.\n\nTake the resonating crystal and meet me in Amberglow.", objectives = "" }
WordHunterWoW_QuestEN[31680] = { title = "Crime and Punishment", description = "The Stinging Trail nurtures young Kypari trees. The empress drains the saplings too early, outsider. They must grow before the amber can be taken.\n\nThe Klaxxi'va demand punishment for this crime! It will please them if you rain death on the Ik'thik harvesters.", objectives = "" }
WordHunterWoW_QuestEN[31681] = { title = "Better With Age", description = "It is a crime to harvest the young trees, but a much bigger crime to waste the amber.\n\nYoung amber is not as strong, but the Klaxxi need it to continue the fight. We will bring them more and they will sing my praises!\n\nGather the young amber. We will store it until it is aged and can be consumed.", objectives = "" }
WordHunterWoW_QuestEN[31682] = { title = "By the Sea, Nevermore", description = "The Klaxxi'va have spoken to me, outsider. The paragon is hidden in the Briny Muck only, he is not so hidden anymore.\n\nThe lizard men surround him. He cannot fall into their scaley hands.\n\nYou will find him; you will awaken him. Do not return without him!\n\nIf you do this the Klaxxi will be pleased with us. ", objectives = "" }
WordHunterWoW_QuestEN[31685] = { title = "Valley of the Four Winds", description = "Yarr, the Jade Forest be goin through some violent reconstruction, but the Valley of the Four Winds is ripe for explorin.  Talk with me when ye be ready to go and I can give ye a ride ta where ya need to go.  Talk to me cohort on the other side 'ta get some equipment to aid ya on yer journey.", objectives = "" }
WordHunterWoW_QuestEN[31687] = { title = "Thinning the Sik'thik", description = "For all our efforts to keep the mantid in the Dread Wastes, some have broken through, seemingly intent on Niuzao Temple. My men have been attempting to extinguish their presence to the west, at Sik'vess, but to no success. If you're half of the {class} Taran paints you to be, maybe you will fare better.\n\nHead west, and kill any Sik'thik mantid you find. And remember, this is no time for mercy. There are lives at the temple depending on us.", objectives = "" }
WordHunterWoW_QuestEN[31688] = { title = "The Search for Restless Leng", description = "One of my best scouts, Restless Leng, went missing during a mission on the other side of Sik'vess. I'm hopeful that he was captured rather than killed, but with the mantid corrupted so heavily by sha, it doesn't seem likely.\n\nStill, can you investigate the cages around Sik'vess? I owe him a more thorough search than even this, but I have no men to spare without allowing our southern lines to break.\n\nPlease, {class}, even if there's no life left in him, find him that I might know his fate.", objectives = "" }
WordHunterWoW_QuestEN[31689] = { title = "The Dreadsworn", description = "The Klaxxi see far and hear much. They have shared their insight with me.\n\nThe Vor'thik embrace the sha, using its power to fuel their march in this false swarm. Their warriors consume tainted amber and call themselves dreadsworn.\n\nThere is no future for them. They are waste which needs disposing.\n\nAnd YOU will begin that process for us when you reach Kypari Vor.", objectives = "" }
WordHunterWoW_QuestEN[31690] = { title = "Inscribed Tiger Staff", description = "As powerful it is, at some point you know you will outgrow this staff.  When that time comes, one of the Inkmasters in the Arboretum would most likely be interested in taking it from you.", objectives = "" }
WordHunterWoW_QuestEN[31691] = { title = "Inscribed Crane Staff", description = "As powerful it is, at some point you know you will outgrow this staff.  When that time comes, one of the Inkmasters in the Arboretum would most likely be interested in taking it from you.", objectives = "" }
WordHunterWoW_QuestEN[31692] = { title = "Inscribed Serpent Staff", description = "As powerful it is, at some point you know you will outgrow this staff.  When that time comes, one of the Inkmasters in the Arboretum would most likely be interested in taking it from you.", objectives = "" }
WordHunterWoW_QuestEN[31693] = { title = "Julia Stevens", description = "Think you can take me again?", objectives = "" }
WordHunterWoW_QuestEN[31695] = { title = "Beyond the Wall", description = "We received word the Shado-Pan have begun a counter attack in to Townlong Steppes. It sounds like they are going after the root of the yaungol invasion.\n\nThe pandaren have not traveled in force in to Townlong for thousands of years. The Shado-Pan are strong and brave, but they are also proud and few. They will need help from heroes like yourself. Can you travel through the Gate of Winter's Blossom in the northwest? Find the Shado-Pan leaders and lend your help and experience?", objectives = "" }
WordHunterWoW_QuestEN[31698] = { title = "Thinning The Pack", description = "The past few seasons have been plentiful, and as a result, the wild tiger population on Windward Isle has exploded.\n\nThe savage creatures have hunted out all the nearby game, and are beginning to encroach upon the cloud serpent nests.\n\nAs a result, as the tigers thrive, the cloud serpents decline.\n\nIf we are not careful, the predatory cats could completely wipe them out.\n\nWe must thin the tigers' numbers, {race}.", objectives = "" }
WordHunterWoW_QuestEN[31699] = { title = "Sprite Fright", description = "Oh bother, how am I supposed to get my tasks done, now?\n\nInstructor Skythorn asked me to go kill some tigers at Windward Isle, but I heard the area was overrun with sprites!\n\nUgh! I hate sprites! They totally give me the creeps!\n\nThey're so small, and... and... they jump on you and... and... they have cold, dead little stick hands!\n\nAuuugh! You have to help me, {name}. Get rid of those things, please!", objectives = "" }
WordHunterWoW_QuestEN[31700] = { title = "The Shoe Is On The Other Foot", description = "I loathe sprites! One time, one of those nasty buggers followed me all day, putting dirt in my tea and bugs in my hair.\n\nI mean, who does that!?\n\nWell, I think it's time for a little payback. Do you know what the sprites up at Windward Isle love more than anything in the world?\n\nYeah, you guessed it. Shoes!\n\nAnd we're going to steal them. Won't that make them mad! Hah!\n\nWell, I'm scared to go near sprites, so you'll have to do it, {name}. ", objectives = "" }
WordHunterWoW_QuestEN[31701] = { title = "Dark Huntress", description = "I have learned that a vicious beast, a Windward Huntress, terrorizes the wood on the northwest side of the island.\n\nShe has already slain several serpents, and injured more than one serpent rider sent to subdue her.\n\nShe must be removed before she can pose a danger to anyone else. Can you perform this task?", objectives = "" }
WordHunterWoW_QuestEN[31702] = { title = "On The Prowl", description = "I have heard report of a great white beast that stalks the wood on the northwestern side of the wild serpent island.\n\nThis savage creature is mate to the Windward Huntress, and already he has taken down several of the adult cloud serpent matriarchs.\n\nWe cannot have such a fearsome predator roaming the island unchecked.\n\nGo and deal with this creature. Let us see if your training has paid off.", objectives = "" }
WordHunterWoW_QuestEN[31703] = { title = "Madcap Mayhem", description = "There is another task I must ask of you.\n\nThe leader of the woodland sprites is the Shadowfae Madcap.\n\nIf there is trouble brewing, he is the mastermind pulling the puppet strings.\n\nWe do not have time to deal with the sprites' tiresome pranks and insolence. Take out the Shadowfae Madcap, and be quick about it.", objectives = "" }
WordHunterWoW_QuestEN[31704] = { title = "Pooped", description = "<Your serpent catches your gaze and ducks its head bashfully.>\n\nYou can tell that someone has gotten out of its pen and had \"an accident.\"\n\nWell, at the rate that the hatchling's been eating, it had to come out the other end... somewhere.\n\nYou had better find the serpent's poop and clean it up before the Serpent Masters find out.", objectives = "" }
WordHunterWoW_QuestEN[31705] = { title = "Needle Me Not", description = "The Arboretum is our home, a safe haven where we raise young hatchlings and train our students.\n\nUnfortunately, there are other, more dangerous creatures who wish to make this their home as well.\n\nTo the north, beyond the river, we have seen a great wasp feeding on the nectar blossoms.\n\nThis creature has already stung several of our students.\n\nUse this honey to lure the wasp out of hiding. Then, destroy it before it harms anyone else.", objectives = "" }
WordHunterWoW_QuestEN[31706] = { title = "Weeping Widows", description = "The spiders near Sri-La Village have grown very aggressive. They pose a severe problem to the anglers who fish along the coast.\n\nFor their safety, I need you to go and eliminate the Weeping Widows in The Widow's Wail.\n\nYou can find the cave along the coast to the north.", objectives = "" }
WordHunterWoW_QuestEN[31707] = { title = "A Tangled Web", description = "We have had a disturbing report from the Anglers fishermen of Sri-La Village, {name}.\n\nMany of their villagers are missing, taken by the spiders who live in The Widow's Wail, a cave along the coast to the north.\n\nThe victims are dragged into the dark depths, wrapped in cocoons, and left to become the spiders' next meal.\n\nWe believe that some of the people may still be alive. There is still time to save them! I need you to go and rescue as many villagers as you can find.", objectives = "" }
WordHunterWoW_QuestEN[31708] = { title = "Serpent's Scale", description = "I see you have gained your own hatchling, {race}.\n\nHave you been feeding it, cleaning after it, and playing with it properly? Only by doing so will it become strong and healthy.\n\nNow let me tell you a trainer's secret. To the north, in The Widow's Wail, you can find a mushroom known as Serpent's Scale.\n\nIt is difficult to acquire, but this mushroom has powerful properties and important nutrients. Your serpent won't like eating it, but who likes eating their vegetables?", objectives = "" }
WordHunterWoW_QuestEN[31709] = { title = "Lingering Doubt", description = "I heard that there has been some strange behavior down at The Widow's Wail to the north.\n\nHyacinth and I went to investigate, and I am certain that some presence of the sha has found its way into the cavern.\n\nI created this device to measure sha energy levels.\n\nIf you are going that way, would you mind taking measurements of any sha disturbances?\n\nThe disturbances look like streams of white and black sha energy pouring from the ground.", objectives = "" }
WordHunterWoW_QuestEN[31710] = { title = "Tiny Treats", description = "As you near, your serpent opens its mouth and begins drooling. It looks quite hungry since you last left it.\n\nFrom the way it whimpers and slaps its tail, you can tell it is not looking for just any treat, but a special favorite snack.\n\nYour serpent loves to munch on tiny spider eyes, but this delicacy comes only from the Widowspawn spiders in the cave along the coast to the north.\n\nWell, what's a rider to do? Your serpent is waiting.", objectives = "" }
WordHunterWoW_QuestEN[31711] = { title = "The Seed of Doubt", description = "The problem with the sha of doubt, {race}, is its deceitful pervasiveness.\n\nOnce the seed of doubt is planted, it can grow like an unwelcome weed.\n\nSuch a seed has been planted in The Widow's Wail to the north, and like a weed, we must extinguish its presence immediately.\n\nI need you to destroy the lingering fragment of doubt before it can infect any more victims.", objectives = "" }
WordHunterWoW_QuestEN[31712] = { title = "Monkey Mischief", description = "Strange tales have reached our ears from Sri-La Village.\n\nIt seems that a hozen tribe has made itself comfortable in Oona Kagu, a cave along the coast south of the fishing village.\n\nToo comfortable, in fact. The tribe members are stealing and pillaging resources all along the coast.\n\nWe must teach them a lesson... one that can only be taught by force. They have already overstayed their welcome.", objectives = "" }
WordHunterWoW_QuestEN[31713] = { title = "The Big Brew-haha", description = "It's a disaster, {name}!\n\nWhen I went to visit the Dancing Serpent Inn yesterday, they were all out of brew. They said the shipment from Sri-La Village had been stolen. STOLEN!\n\nTurns out those Oona hozen have been making all kinds of trouble down at the docks, including taking all the brew to their cave at Oona Kagu along the coast.\n\nI can't handle a dry spell. A life without brew is not a life worth living!\n\nSomeone needs to go and save the brew!", objectives = "" }
WordHunterWoW_QuestEN[31714] = { title = "Saving the Serpents", description = "Those Oona hozen have gone too far this time.\n\nDo you know what they are doing with wild cloud serpents? Captured hatchlings are forced to fight one another in the pits, for nothing more than the Oona's amusement.\n\nSavages!\n\nIf the young hatchlings learn such aggressive behavior at a young age, they may become violent and corrupted adults. A malicious cloud serpent is not something we want to deal with.\n\nWe must save the hatchlings.", objectives = "" }
WordHunterWoW_QuestEN[31715] = { title = "The Big Kah-Oona", description = "The leader of the Oona hozen is a brigand by the name of Lord Oona.\n\nI have heard fearsome tales of this roaming sea captain and his crew. Everywhere he takes his tribe, destruction follows.\n\nThe Oona land their boats on fertile soil, pillage the local villages, and drain the land dry before moving on to their next conquest.\n\nWe shall not allow the same to occur on our shores, not while I am still in charge.\n\nI need someone to go eradicate him now.", objectives = "" }
WordHunterWoW_QuestEN[31716] = { title = "Pooped", description = "<As you approach the pen, the serpent zips into a corner and hides.>\n\nAs it looks at you with bashful eyes, you can tell that someone has gotten out of its pen and had... an accident.\n\nWell, at the rate that the serpent's been eating, it had to come out the other end... somewhere.\n\nYou had better find the serpent's poop and clean it up before the Serpent Masters find out.", objectives = "" }
WordHunterWoW_QuestEN[31717] = { title = "The Trainer's Challenge: Ace Longpaw", description = "You are rising up the ranks of our students, {name}.\n\nJust as a sword must be forged through fire, so must our students test themselves against one another.\n\nToday, you will spar against one of our brightest disciples, Ace Longpaw. In order to defeat him, you will need to make use of your defensive capabilities.\n\nSpeak to him in the training ring to begin the challenge. Good luck.", objectives = "" }
WordHunterWoW_QuestEN[31718] = { title = "The Trainer's Challenge: Big Bao", description = "Are you ready for another lesson, {name}?\n\nToday, you will spar against Big Bao. He is large of stature and of heart, and he will not give up until he is wholly beaten.\n\nIf you wish to defeat him, you will need to persevere.\n\nSpeak to him in the training ring to begin the challenge. Good luck.", objectives = "" }
WordHunterWoW_QuestEN[31719] = { title = "The Trainer's Challenge: Ningna Darkwheel", description = "You show much promise, {name}. However, talent is worth little without discipline and humility.\n\nToday, you will face Ningna Darkwheel. Her natural strength makes her one of our most talented students. \n\nIf you hope to defeat her, you will need to act with the utmost control.\n\nSpeak to her in the training ring to begin the challenge. Good luck.", objectives = "" }
WordHunterWoW_QuestEN[31720] = { title = "The Trainer's Challenge: Suchi the Sweet", description = "Today you will face Suchi the Sweet in the training ring. Despite her sweet exterior, she is a tough opponent.\n\nShe attacks swiftly and surely, but such potent attacks can become tiring over time.\n\nIf you hope to defeat her, you will need to concentrate your damage when she is weakened.\n\nSpeak to Suchi to begin the duel. Good luck.", objectives = "" }
WordHunterWoW_QuestEN[31721] = { title = "The Trainer's Challenge: Qua-Ro Whitebrow", description = "Qua-Ro Whitebrow is commonly considered the best student of the Order.\n\nHe seems quite without weakness. He is quick of intellect, strong of arm, hard-working, and talented.\n\nWhen you face him in the training ring, you will be testing yourself against our best.\n\nSpeak to him to begin the duel. No matter the outcome, you will learn much from challenging him.", objectives = "" }
WordHunterWoW_QuestEN[31723] = { title = "Valley of the Four Winds", description = "Yarr, the Jade Forest be goin through some violent reconstruction, but the Valley of the Four Winds is ripe for explorin.  I can help ye on yer way if ye wants to explore it.  Be sure to check out me wares for some equipment that may help ye on yer journey.", objectives = "" }
WordHunterWoW_QuestEN[31724] = { title = "Old MacDonald", description = "You're tough for just starting out!\n\nOld MacDonald taught me everything I know about battling. I think fighting him would be a great learning experience for you!\n\nHe can be found just across the bridge leading to Westfall. Don't let his age fool you, he's already beaten quite a few up-and-coming trainers like yourself.", objectives = "" }
WordHunterWoW_QuestEN[31725] = { title = "Lindsay", description = "Are you ready to show off what you can do? There's a little girl up in Redridge Mountains that has made a real storm on the battle scene.\n\nFind Lindsay at the dock at Camp Everstill. She may be young, but her impressive record is nothing to be scoffed at!", objectives = "" }
WordHunterWoW_QuestEN[31726] = { title = "Eric Davidson", description = "I heard all my friends talking about a scary worgen called Eric Davidson in Duskwood that nobody ever fights with their pets.\n\nI bet if you found and beat him, people might talk about you instead!", objectives = "" }
WordHunterWoW_QuestEN[31727] = { title = "Gambling Problem", description = "If this war is to be won we cannot afford to leave anything unchecked, outsider.\n\nThere is a disturbance along the coast that needs to be investigated. The presence there is not our kind and are of no value to us. However, their supplies could prove very valuable.\n\nIf there is anything of use there we must get to it before the empress.", objectives = "" }
WordHunterWoW_QuestEN[31728] = { title = "Bill Buckler", description = "My longtime friend, fellow trainer, and infamous drunkard Bill Buckler of the Cape of Stranglethorn, has issued an open challenge to prepared trainers!\n\nYou should answer his call and really put your skills to the test. He tends to wander the southern roads of the Cape.", objectives = "" }
WordHunterWoW_QuestEN[31729] = { title = "Steven Lisbane", description = "If you thought I was tough, prepare yourself. The road only gets harder from here.\n\nFind Steven Lisbane wandering the roads in the southern parts of Northern Stranglethorn. Seek him out and see who the superior tamer is!", objectives = "" }
WordHunterWoW_QuestEN[31730] = { title = "A Not So Friendly Request", description = "Scouts have reported a non-mantid presence near Kor'vess. Their intrusion and their theft of amber would normally be dealt with swiftly, but our forces are needed elsewhere.\n\nThis task seems suited to you, Wakener. You will convince them to leave this land, or you will destroy them in the name of the Klaxxi'va.", objectives = "" }
WordHunterWoW_QuestEN[31732] = { title = "Unleash Hell", description = "I will NOT let the Horde gain a foothold on these shores before we do! If you're looking to jump into the fray, I've got a spare gyrocopter for you at the end of the runway. An attack run is already programmed in, all you have to do is concentrate on shooting.\n\nUnleash hell upon these orcs!", objectives = "" }
WordHunterWoW_QuestEN[31733] = { title = "Touching Ground", description = "Their town is burning and their men are scattered and broken. I need every available man on the ground NOW to finish them off.\n\nGrab one of the parachutes on the edge of the ship and get down there!", objectives = "" }
WordHunterWoW_QuestEN[31734] = { title = "Welcome Wagons", description = "Did you see the size of those war wagons? They're packing so many explosives, I cannae tell if the Horde is here to take over this continent or just blow it out of the sea!\n\nWe need to neutralize those wagons before they leave Garrosh'ar Point.\n\nHere, take me pocket flares. Fire 'em into a wagon and watch the fireworks!", objectives = "" }
WordHunterWoW_QuestEN[31735] = { title = "The Right Tool For The Job", description = "I've scouted the area and found no leads on the prince or Admiral Taylor. We need to neutralize this base quickly and continue our search elsewhere.\n\nOperations here are being led by an orc warlock; Ga'trul. He's barricaded the dock and is trying to escape through a demonic circle.\n\nPut that flaregun to work again and blow those barricades! I'll cover your back and move in when you reach Ga'trul.", objectives = "" }
WordHunterWoW_QuestEN[31736] = { title = "Envoy of the Alliance", description = "North of this base is a cherry blossom orchard and a village tucked away behind it. We will need to quarter there and tend to our wounded while we plan our next move.\n\nHead to that village and make contact with the native leader. Agent Mishka and I will rendezvous with you there.\n\nBe courteous, {name}! I am authorizing you to represent the entire Alliance here.\n\nI'm banking that seeing a powerful Alliance hero like you should make a favorable impression.", objectives = "" }
WordHunterWoW_QuestEN[31737] = { title = "The Cost of War", description = "This whole place is going up in flames and the Skyfire is reporting that more of those... shadows are crawling up out of the ground. We need to get our people out of here.\n\nClear a path through the base on your way north and head for the town. I will rendezvous with you there.", objectives = "" }
WordHunterWoW_QuestEN[31738] = { title = "Pillaging Peons", description = "How did my village become a battlefield?\n\nTo the west, your Horde enemies cut down our precious orchard. Without our apple trees, we will have no harvest, no food, and no livelihood.\n\nIf you are truly different than this Horde, show us! Help us protect our grove by killing those who defile the land.", objectives = "" }
WordHunterWoW_QuestEN[31739] = { title = "Priorities!", description = "Those \"orc\" things ransacked the brewery and made off with my family's finest barrels of cider.\n\nI know there is a war out there, but I am not a brewer who will stand idly by while his prized vintage is chugged by undeserving lips.\n\nThe \"Horde\" will likely put up some resistance. Why don't you put that weapon to good use and help me recover my cider?", objectives = "" }
WordHunterWoW_QuestEN[31740] = { title = "Koukou's Rampage", description = "We have more than just our cellars to worry about.\n\nKoukou, our beloved mushan, has gone crazy! Just look at him!\n\nI've tried cajoling and pleading and yelling and soothing, but nothing has worked.\n\nI'm afraid he is no longer of his own mind. There is only one way to save him, and our brewery.\n\nStrike swift and sure. He will not feel a thing.", objectives = "" }
WordHunterWoW_QuestEN[31741] = { title = "Twinspire Keep", description = "I do not trust this Horde. They wield foul magic, and their intentions are clearly malevolent. We can no longer stand their presence in Twinspire Keep, so close to Paw'don.\n\nI beg you, visitor: thin their numbers before they do something awful to this village.", objectives = "" }
WordHunterWoW_QuestEN[31742] = { title = "Fractured Forces", description = "The Horde have made our jobs easier for us. Their infighting and segregation have split their camp in two: orcs in the west, and undead in the east.\n\nThe orcs obey their commander Dalgan, while the undead follow Bellandra Felstorm, a powerful warlock. Hopefully, their internal squabbles will be enough of a distraction that you'll be able to sneak in there and kill both of them. Sully has already infiltrated the ruins; find him inside when you are done.", objectives = "" }
WordHunterWoW_QuestEN[31743] = { title = "Smoke Before Fire", description = "Sully scouted the Horde establishment to the north, and he reports seeing a large pile of explosives, along with a small force of demolishers. That's not to mention the demons that their warlocks have summoned.\n\nLuckily, we came prepared. We've got air support from the Skyfire. We just need to show our pilots where to strike.\n\n<Rell hands you a smoke flare, and gives you a knowing nod.>", objectives = "" }
WordHunterWoW_QuestEN[31744] = { title = "Unfair Trade", description = "Though we have only just met, we have a common enemy: this group called the \"Horde.\"\n\nSeveral days ago, their leader made us a trade offer. When we refused, his servants abducted several of our cubs as bargaining chips.\n\nWe have called in the Shado-Pan to help, but they are in Kun-Lai Summit, a journey of several days. Can you come to our aid?", objectives = "" }
WordHunterWoW_QuestEN[31745] = { title = "Onward and Inward", description = "\"Sha\" energy, hm? Tread carefully, {name} - there's a hidden darkness to this continent.\n\nWe'll stay behind to mop up the rest of the Horde, but we need you to continue with the main mission: the rescue of Captain Taylor, and the retrieval of Prince Anduin.\n\nOur aerial scouts think we've found the wreckage of the flagship near Paw'don Village. Go there and report to Admiral Rogers for instructions.\n\nYou are welcome to use my gyrocopter.", objectives = "" }
WordHunterWoW_QuestEN[31752] = { title = "Blingtron 4000", description = "", objectives = "" }
WordHunterWoW_QuestEN[31754] = { title = "Cannonfire", description = "Those mogu cannons up on the Golden Stair are bombarding us from a distance. Sure would be nice if they somehow spontaneously broke, don't you think?", objectives = "" }
WordHunterWoW_QuestEN[31755] = { title = "Acts of Cruelty", description = "I can hear the screams of the captured soldiers and villagers up on the Golden Stair. They're torturing them!\n\nPlease, please, you have to save them!", objectives = "" }
WordHunterWoW_QuestEN[31756] = { title = "High Chance of Rain", description = "The mogu are conjuring some kind of sinister storm upon the Golden Stair. Generally, mogu and lightning are not a particularly pleasant mix. I say we stop them.\n\nYou should be able to find their Stormcaller staves pretty easily, considering the giant arcs of lightning extending up from them. Mind knocking them over or destroying them or something for me? I sure would sleep better.", objectives = "" }
WordHunterWoW_QuestEN[31757] = { title = "Unleashed Spirits", description = "The Shao-Tien have unleashed their captive tortured spirits upon us. They flood down from the Golden Stair, with no end in sight.\n\nKill as many of these unleashed spirits as you can. They are fragile, but if you are not alert, they can easily overrun you.\n\nGood luck.", objectives = "" }
WordHunterWoW_QuestEN[31758] = { title = "Laosy Scouting", description = "Lao Softfoot got himself captured again up on the Golden Stair. I'm not going to make any excuses for him, he's a lousy rogue.\n\nWe probably shouldn't just leave him there though. Could you go find him?", objectives = "" }
WordHunterWoW_QuestEN[31760] = { title = "Striking First", description = "The mogu are empowering some giant stone monstrosity up on the Golden Stair, with the sure intent of unleashing it upon us.\n\nHow about you go and let them know our opinion on the matter? Make sure the point strikes home.", objectives = "" }
WordHunterWoW_QuestEN[31762] = { title = "Crumbling Behemoth", description = "The mogu have succeeded in empowering an enormous stone statue with the intent of unleashing it upon us.\n\nIn response, I would like to unleash you upon it.\n\nIt approaches from the Golden Stair. Bring it to its knees...", objectives = "" }
WordHunterWoW_QuestEN[31765] = { title = "Paint it Red!", description = "They shot out our engines and we floated here - HERE! Right in the firing line of the enemy!\n\nYou know what to do, {name}. Get below decks and man those guns!\n\nShow these scum that they're in OUR line of fire!", objectives = "" }
WordHunterWoW_QuestEN[31766] = { title = "Touching Ground", description = "Nazgrim has taken command of the ground assault and has requested that you be sent to meet up with him immediately.\n\nWe have several rappelling ropes setup near the guns. Fastest way down you're going to find, save the one that ends poorly.", objectives = "" }
WordHunterWoW_QuestEN[31767] = { title = "Finish Them!", description = "We've softened them up. Now it's time to finish them off!\n\nThat fortress must be cleansed of Alliance, and we've got nowhere to keep any prisoners.\n\n<The hint of a smile crosses Nazgrim's face.>\n\nYou know what to do, {name}. The cowards will run if you give them the chance.\n\nSee that you don't!\n", objectives = "" }
WordHunterWoW_QuestEN[31768] = { title = "Fire Is Always the Answer", description = "It's not enough that we destroy their forces. Nothing must be left for them to salvage!\n\nTake this flare-gun and fire it into their munitions stockpiles. Leave them nothing!", objectives = "" }
WordHunterWoW_QuestEN[31769] = { title = "The Final Blow!", description = "We've learned that their captain has barricaded himself in above us.\n\nThe coward allowed his forces to die while he hid from our fury! Typical Alliance! No matter. He cannot delay his fate any longer.\n\nI will scale the walls with my marines while you lead a frontal assault up the ramps. Use your flare gun on munitions near the barricades to blast your way through.\n\nWe will meet you up top and destroy this pathetic excuse for a captain together!", objectives = "" }
WordHunterWoW_QuestEN[31770] = { title = "You're Either With Us Or...", description = "The assistance of the nearby village has now become a necessity, {name}.\n\nWe will need to use the village to regroup and tend to our wounded.\n\nPerhaps the villagers will join our cause after seeing the brutality unleashed by the alliance.\n\nYou will act as envoy for the Horde. Ensure the cooperation of their leader. Do not disappoint me!", objectives = "" }
WordHunterWoW_QuestEN[31771] = { title = "Face to Face With Consequence", description = "I do not know the history of this war that you fight, and I am not interested. This land responds to negative energy in kind. The hatreds, doubt, and violence you have brought here now ooze out of Pandaria like blood from an open wound.\n\nYour actions have wrought havoc all over these ruins! Clean up after yourself and meet me in the village below - I will do my best to explain what is happening here.", objectives = "" }
WordHunterWoW_QuestEN[31772] = { title = "Priorities!", description = "Just look at this mess! All that brew gone to waste!\n\nTaran Zhu warned us against speaking to you outsiders, but I'll take any help I can get.\n\nWe were on our way to Dawn's Blossom when the fighting broke out. Now all of our brew has been lost!\n\nYou want to make it up to us? Maybe you can find some of our Honeybrew barrels that haven't been broken. Then it wouldn't be a complete loss.", objectives = "" }
WordHunterWoW_QuestEN[31773] = { title = "Prowler Problems", description = "The animals have all gone crazy!\n\nNormally the prowlers steer clear of the village, but now we can't seem to keep them away. I've never seen them act this way before!\n\nThe mayor has summoned in the Shado-Pan, but they're not all here yet. Can you take care of those prowlers before they maul one of our farmers?", objectives = "" }
WordHunterWoW_QuestEN[31774] = { title = "Seeking Zin'jun", description = "Rivett claims to have seen Zin'jun abandon ship with the rest of the survivors. That means he's still out there somewhere.\n\nWe can't leave him behind. He could be injured or worse yet, captured!\n\nGo track down Zin'jun and bring him back.", objectives = "" }
WordHunterWoW_QuestEN[31775] = { title = "Assault on the Airstrip", description = "I have found their hidden airfield, {name}: the Strongarm Airstrip. It wasn't hard to spot, it's swarming with Alliance.\n\n<Nazgrim spits.>\n\nThey think they've wiped us out, but we're Horde! We fight until we're corpses... and sometimes even afterwards. Let them taste our steel!", objectives = "" }
WordHunterWoW_QuestEN[31776] = { title = "Strongarm Tactics", description = "Scouting reports from the Strongarm Airstrip are in, and I've underlined a few high-priority targets for you.\n\nTwo gnomish mechanics have been keeping Alliance gyrocopters in the air. Take out the mechanics, and the gyrocopters' numbers will dwindle.\n\nA dwarven death knight wanders their perimeter. He's an adventurer like yourself - loosely allied and highly dangerous.\n\nFinally, a name I recognize: Corporal Jackson Silver. He's a hero of the Alliance and a deadshot with a crossbow.\n\nGood luck, {name}.", objectives = "" }
WordHunterWoW_QuestEN[31777] = { title = "Choppertunity", description = "I spotted some shoulder-mounted rocket launchers on the way over here.\n\nThey mighta been fireworks. I dunno. I'm just going to assume that they were shoulder-mounted rocket launchers until I'm proven wrong.\n\nPoint is, in the arms of a skilled {class} like you, they could probably take down a chopper. If you find any lying around, try pointing them at those poorly-built gyrocopters.", objectives = "" }
WordHunterWoW_QuestEN[31778] = { title = "Unreliable Allies", description = "We originally welcomed the Alliance as friends. Several of our villagers volunteered to help them build an airstrip. Only recently, however, did it become clear to us that they were building a war base, within shouting distance of our village.\n\nWhat's worse - I fear that some villagers are being held against their will. If you find them, {class}, let them know that it is time to come home.", objectives = "" }
WordHunterWoW_QuestEN[31779] = { title = "The Darkness Within", description = "You didn't see Captain Doren while you were out there, did you?\n\nThat sniveling Alliance leader must be in hiding somewhere. If he wasn't in that airbase, he can't be far. Search the perimeter - try searching the cave southwest of the main airfield. I want the Alliance gone from here!", objectives = "" }
WordHunterWoW_QuestEN[31780] = { title = "Old MacDonald", description = "I won't be such a pushover this time around!", objectives = "" }
WordHunterWoW_QuestEN[31781] = { title = "Lindsay", description = "Think you can take me again?  I'm always up for challenge!", objectives = "" }
WordHunterWoW_QuestEN[31782] = { title = "Overthrone", description = "The council is in harmony, wakener.\n\nOur ritual will bring about the demise of the empress and allow us to secure the future of our great empire.\n\nBehold the power of the Klaxxi!", objectives = "" }
WordHunterWoW_QuestEN[31785] = { title = "Level Up!", description = "Good, good. It's important to keep your pets healthy and ready for battle.\n\nMy next task for you is to fight a few battles and raise a pet to level 3.  Once you do that, come back and see me and we can talk about catching your own pets!", objectives = "" }
WordHunterWoW_QuestEN[31786] = { title = "Pristine Manacles of Rebellion", description = "This artifact has been restored to a remarkably excellent condition.  Perhaps you will put it on display at the Seat of Knowledge, so that lorewalkers and archaeologists can study it.", objectives = "" }
