WordHunterWoW_QuestEN[31834] = { title = "Begin Your Training: Master Cheng", description = "Greetings, {name}. Welcome to the Peak of Serenity.  It is here that we monks train and hone our skills in the martial arts.  The time has come for you to begin your training.  Speak with Master Cheng in the Training Grounds below us to begin.", objectives = "" }
WordHunterWoW_QuestEN[31835] = { title = "Continue Your Training: Master Kistane", description = "Welcome back {name}, the time has come for the next step of your training.  Speak with Master Kistane in the Training Grounds below us for your next lesson.\n", objectives = "" }
WordHunterWoW_QuestEN[31836] = { title = "Continue Your Training: Master Yoon", description = "Welcome back {name}, the time has come for the next step of your training.  Speak with Master Yoon in the Training Grounds below us for your next lesson.\n", objectives = "" }
