WordHunterWoW_QuestEN[31840] = { title = "Practice Makes Perfect: Master Cheng", description = "Welcome Back, {name}. I see you've returned to hone your skills.  Speak with Master Cheng in the Training Grounds below us for a practice sparring session.", objectives = "" }
WordHunterWoW_QuestEN[31842] = { title = "Practice Makes Perfect: Master Kistane", description = "Welcome Back, {name}. I see you've returned to hone your skills.  Speak with Master Kistane in the Training Grounds below us for a practice sparring session.", objectives = "" }
