WordHunterWoW_QuestEN[31846] = { title = "Practice Makes Perfect: Master Hsu", description = "Welcome Back, {name}. I see you've returned to hone your skills.  Speak with Master Hsu in the Training Grounds below us for a practice sparring session.", objectives = "" }
WordHunterWoW_QuestEN[31847] = { title = "Better Dead than Dread", description = "I am sure many of our associates will be requesting your services after your victory here. But I have received a request for aid from our defenders at the wall along the Dread Wastes.\n\nIf you would assist them, then take a kite and check in with Bowmistress Li.\n", objectives = "" }
WordHunterWoW_QuestEN[31850] = { title = "Eric Davidson", description = "Ah, so you've braved the woods again to face me in battle. I accept your brazen challenge to my vicious spawn.", objectives = "" }
WordHunterWoW_QuestEN[31851] = { title = "Bill Buckler", description = "So ye've come fer another round, have ye?\n\nI'll show ya why they be callin' me the shcourge o' the vale!", objectives = "" }
WordHunterWoW_QuestEN[31852] = { title = "Steven Lisbane", description = "You dare to challenge me again? This time, I do believe our battle is going to sway in my favor!", objectives = "" }
WordHunterWoW_QuestEN[31853] = { title = "All Aboard!", description = "You hear all of that, {name}? There are Alliance that need killing and I need to round up a veteran crew.\n\nYou're coming with me!\n\nWe won't be returning until our assignment's complete, so round up your things and make ready.\n\nI'll be aboard a newly commissioned gunship over Bladefist Bay.\n\nDon't keep me waiting!", objectives = "" }
WordHunterWoW_QuestEN[31854] = { title = "Analynn", description = "I see you have once again found me. I presume you wish to do battle once more? Yes, let's.", objectives = "" }
WordHunterWoW_QuestEN[31856] = { title = "The Peak of Serenity - Begin Your Training", description = "The time has come for you to venture to the Peak of Serenity to begin training in the ways of the Monk.  Use Zen Pilgrimage to go there and speak with Master Hight when you arrive.", objectives = "" }
WordHunterWoW_QuestEN[31857] = { title = "The Peak of Serenity - Continue Your Training", description = "The time has come for you to return to the Peak of Serenity to continue your training.  Use Zen Pilgrimage to return there and speak with Master Hight when you arrive.", objectives = "" }
WordHunterWoW_QuestEN[31858] = { title = "The Peak of Serenity - Continue Your Training", description = "The time has come for you to return to the Peak of Serenity to continue your training.  Use Zen Pilgrimage to return there and speak with Master Hight when you arrive.", objectives = "" }
WordHunterWoW_QuestEN[31859] = { title = "The Peak of Serenity - Continue Your Training", description = "The time has come for you to return to the Peak of Serenity to continue your training.  Use Zen Pilgrimage to return there and speak with Master Hight when you arrive.", objectives = "" }
WordHunterWoW_QuestEN[31860] = { title = "The Peak of Serenity - Continue Your Training", description = "The time has come for you to return to the Peak of Serenity to continue your training.  Use Zen Pilgrimage to return there and speak with Master Hight when you arrive.", objectives = "" }
WordHunterWoW_QuestEN[31861] = { title = "The Peak of Serenity - Continue Your Training", description = "The time has come for you to return to the Peak of Serenity to continue your training.  Use Zen Pilgrimage to return there and speak with Master Hight when you arrive.", objectives = "" }
WordHunterWoW_QuestEN[31862] = { title = "Zonya the Sadist", description = "The prey be walkin' to the predator's territory, unaware of the danger that he is in. You be givin' Zonya no trouble dis time.", objectives = "" }
WordHunterWoW_QuestEN[31870] = { title = "Cassandra Kaboom", description = "Cassandra Kaboom is a fierce tamer, known for her mechanical pets. She should serve as the next step on your journey to greatness.\n\nFind her in Southern Barrens near the Frazzlecraz Motherlode and challenge her. Beating Cassandra will surely prove yourself in the eyes of Varzok.\n\nGood luck.", objectives = "" }
WordHunterWoW_QuestEN[31871] = { title = "Traitor Gluk", description = "You beat Gluk before, but now Gluk lay da smackdown on puny {race}!", objectives = "" }
WordHunterWoW_QuestEN[31872] = { title = "Merda Stronghoof", description = "Just as the land continues to grow, my team is stronger than ever. Are you sure you wish to combat me? There is no shame in admitting defeat now.", objectives = "" }
WordHunterWoW_QuestEN[31876] = { title = "The Inkmasters of the Arboretum", description = "I have heard that the Inkmasters at the Arboretum are in need of aid from a scribe of great skill.  You should speak with Inkmaster Wei, if you wish to help.", objectives = "" }
WordHunterWoW_QuestEN[31877] = { title = "The Inkmasters of the Arboretum", description = "I have heard that the Inkmasters at the Arboretum are in need of aid from a scribe of great skill.  You should speak with Inkmaster Wei, if you wish to help.", objectives = "" }
WordHunterWoW_QuestEN[31878] = { title = "Audrey Burnhep", description = "I'm afraid I have nothing left to teach you, {name}. However, your journey as a trainer is far from over!\n\nReport to Audrey Burnhep in Stormwind. She has connections with many of Azeroth's finest trainers, and will help you grow further.", objectives = "" }
WordHunterWoW_QuestEN[31879] = { title = "Audrey Burnhep", description = "I'm afraid I have nothing left to teach you, {name}. However, your journey as a trainer is far from over!\n\nReport to Audrey Burnhep in Stormwind. She has connections with many of Azeroth's finest trainers, and will help you grow further.", objectives = "" }
