WordHunterWoW_QuestEN[31885] = { title = "Varzok", description = "I'm afraid I have nothing left to teach you, {name}. However, your journey as a trainer is far from over!\n\nReport to Varzok in Orgrimmar. He has connections with many of Azeroth's finest trainers, and will help you grow further.", objectives = "" }
WordHunterWoW_QuestEN[31886] = { title = "Dread Space", description = "Shado-Pan marksmen keep a constant watch over the Dread Wastes from the top of the Serpent's Spine. They would surely welcome the aid of a skilled {class} such as yourself.\n\nTake a kite and check in with Bowmistress Li.", objectives = "" }
WordHunterWoW_QuestEN[31889] = { title = "Battle Pet Tamers: Kalimdor", description = "Now that you've had a real chance to hone your skills, you're ready to venture out into the world of pet battles in full.\n\nThere are five tamers throughout Kalimdor that I'd like you to defeat: Traitor Gluk in Feralas, Grazzle the Great in Dustwallow Marsh, Kela Grimtotem in Thousand Needles, Zoltan in Felwood, and Elena Flutterfly in Moonglade.\n\nIf you are able to best them, you will be ready to venture further.", objectives = "" }
WordHunterWoW_QuestEN[31891] = { title = "Battle Pet Tamers: Kalimdor", description = "Now that you've had a real chance to hone your skills, you're ready to venture out into the world of pet battles in full.\n\nThere are five tamers throughout Kalimdor that I'd like you to defeat: Traitor Gluk in Feralas, Grazzle the Great in Dustwallow Marsh, Kela Grimtotem in Thousand Needles, Zoltan in Felwood, and Elena Flutterfly in Moonglade.\n\nIf you are able to best them, you will be ready to venture further.", objectives = "" }
WordHunterWoW_QuestEN[31894] = { title = "A Delicate Balance", description = "The calling to be a Shado-pan is one to bring balance and harmony to this land. It is our duty to ensure balance is maintained, {name}.\n\nThe yaungol activity in Townlong is threatening this balance and must be stopped before it is too late.\n\nWe've had sightings of yaungol in the Sumprushes. The reports indicate they are attacking the mist lurkers in the area. Find out why and put an end to it! ", objectives = "" }
WordHunterWoW_QuestEN[31895] = { title = "Better Off Dread", description = "It's time we go to the source, {name}!\n\nShado-Pan marksmen keep a constant watch over the Dread Wastes from the top of the Serpent's Spine. They would surely welcome the aid of a skilled {class} such as yourself.\n\nSeek out Bowmistress Li atop the Serpent's Spine on the border of Dread Wastes.", objectives = "" }
WordHunterWoW_QuestEN[31897] = { title = "Grand Master Trixxy", description = "Word around the master tamers in Kalimdor is you're the new hotshot that's making such a buzz. Why don't you come down to my training grounds in the Ice Thistle Hills in Winterspring so I can show you how it's done?", objectives = "" }
WordHunterWoW_QuestEN[31902] = { title = "Battle Pet Tamers: Eastern Kingdoms", description = "Now that you've had a real chance to hone your skills, you're ready to venture out into the world of pet battles in full.\n\nThere are five tamers throughout the Eastern Kingdoms that I'd like you to defeat: David Kosse in The Hinterlands, Deiza Plaguehorn in Eastern Plaguelands, Kortas Darkhammer in Searing Gorge, Everessa in Swamp of Sorrows, and Kortas' brother, Durin Darkhammer, in Burning Steppes.\n\nIf you are able to best them, you will be ready to venture further.", objectives = "" }
WordHunterWoW_QuestEN[31903] = { title = "Battle Pet Tamers: Eastern Kingdoms", description = "Now that you've had a real chance to hone your skills, you're ready to venture out into the world of pet battles in full.\n\nThere are five tamers throughout the Eastern Kingdoms that I'd like you to defeat: David Kosse in The Hinterlands, Deiza Plaguehorn in Eastern Plaguelands, Kortas Darkhammer in Searing Gorge, Everessa in Swamp of Sorrows, and Kortas' brother, Durin Darkhammer, in Burning Steppes..\n\nIf you are able to best them, you will be ready to venture further.", objectives = "" }
WordHunterWoW_QuestEN[31904] = { title = "Cassandra Kaboom", description = "I've loaded my pets with new gyrotechnic training modules. You're going down!", objectives = "" }
WordHunterWoW_QuestEN[31905] = { title = "Grazzle the Great", description = "You're back?! You're just asking to get eaten by a black dragon!", objectives = "" }
WordHunterWoW_QuestEN[31906] = { title = "Kela Grimtotem", description = "You're so bold as to venture into the heart of Grimtotem lands once more to challenge me? You will regret your decision!", objectives = "" }
WordHunterWoW_QuestEN[31907] = { title = "Zoltan", description = "With each passing day my power grows. Resistance is futile.", objectives = "" }
WordHunterWoW_QuestEN[31908] = { title = "Elena Flutterfly", description = "I see you're ready for another bout in the skies. Let's take flight!", objectives = "" }
WordHunterWoW_QuestEN[31909] = { title = "Grand Master Trixxy", description = "Freeze! You've finally warmed up from our last encounter, have you? Let's change that.", objectives = "" }
WordHunterWoW_QuestEN[31910] = { title = "David Kosse", description = "My research has helped my training regimen greatly. I will defeat you this time.", objectives = "" }
WordHunterWoW_QuestEN[31911] = { title = "Deiza Plaguehorn", description = "You have not yet turned to the true path of undeath. Perhaps another battle will show you the way.", objectives = "" }
WordHunterWoW_QuestEN[31912] = { title = "Kortas Darkhammer", description = "I hear that you fought my fool of a brother. He lost, eh?\n\nLooks like this is my time to shine!", objectives = "" }
WordHunterWoW_QuestEN[31913] = { title = "Everessa", description = "I believe I'm figuring out the secrets of this place. Soon I will be unstoppable!", objectives = "" }
WordHunterWoW_QuestEN[31914] = { title = "Durin Darkhammer", description = "My time under the Firelord has prepared me fer anything. Nothing you can throw at me will deter me!", objectives = "" }
WordHunterWoW_QuestEN[31915] = { title = "Grand Master Lydia Accoste", description = "The master tamers around the Eastern Kingdoms have been talking about you. You think yourself unstoppable? You believe that you are the true grand master?\n\nCome, then, {name}. I await you in Deadwind Pass. Come, and know the crushing defeat that's always been yours.", objectives = "" }
WordHunterWoW_QuestEN[31916] = { title = "Grand Master Lydia Accoste", description = "You wish to face me again? You will regret this decision!", objectives = "" }
WordHunterWoW_QuestEN[31917] = { title = "A Tamer's Homecoming", description = "Yer ready to enter the full circuit of pet battlin', matey. Go back to yer trainer, Mish Burnhep, in Stormwind, and prepare for the adventure of a lifetime!", objectives = "" }
WordHunterWoW_QuestEN[31918] = { title = "A Tamer's Homecoming", description = "If you beat me, then you must be ready for da big time! Go talk to Varzok in Orgrimmar.", objectives = "" }
WordHunterWoW_QuestEN[31919] = { title = "Battle Pet Tamers: Outland", description = "You've bested the master tamers of Kalimdor and the Eastern Kingdoms, but your next challenge will be far more trying.\n\nThere are four tamers in Outland that you must now defeat: Nicki Tinytech in Hellfire Peninsula, Ras'an in Zangarmarsh, Narrok in Nagrand, and Morulu the Elder in Shattrath.\n\nYou must defeat them to proceed on the path to greatness.", objectives = "" }
WordHunterWoW_QuestEN[31920] = { title = "Grand Master Antari", description = "I've seen the likes of you before. A young, naive tamer that thinks that they deserve victory handed to them on a silver platter.\n\nWell no more! I will be your reckoning, {class}. I, Bloodknight Antari of Shadowmoon Valley, await the chance to show you how it feels to be obliterated in battle.", objectives = "" }
WordHunterWoW_QuestEN[31921] = { title = "Battle Pet Tamers: Outland", description = "You've bested the master tamers of Kalimdor and the Eastern Kingdoms, but your next challenge will be far more trying.\n\nThere are four tamers in Outland that you must now defeat: Nicki Tinytech in Hellfire Peninsula, Ras'an in Zangarmarsh, Narrok in Nagrand, and Morulu the Elder in Shattrath.\n\nYou must defeat them to proceed on the path to greatness.", objectives = "" }
WordHunterWoW_QuestEN[31922] = { title = "Nicki Tinytech", description = "According to my calculations, I have a 32.333% chance of victory. I'll take it!", objectives = "" }
WordHunterWoW_QuestEN[31923] = { title = "Ras'an", description = "You want to fight again? I think I've gotten better!", objectives = "" }
WordHunterWoW_QuestEN[31924] = { title = "Narrok", description = "I wish to do battle once more. These young ones need to grow stronger.", objectives = "" }
WordHunterWoW_QuestEN[31925] = { title = "Morulu The Elder", description = "I have learned much since our last encounter. Do you wish to test your skills once more?", objectives = "" }
WordHunterWoW_QuestEN[31926] = { title = "Grand Master Antari", description = "You capitalized on my mistake last time and emerged victorious. This time, you will not be so fortunate, {race}.", objectives = "" }
WordHunterWoW_QuestEN[31927] = { title = "Battle Pet Tamers: Northrend", description = "Outland's finest have fallen to your skill, but Northrend now awaits you!\n\nThere are four tamers that you must now defeat: Beegle Blastfuse in Howling Fjord, Nearly Headless Jacob in Crystalsong Forest, Okrut Dragonwaste in Dragonblight, and Gutretch in Zul'Drak.\n\nIf you are able to best all of them, then Northrend's Grand Master will surely challenge you!", objectives = "" }
WordHunterWoW_QuestEN[31928] = { title = "Grand Master Payne", description = "In my opinion, my fellow tamers have been far too lenient on your training.\n\nTrue pet taming requires militaristic discipline. I shall honor you with the pleasure of seeing firsthand what that discipline can produce.\n\nCome to the Argent Tournament Grounds in Icecrown and see firsthand what you could become!", objectives = "" }
WordHunterWoW_QuestEN[31929] = { title = "Battle Pet Tamers: Northrend", description = "Outland's finest have fallen to your skill, but Northrend now awaits you!\n\nThere are four tamers that you must now defeat: Beegle Blastfuse in Howling Fjord, Nearly Headless Jacob in Crystalsong Forest, Okrut Dragonwaste in Dragonblight, and Gutretch in Zul'Drak.\n\nIf you are able to best all of them, then Northrend's Grand Master will surely challenge you!", objectives = "" }
WordHunterWoW_QuestEN[31930] = { title = "Battle Pet Tamers: Pandaria", description = "You must now face the toughest tamers in all of Azeroth, {name}. They make their home in Pandaria, training ground of the grand masters.\n\nThere are six grand masters left to defeat: Hyuna of the Shrines in The Jade Forest, Farmer Nishi in Valley of the Four Winds, Mo'ruk in Krasarang Wilds, Courageous Yon in Kun-Lai Summit, Seeker Zusshi in Townlong Steppes, and Wastewalker Shu in Dread Wastes.\n\nIf you think yourself ready, seek out these champions of the trade and prove yourself!", objectives = "" }
WordHunterWoW_QuestEN[31931] = { title = "Beegle Blastfuse", description = "One of my chickens flew for just a moment yesterday, I swear. We're finally hitting the big time!\n\nOh, you'd like to battle again?", objectives = "" }
WordHunterWoW_QuestEN[31932] = { title = "Nearly Headless Jacob", description = "Time and time again you defy my wisdom. What is it that brings you back to these woods?\n\nAh, you wish to do battle once more. Very well then.", objectives = "" }
WordHunterWoW_QuestEN[31933] = { title = "Okrut Dragonwaste", description = "You dare interrupt our work? Then you must battle me again! Take out your pets, and I'll give you a taste of Hellscream's wrath!", objectives = "" }
WordHunterWoW_QuestEN[31934] = { title = "Gutretch", description = "Me like fighting you. You not so easy like the others. We fight again?", objectives = "" }
WordHunterWoW_QuestEN[31935] = { title = "Grand Master Payne", description = "The rebel {class} comes once again to test his might again that of a Grand Master. Your bravery will be your undoing this time!", objectives = "" }
WordHunterWoW_QuestEN[31936] = { title = "The \"Jinyu Princess\" Irrigation System", description = "<The back of the box features a caricature of a jinyu maiden surrounded by marketing copy.>\n\n\"Hey there, greenthumb. Are you pouting over parched pumpkins? Crying over crusty cabbage? Are your leeks lame and your melons melancholy?\n\nThen it's time you brought home the Jinyu Princess! She'll wash over your garden like a sweet spring rain, dousing that drought with a deep draught of...\"\n\n<It goes on like this for six paragraphs.>", objectives = "" }
WordHunterWoW_QuestEN[31937] = { title = "\"Thunder King\" Pest Repellers", description = "<An imposing image of a mogu face dominates this box, casting its gaze downward at neatly ordered rows of bold text.>\n\n\"DO NOT LET WEAK, DISGUSTING INSECTS INFEST YOUR GLORIOUS CROPS. CONQUER THEM WITH THE MIGHT OF THE THUNDER KING AND PROTECT YOUR LEGACY.\"\n\n<The rest of the space is dedicated to cartoon depictions of various insects crying out in lament or fleeing in terror.>", objectives = "" }
WordHunterWoW_QuestEN[31938] = { title = "The \"Earth-Slasher\" Master Plow", description = "<The box art depicts a pandaren farmer of impossible physique standing proudly astride a widening rift in the earth, a mighty plow in his grasp. Cubs wrestle playfully on his shoulders and dangle from his muscular arms.\n\nAt his side, a stoic female - of equally impossible physique - balances a massive, overflowing cornucopia gracefully on her head while kicking a virmen in the face.>\n\n\"The Earth-Slasher. Master the land. Master your life.\"", objectives = "" }
WordHunterWoW_QuestEN[31941] = { title = "Squash Those Foul Odors", description = "Grandpa always said, \"A squash a week, and your tail won't reek.\"\n\n<Yoon subtly sniffs the air.>\n\nYup. I think it's been about a week. Could you help me plant a Jade Squash?", objectives = "" }
WordHunterWoW_QuestEN[31942] = { title = "It's Melon Time", description = "<Farmer Yoon looks up at the sky and sniffs the air.>\n\nHmm...\n\n<He licks his paw and holds it up in the air, sticks a toenail into the soil, and then inspects the length of his shadow.>\n\nYup. It's melon time.\n\nCould you grab some seeds and help me plant a Striped Melon?", objectives = "" }
WordHunterWoW_QuestEN[31943] = { title = "Which Berries? Witchberries.", description = "That young'un over there, Andi, is going to grow up to be a heck of a farmer some day. I can tell just by lookin' at him.\n\nI think I'll plant him some witchberries. Kids love witchberries - it'll be a nice surprise.", objectives = "" }
WordHunterWoW_QuestEN[31944] = { title = "Complete Your Training: The Final Test", description = "Welcome back, {name}.  The time has come for you to complete the last step of your training.  Head to the Training Grounds for your final test.", objectives = "" }
WordHunterWoW_QuestEN[31945] = { title = "Learn and Grow VI: Gina's Vote", description = "My business is doomed! You see all of the Ironpaws at their cooking stations?\n\nTheir tasty dishes draw many of the customers to this market, but they're all out of scallions!\n\nIt may not look like much, but the scallion is an essential cooking ingredient. Without it, foods are less savory, less flavorful, and less aromatic.\n\nThis is terrible. I'm not getting another scallion shipment for a week!\n\nWait a second. You're a farmer, aren't you? You think you could help me?", objectives = "" }
WordHunterWoW_QuestEN[31946] = { title = "Mung-Mung's Vote III: The Great Carrot Caper", description = "Mung-Mung don't care who steals carrots. Only care what Mr. Mudclaw does to poor Mung-Mung when he finds his crop is ruined!\n\n<Mung-Mung rubs his chin thoughtfully.>\n\nWait! Mung-Mung have bright idea. You go and grow some juicycrunch carrots. Then, we take your carrots and pretend they are Mr. Mudclaw's.\n\nYes!", objectives = "" }
WordHunterWoW_QuestEN[31947] = { title = "Farmer Fung's Vote III: Crazy For Cabbage", description = "<Farmer Fung is beaming with a radiant smile.>\n\nThanks to you, I got my precious yaks back! Unfortunately, I noticed that their time out in the wild left them rather gaunt.\n\nThey must be starving, but I don't feed my prize yaks just any regular old grass.\n\nNo sir, they eat only the leafiest green cabbages you can find here in the Valley.\n\nMy stores are a bit low. If you bring me some cabbages for my yaks, I will reward you handsomely.", objectives = "" }
WordHunterWoW_QuestEN[31948] = { title = "Nana's Vote II: The Sacred Springs", description = "You caught me at a good time, {name}. I was just hankering to make a fresh batch of Witchberry Julep.\n\nHave you ever heard of this wondrous brew?\n\nEach sip takes ten years off your face! How do you think I still look so good?\n\nAnyway, I need a special ingredient - thousand-year water - which can be collected from the mouth of the waterfall to the north.\n\nI'm afraid the journey is too treacherous for an old matron like me, but if you can get your hands on a pitcher, I'll let you share my brew.", objectives = "" }
WordHunterWoW_QuestEN[31949] = { title = "Nana's Vote III: Witchberry Julep", description = "Now that we have the water, I can almost taste the icy cold witchberry julep!\n\nNow, we just need to find ourselves some sweet witchberries.\n\nMy grandson's berries this season have been total slop, so I need to seek a decent harvest elsewhere.\n\nSay, do you have any witchberries in the ground this year? How about you bring me some from your farm?\n\nIf your berries are up to the standard, we'll make ourselves a grand old batch of the old juice!", objectives = "" }
WordHunterWoW_QuestEN[31951] = { title = "Grand Master Aki", description = "You have fought hard and well against the trainers of Azeroth. Even the grand masters have fallen to your cunning tactics.\n\nI now await you in the Vale of Eternal Blossoms, for you have earned the privilege to face me in battle. Come, {name}, and let us see if you have what it takes to defeat me.", objectives = "" }
WordHunterWoW_QuestEN[31952] = { title = "Battle Pet Tamers: Pandaria", description = "You must now face the toughest tamers in all of Azeroth, {name}. They make their home in Pandaria, training ground of the grand masters.\n\nThere are six grand masters left to defeat: Hyuna of the Shrines in The Jade Forest, Farmer Nishi in Valley of the Four Winds, Mo'ruk in Krasarang Wilds, Courageous Yon in Kun-Lai Summit, Seeker Zusshi in Townlong Steppes, and Wastewalker Shu in Dread Wastes.\n\nIf you think yourself ready, seek out these champions of the trade and prove yourself!", objectives = "" }
WordHunterWoW_QuestEN[31953] = { title = "Grand Master Hyuna", description = "You seek to do battle once more? Very well, it will strengthen me to better protect the sacred sites of my people.", objectives = "" }
WordHunterWoW_QuestEN[31954] = { title = "Grand Master Mo'ruk", description = "This time I'm gonna do the beating! You watch!", objectives = "" }
WordHunterWoW_QuestEN[31955] = { title = "Grand Master Nishi", description = "My pets continue to grow in strength thanks to the fertile land we train on. You don't stand a chance!", objectives = "" }
WordHunterWoW_QuestEN[31956] = { title = "Grand Master Yon", description = "If you think I am going to let you walk away with another victory in hand, you are sorely mistaken. This time, I will stand over you as the superior trainer!", objectives = "" }
